function randomCode($length)
    {

        $validCharacters = "0123456789";
        $validCharNumber = strlen($validCharacters);
        $result = "";
        for ($i = 0; $i < $length; $i++) {
            $index = random_int(0, $validCharNumber - 1);
            $result .= $validCharacters[$index];
        }
        return $result;
    }

