| ==============================Util functions=================================
*/



public function addDSAMaster()
{
    $tableName = "";
    $columName = "";
    $user = $this->request->auth;
   
    $this->validate($this->request, [
        'name' => 'required',
        'type' => 'required',
    ]);

    $masterType = $this->request->type;
   
    if ($masterType == 'agent_type') {
        $tableName = 'dsa_front_m_agent_type';
        $columName = 'agent_type';
    } else if ($masterType == 'bank_account_type') {
        $tableName = 'dsa_front_m_bank_account_type';
        $columName = 'bank_account_type';
    } else if ($masterType == 'constitution_type') {
        $tableName = 'dsa_front_m_constitution_type';
        $columName = 'constitution_type';
    } else if ($masterType == 'event_type') {
        $tableName = 'dsa_front_m_event_type';
        $columName = 'event_type';
    } else if ($masterType == 'event_type_mode') {
        $tableName = 'dsa_front_m_event_type_mode';
        $columName = 'event_type_mode';
    } else if ($masterType == 'partner_type') {
        $tableName = 'dsa_front_m_partner_type';
        $columName = 'partner_type';
    } else if ($masterType == 'resident_type') {
        $tableName = 'dsa_front_m_recident_type';
        $columName = 'recident_type';
    } else if ($masterType == 'resource_center') {
        $tableName = 'dsa_front_m_resource_center';
        $columName = 'resource_center';
    } else if ($masterType == 'highest_qualification') {
        $tableName = 'dsa_front_m_highest_qualification';
        $columName = 'highest_qualification';
    } else if ($masterType == 'profession') {
        $tableName = 'dsa_front_m_profession';
        $columName = 'profession';
    } else if ($masterType == 'relationship') {
        $tableName = 'dsa_front_m_relationship';
        $columName = 'relationship';
    } else if ($masterType == 'scheme') {
        $tableName = 'dsa_front_m_scheme';
        $columName = 'scheme_name';
    }  else if ($masterType == 'category') {
        $tableName = 'dsa_front_m_category';
        $columName = 'category_name';
    } 

    try {
        DB::table($tableName)->insert([
            $columName => $this->request->name,
            'created_by'=>1,
            'created_at' => Carbon::now() 
        ]);
        return response()->json([
            'error'=>false,
            'message' => 'Record added.'
        ], 200);
    } catch (\Exception $e) {
        dd($e->getMessage());
        $errorCode = $e->errorInfo[1];
        if ($errorCode == 1062 || $errorCode == 2627) {
            return response()->json([
                'error'=>true,
                'message' => 'Record already added.'
            ], 400);
        }
        return response()->json([
            'error'=>true,
            'message' => 'Record not added, Please try again.'
        ], 400);
    }
}


public function updateDSAMaster()
{
    $tableName = "";
    $columName = "";

    $user = $this->request->auth;
 
    $this->validate($this->request, [
        'name' => 'required',
        'id' => 'required',
        'type' => 'required',
    ]);

    $masterType = $this->request->type;

    if ($masterType == 'agent_type') {
        $tableName = 'dsa_front_m_agent_type';
        $columName = 'agent_type';
        $id='type_id';
    } else if ($masterType == 'bank_account_type') {
        $tableName = 'dsa_front_m_bank_account_type';
        $columName = 'bank_account_type';
        $id='bank_type_id';
    } else if ($masterType == 'constitution_type') {
        $tableName = 'dsa_front_m_constitution_type';
        $columName = 'constitution_type';
        $columnId='cid';
    } else if ($masterType == 'event_type') {
        $tableName = 'dsa_front_m_event_type';
        $columName = 'event_type';
        $columnId='event_type_id';
    } else if ($masterType == 'event_type_mode') {
        $tableName = 'dsa_front_m_event_type_mode';
        $columName = 'event_type_mode';
        $columnId='event_mode_id';
    } else if ($masterType == 'partner_type') {
        $tableName = 'dsa_front_m_partner_type';
        $columName = 'partner_type'; 
        $columnId='partner_type_id';
    } else if ($masterType == 'resident_type') {
        $tableName = 'dsa_front_m_recident_type';
        $columName = 'recident_type';
        $columnId='rt_id';
    } else if ($masterType == 'issues_resource_center') {
        $tableName = 'dsa_front_m_resource_center';
        $columName = 'resource_center';
        $columnId='rc_id';
    } else if ($masterType == 'highest_qualification') {
        $tableName = 'dsa_front_m_highest_qualification';
        $columName = 'highest_qualification';
        $columnId='hid';
    }else if ($masterType == 'profession') {
        $tableName = 'dsa_front_m_profession';
        $columName = 'profession';
        $columnId='pid';
    } else if ($masterType == 'relationship') {
        $tableName = 'dsa_front_m_relationship';
        $columName = 'relationship'; 
        $columnId='rm_id';
    } else if ($masterType == 'scheme') {
        $tableName = 'dsa_front_m_scheme';
        $columName = 'scheme_name'; 
        $columnId='sid';
    } else if ($masterType == 'category') {
        $tableName = 'dsa_front_m_category';
        $columName = 'category_name';
        $columnId='category_id';
    } 

    try {

        $isRecordFound=DB::table($tableName)
        ->where($columnId, $this->request->id) 
        ->where('is_deleted',0)
        ->select()
        ->first();

        if($isRecordFound==null){
            return response()->json([
                'error'=>false,
                'message' => 'Record not found.'
            ], 200);
        }

        DB::table($tableName)
            ->where($columnId, $this->request->id)
            ->update([
                $columName => $this->request->name,
                'updated_by'=>1,
                'updated_at' => Carbon::now()
            ]);

            return response()->json([
            'error'=>false,
            'message' => 'Record updated.'
        ], 200);
    } catch (\Exception $e) {
        dd($e->getMessage());
        $errorCode = $e->errorInfo[1];
        if ($errorCode == 1062 || $errorCode == 2627) {
            return response()->json([
            'error'=>true,
                'message' => 'Record already exist.'
            ], 400);
        }
        return response()->json([
            'error'=>true,
            'message' => 'Record not updated, please try again.'
        ], 400);
    }
}

public function deleteDSAMasterById()
{
    $tableName = "";

    $user = $this->request->auth;
 
    $this->validate($this->request, [
        'id' => 'required',
        'type' => 'required',
    ]);

    $masterType = $this->request->type;

    if ($masterType == 'agent_type') {
        $tableName = 'dsa_front_m_agent_type';
        $id='type_id';
    } else if ($masterType == 'bank_account_type') {
        $tableName = 'dsa_front_m_bank_account_type';
        $id='bank_type_id';
    } else if ($masterType == 'constitution_type') {
        $tableName = 'dsa_front_m_constitution_type';
        $columnId='cid';
    } else if ($masterType == 'event_type') {
        $tableName = 'dsa_front_m_event_type';
        $columnId='event_type_id';
    } else if ($masterType == 'event_type_mode') {
        $tableName = 'dsa_front_m_event_type_mode';
        $columnId='event_mode_id';
    } else if ($masterType == 'partner_type') {
        $tableName = 'dsa_front_m_partner_type';
        $columnId='partner_type_id';
    } else if ($masterType == 'resident_type') {
        $tableName = 'dsa_front_m_recident_type';
        $columnId='rt_id';
    } else if ($masterType == 'issues_resource_center') {
        $tableName = 'dsa_front_m_resource_center';
        $columnId='rc_id';
    } else if ($masterType == 'highest_qualification') {
        $tableName = 'dsa_front_m_highest_qualification';
        $columnId='hid';
        
    }else if ($masterType == 'profession') {
        $tableName = 'dsa_front_m_profession';
        $columnId='pid';
       
    } else if ($masterType == 'relationship') {
        $tableName = 'dsa_front_m_relationship';
        $columnId='rm_id';
       
    } 
    else if ($masterType == 'scheme') {
        $tableName = 'dsa_front_m_scheme';
        $columnId='sid';
    } 
    else if ($masterType == 'category') {
        $tableName = 'dsa_front_m_category';
        $columnId='category_id';
    }

    try {

        $isRecordAlreadyDeleted= DB::table($tableName)
        ->where($columnId, $this->request->id)
        ->where('is_deleted',1)
        ->select()
        ->first();

         if($isRecordAlreadyDeleted){
            return response()->json([
                'error'=>true,
                'message' => 'Record already deleted.'
            ], 200);
        }
        

        $isRecordAvailable= DB::table($tableName)
        ->where($columnId, $this->request->id)
        ->select()
        ->first();

        if($isRecordAvailable==null){
            return response()->json([
                'error'=>false,
                'message' => 'Record not found.'
                ], 200);
        }
        DB::table($tableName)
        ->where($columnId, $this->request->id)
        ->update([
            'is_deleted'=>1,
            'deleted_by'=>1,
            'deleted_at' => Carbon::now()
        ]);

            return response()->json([
            'error'=>false,
            'message' => 'Record deleted.'
        ], 200);
    } catch (\Exception $e) {
        dd($e->getMessage());
        $errorCode = $e->errorInfo[1];
        if ($errorCode == 1062 || $errorCode == 2627) {
            return response()->json([
            'error'=>true,
                'message' => 'Record already deleted.'
            ], 400);
        }
        return response()->json([
            'error'=>true,
            'message' => 'Record not deleted, please try again.'
        ], 400);
    }
}

public function getAllDSAMaster()
{
    $tableName = "";
    $columName = "";

    
 
    $this->validate($this->request, [
        'searchTerm' => 'nullable',
        'perPage' => 'nullable',
        'type' => 'required',
    ]);

    $masterType = $this->request->type;

   
    if ($masterType == 'agent_type') {
        $tableName = 'dsa_front_m_agent_type';
        $columName = 'agent_type';
        $columnId='type_id';
    } else if ($masterType == 'bank_account_type') {
        $tableName = 'dsa_front_m_bank_account_type';
        $columName = 'bank_account_type';
        $columnId='bank_type_id';
    } else if ($masterType == 'constitution_type') {
        $tableName = 'dsa_front_m_constitution_type';
        $columName = 'constitution_type';
        $columnId='cid';
    } else if ($masterType == 'event_type') {
        $tableName = 'dsa_front_m_event_type';
        $columName = 'event_type';
        $columnId='event_type_id';
    } else if ($masterType == 'event_type_mode') {
        $tableName = 'dsa_front_m_event_type_mode';
        $columName = 'event_type_mode';
        $columnId='event_mode_id';
    } else if ($masterType == 'partner_type') {
        $tableName = 'dsa_front_m_partner_type';
        $columName = 'partner_type'; 
        $columnId='partner_type_id';
    } else if ($masterType == 'resident_type') {
        $tableName = 'dsa_front_m_recident_type';
        $columName = 'recident_type';
        $columnId='rt_id';
    } else if ($masterType == 'issues_resource_center') {
        $tableName = 'dsa_front_m_resource_center';
        $columName = 'resource_center';
        $columnId='rc_id';
    } else if ($masterType == 'highest_qualification') {
        $tableName = 'dsa_front_m_highest_qualification';
        $columName = 'highest_qualification';
        $columnId='hid';
    }else if ($masterType == 'profession') {
        $tableName = 'dsa_front_m_profession';
        $columName = 'profession';
        $columnId='pid';
    } else if ($masterType == 'relationship') {
        $tableName = 'dsa_front_m_relationship';
        $columName = 'relationship'; 
        $columnId='rm_id';
    } else if ($masterType == 'scheme') {
        $tableName = 'dsa_front_m_scheme'; 
        $columName = 'scheme_name'; 
        $columnId='sid';
    } 
    else if ($masterType == 'category') {
        $tableName = 'dsa_front_m_category';
        $columName = 'category_name';
        $columnId='category_id';
    }
    
        $query = DB::table($tableName)
        ->Where('is_deleted',0)
        ->where(function ($query) use ($columName) {
            $query->where($columName, 'like', '%' . $this->request->searchTerm . '%')
                ->Where('is_deleted',0);
        })
        ->orderBy($columnId, 'desc');

        if($this->request->perPage)
        {
            $perPage = $this->request->perPage; 
            $list = $query->paginate($perPage);

        }
        else{
            $list = $query->get();
        }

   
 
    return response()->json($list, 200);
    
}


