public function addDSAPartner()
{
    $user = $this->request->auth;
 
        $this->validate($this->request, [
            'partnerName' => 'required',
            'typeOfAgent' => 'required',
            'phoneNo' => 'required',
            'emailId' => 'required',
            // 'schemeId' => 'required',
            // 'branchName' => 'required'
        ]);
 
        $phoneno=$this->request->phoneNo;
        $emailId=$this->request->emailId;
        $checkMobileNo = DB::table('dsa_front_m_partner')
        ->where(function ($checkMobileNo) use($phoneno,$emailId){
            $checkMobileNo->where(function($q) use($phoneno,$emailId){
                $q->where('phone_no',  $phoneno)
                ->orWhere('email_id',  $emailId);
            })->where('is_rejected','0');
        })->count();
 
        // dd($checkMobileNo);
 
 
        if($checkMobileNo == 0)
        {
 
            DB::table('dsa_front_m_partner')->insert([
                'partner_name' => $this->request->partnerName,
                'partner_type'=>$this->request->typeOfAgent,    
                'phone_no' => $this->request->phoneNo,
                'email_id'=>$this->request->emailId,  
                'scheme_id' => $this->request->schemeId,
                'branch_name'=> $this->request->branchName,
                'house_loan_selling_exp' =>  $this->request->houseLoanSellingExperience,  
                'total_lending_insurance_sales_experience' =>  $this->request->insuranceSalesExperience,  
                'other_than_DSA_RPA_business' =>  $this->request->whichOtherBusinessDo,  
                'persona_of_channel' =>  $this->request->personaOfChannel,  
                'number_of_employees_manpower' =>  $this->request->NumberOfEmployee,  
                'number_of_FIs_empanelled_with' =>  $this->request->NumberOfFI,  
                'top_3_FIs_Name' =>  $this->request->topFisName,  
                'do_you_own_a_car_or_bike' =>  $this->request->ownCar,  
                'do_you_have_builder_connects' =>  $this->request->builderConnects,  
                'total_monthly_income_in_lacs' =>  $this->request->totalMonthlyIncome,  
                'total_monthly_business_in_CR' =>  $this->request->totalMonthlyBusinessCR,  
                'is_DSA_RPA_business_the_primary_source_of_income' =>  $this->request->IsDSABusinessSourceOfIncome,  
                'income_from_DSA_RPA_business_in_lacs' =>  $this->request->incomeComingFromDSABusiness,  
                'number_of_files_processed_in_a_month' =>  $this->request->filesprocessedMonth,  
                'number_of_files_processed_for_mortgage_in_a_month' =>  $this->request->filesprocessedMortgage,
                'fisnameone'=>$this->request->fisnameone,
                'fisnametwo'=>$this->request->fisnametwo,
                'fisnamethre'=>$this->request->fisnamethre,
                'builder1'=>$this->request->builder1,
                'builder2'=>$this->request->builder2,
                'builder3'=>$this->request->builder3,
                'mentionBusiness'=>$this->request->mentionBusiness,
                'created_by' =>  $user->employee_id
            ]);
       
            return response()->json([
                'error'=>false,
                'status'=> 200,
                'message' => 'Partner details added',
            ], 200);
        }
        else {
            return response()->json([
                'error'=>true,
                'status'=> 500,
                'message' => 'Partner is already added.',
            ], 200);
        }
 
 
}

