public function getpartnerDetails()
{
    // $user = $this->request->auth;
    $this->validate($this->request, [
        'searchTerm' => 'nullable',
        'perPage' => 'nullable'
    ]);

    $query = DB::table('dsa_front_m_partner as dmp')
        ->leftJoin('dsa_front_m_scheme as dms', 'dms.sid', '=', 'dmp.scheme_id')
        ->where('dmp.deletion_flag', 0)
        ->select('dmp.*','dms.scheme_name');

        $list = $query->paginate($this->request->perPage);

       
    if (count($list)==0)
    {
        return response()->json([
            'error'=>true,
            'message' => 'No data found.',
            'status'=>500
        ], 200);
    }
    else {
        return response()->json([
            'error'=>false,
            'message' => 'data found.',
            'status'=>200,
            'data'=>$list

        ], 200);
    }



}


public function getpartnercaseDashboardList()
{ 
    $user = $this->request->auth;
    $condition="";
    $condition1="";
    if($this->request->type == 'Monthly')
    {
        $condition="and MONTH(created_at) = MONTH(NOW())";
        $condition1="and MONTH(dm.created_at) = MONTH(NOW())";
    }
    else if($this->request->type == 'Yearly')
    {
        $startDate=Carbon::now()->year.'-04-01';
        $endDate=Carbon::parse(Carbon::now())->addYears(1)->format('Y').'-03-31';
        $d1 = Carbon::parse($startDate)->format('Y-m-d');
        $d2 = Carbon::parse($endDate)->format('Y-m-d');
        $condition = "and created_at between '$d1'  and  '$d2'";
        $condition1 = "and dm.created_at between '$d1'  and  '$d2'";
    }
    else if($this->request->type == 'Range') {
        if ($this->request->fromDate && $this->request->toDate) {
            $d1 = Carbon::parse($this->request->fromDate)->format('Y-m-d');
            $d2 = Carbon::parse($this->request->toDate)->add('day', 1)->format('Y-m-d');
            $condition = "and created_at between '$d1'  and  '$d2'";
            $condition1 = "and dm.created_at between '$d1'  and  '$d2'";
        }
    }



     $applicationData = DB::select("select
     (select count(*) from dsa_m_case where case_status in ('In Progress') and created_by = $user->employee_id $condition)  as 'Under Review',
     (select count(*) from dsa_m_case where case_status in ('Approved') and created_by = $user->employee_id $condition)  as 'Agreement In Progress',
     (select count(*) from dsa_m_case where case_status in ('Completed') and created_by = $user->employee_id $condition)  as 'Onboarding',
     (select count(dm.dsa_case_id) from dsa_case_query_details as dq inner join dsa_m_case as dm on dq.dsa_case_id=dm.dsa_case_id where dq.query_type= 'External' and dq.query_status in ('Open','Reopen') and dm.created_by = $user->employee_id $condition1)  as Queries 
      ");   
 
    return response()->json([ 
            'Status'=> 200,
            'applicationData'=>$applicationData,
            'message' => 'Application Case details found',

        ], 200); 

}



public function getapplicationcaseDetails()
{
    $user = $this->request->auth;
 
    $this->validate($this->request, [ 
        'caseId' => 'nullable',
    ]); 

    $isSelectAdvisory = DB::table('dsa_front_m_partner')
    ->where('phone_no',$user->mobile)->select('onboarding_type')->get();
    // dd($isSelectAdvisory);
    if($isSelectAdvisory[0]->onboarding_type == "Select Advisory" || $isSelectAdvisory[0]->onboarding_type == "RPDIY"){
        $query = DB::table('dsa_front_m_partner as dmp')
        ->leftJoin('dsa_front_m_case_master as dcm','dcm.phone_number', '=', 'dmp.phone_no')
        ->leftJoin('dsa_front_m_highest_qualification as dmh', 'dcm.qualification', '=', 'dmh.hid')
        ->where('phone_no',$user->mobile)
        // ->where('dmp.is_rejected', 0)
                // ->where('dcm.is_rejected', 0)
                ->select('dcm.*','dmp.*',
                DB::raw('CASE WHEN dcm.pan_verify_flag=1 THEN false ELSE true END as isHardStop'),
                DB::raw('CASE WHEN dcm.pan_verify_flag=1 THEN false ELSE true END as isSendConsent'),
                'dcm.branch_name as bank_branch_name','dmh.highest_qualification as qualificationName');
        // ->select('dcm.*', 'dmp.*', 'dcm.branch_name as bank_branch_name', 'dmh.highest_qualification as qualificationName');
        // dd($query->get());
    } else {  
        $query = DB::table('dsa_front_m_case_master as dcm')
                ->leftJoin('dsa_front_m_partner as dmp', 'dcm.phone_number', '=', 'dmp.phone_no')
                ->leftJoin('dsa_front_m_highest_qualification as dmh', 'dcm.qualification', '=', 'dmh.hid')
                ->where('dcm.phone_number', $user->mobile)
                ->where('dmp.is_rejected', 0)
                ->where('dcm.is_rejected', 0)
                ->select('dcm.*','dmp.*',
                DB::raw('CASE WHEN dcm.pan_verify_flag=1 THEN false ELSE true END as isHardStop'),
                DB::raw('CASE WHEN dcm.pan_verify_flag=1 THEN false ELSE true END as isSendConsent'),
                'dcm.branch_name as bank_branch_name','dmh.highest_qualification as qualificationName');
    }
            // 'isHardStop'=>$isHardStop,
            // 'isSendConsent'=>$isSendConsent,
    $list = $query->get();

    if (count($list)==0)
    {
        return response()->json([
            'error'=>true,
            'message' => 'No data found.',
            'status'=>500,
            'data'=>[]
        ], 200);
    }
    else {

        $addressData = DB::table('dsa_front_t_case_address as dca')
        ->leftJoin('dsa_front_m_recident_type as dct','dca.resident_type', '=', 'dct.rt_id')
        ->where('dca.case_id', $list[0]->case_id)
        ->select('dca.*','dct.recident_type as residentName')->get();

        $directorData = DB::table('dsa_front_t_case_director as dcd')
        ->leftJoin('dsa_front_m_highest_qualification as dct','dcd.director_qualification', '=', 'dct.hid')
        ->leftJoin('dsa_front_m_profession as dcp','dcd.director_profession', '=', 'dcp.pid')
        ->where('dcd.case_id', $list[0]->case_id)
        ->where('dcd.deletion_flag',0)
        ->select('dcd.*','dct.highest_qualification','dcp.profession')->get();

        $referenceData = DB::table('dsa_front_t_case_reference as dcr')
        ->leftJoin('dsa_front_m_relationship as dfr','dfr.rm_id', '=', 'dcr.reference_relation')
        ->where('dcr.case_id', $list[0]->case_id)
        ->select('dcr.*','dfr.relationship')->get();

        $financialInstitutionData = DB::table('dsa_front_t_case_financial_institution as dftcfi')
        ->where('dftcfi.case_id', $list[0]->case_id)
        ->select('dftcfi.*')->get();

        return response()->json([
            'error'=>false,
            'message' => 'data found.',
            'status'=>200,
            'data'=>$list,
            'addressData'=>$addressData,
            'directorData'=>$directorData,
            'referenceData'=>$referenceData, 
            'financialInstitutionData'=> $financialInstitutionData
        ], 200);
    }



}


////Local
public function sendOTP()
{

    $this->validate($this->request, [
        'mobileNo' => 'required'
    ]);

    $checkMobileNo="";
        if($this->request->type == 'login-otp')
        {
            $checkMobileNo = DB::table('dsa_front_m_partner')
                            ->where('phone_no', $this->request->mobileNo)->count();
        }
        else if($this->request->type == 'verify-mobile-otp')
        {
            $checkMobileNo = DB::table('dsa_front_m_partner')
                            ->where('phone_no', $this->request->mobileNo)->count();
        }

        else if($this->request->type == 'verify-email-otp')
        {
            $checkMobileNo = DB::table('dsa_front_m_partner')
                            ->where('email_id', $this->request->emailId)->count(); 
        }



        if ($checkMobileNo == 0)
        {
            if($this->request->type == 'login-otp' || $this->request->type == 'verify-mobile-otp')
            {
                return response()->json([
                    'error'=>true,
                    'message' => 'Mobile number not registered.'
                ], 200);
            }
            else if($this->request->type == 'verify-email-otp')
                {
                    return response()->json([
                        'error'=>true,
                        'message' => 'Email id not registered.'
                    ], 200);
                }
            

        }
        else {
            $otp=$this->randomCode(6);

            $updateData=DB::table('dsa_front_m_partner');

            if($this->request->type == 'login-otp')
            {

               
                $updateData->where('phone_no', $this->request->mobileNo) 
                ->update([
                    'login_otp' => $otp,
                    'login_otp_time' => Carbon::now(),  
                ]);
                $this->captcha($this->request->mobileNo);
                return response()->json([
                    'status'=> 200,
                    'message' => 'OTP sent to your registered mobile number',
                    'OTP'=> env('APP_ENV') == 'local' ? $otp : '',
                    'captcha_name'=>  DB::table('dsa_front_m_partner')->where('phone_no', $this->request->mobileNo)->value('captcha_path')
                ], 200); 

            }
            else  if($this->request->type == 'verify-mobile-otp')
            {

                $updateData->where('phone_no', $this->request->mobileNo) 
                ->update([
                    'mobile_verify_otp' => $otp,
                    'verify_otp_time' => Carbon::now(),   
                ]);

                return response()->json([
                    'status'=> 200,
                     'message' => 'OTP sent to your registered mobile number',
                     'OTP'=> env('APP_ENV') == 'local' ? $otp : ''
                ], 200); 
            }
            else  if($this->request->type == 'verify-email-otp')
            {
                $updateData->where('phone_no', $this->request->mobileNo) 
                ->update([
                    'email_otp' => $otp,
                    'email_otp_time' => Carbon::now(),    
                ]);

                if (env('DSA_FRONT_EMAIL_FLAG')) {

                    $discription=  " "."This is your DSA email verfication OTP <b>".$otp ."</b>.<br/> Please don't share OTP with anyone  </b>.";
    
                    $data = [
                        'Application_No' => "", 
                        'sender1'=>'Dear user,',
                        'details' => $discription,
                        'link' => "http://localhost:4200/",
                        'detail1'=>'Thanks and Regards,',
                        'detail2'=>'Aditya Birla Housing Finance.'
                    ];
    
                 
                    $senderName = $this->request->emailId;
                    Queue::push(new DSAInitiateEmailJob(
                        $senderName,
                        explode(',', env('dsa_cc_Email')), 
                        "Email Verification", 
                        $data,
                       ));
    
    
                } 

                return response()->json([
                    'status'=> 200,
                    'message' => 'OTP sent to your registered email id',
                    'OTP'=> env('APP_ENV') == 'local' ? $otp : ''
                ], 200); 
            }

        }
}


