public function resendCaptcha()
{
    $this->validate($this->request, [
            'mobileNo' => 'required'
        ]);

        $this->captcha($this->request->mobileNo);
        return response()->json([
            'error'=>false,
            'status'=> 200,
            'message' => 'Captcha created', 
            'captcha_name'=>  DB::table('dsa_front_m_partner')->where('phone_no', $this->request->mobileNo)->value('captcha_path'),
            'captcha_image' => base64_encode(file_get_contents($this->captcha($this->request->mobileNo)))
        ], 200);  

}

    protected function jwt($mobile)
    {
        $payload = [
            'iss' => "lumen-jwt", // Issuer of the token
            'sub' => $mobile, // Subject of the token
            'iat' => time(), // Time when JWT was issued.
            'exp' => time() + 365 * 60 * 60 * 12 // Expiration time
        ];

        return JWT::encode($payload, env('JWT_SECRET'));
    }


