public function verifyOTP()
{
 
    $this->validate($this->request, [
        'mobileNo' => 'required',
        'otp' => 'required'
    ]);

    
    $checkMobileNo="";$checkCaptcha="";
    if($this->request->type == 'login-otp')
    {
        $checkMobileNo = DB::table('dsa_front_m_partner')
                        ->where('phone_no', $this->request->mobileNo)
                        ->where('is_rejected',0)
                        ->where('login_otp', $this->request->otp)->value('login_otp_time');  
        $checkCaptcha = DB::table('dsa_front_m_partner')
                        // ->where('login_captcha', $this->request->captcha)
                        ->where('login_captcha', "ABCDEF")
                        ->where('is_rejected',0)
                        ->where('login_otp', $this->request->otp)->count();  

            
    }
        $endTime = Carbon::parse($checkMobileNo)->addMinutes(59)->format('Y-m-d H:i:s');

        if ($checkMobileNo == null)
        {
            return response()->json([
                'status'=> 500,
                'message' => 'OTP is invalid, Please enter valid OTP',
                'error'=>true
            ], 200);
      
        }
        else {
           

            if($endTime < Carbon::parse(carbon::now())->format('Y-m-d H:i:s'))
            {
                return response()->json([
                    'status'=> 500,
                    'message' => 'OTP is expired' ,
                    'error'=>true
                ], 200);
            }
            else {
                if($checkCaptcha == 0)
                {
                    return response()->json([
                        'status'=> 500,
                        'message' => 'Invalid captcha' ,
                        'error'=>true,

                    ], 200);
                }  
                else{

                    if($this->request->type == 'login-otp') 
                    {
                        DB::table('dsa_front_m_partner')
                            ->where('is_rejected', 0)
                            ->where('phone_no',$this->request->mobileNo)
                            ->update([
                                'mobile_verify_otp' => $this->request->otp,
                                'verify_otp_time' => Carbon::now(),
                                'mobile_verify_flag' => 1
                            ]);
                        
                        $data = DB::table('dsa_front_m_partner')
                                ->where('phone_no', $this->request->mobileNo)
                                ->where('is_rejected',0)
                                ->where('login_otp', $this->request->otp)->get(); 

                        $token = $this->jwt($this->request->mobileNo);
                    }
                 }    
                 Log::info("DSA/ RPA Login details, Name: ". $data[0]->partner_name ." Partner Type: ".$data[0]->partner_type." Registered number: ".$data[0]->phone_no);

                return response()->json([
                    'status'=> 200,
                    'message' => 'Login Successfully',
                    'data'=>$data,
                    'token'=>$token,
                    'error'=>false,
                    'ADHAR_ENABLE' => env('ADHAR_ENABLE'),
                    'ITR_ENABLE' => env('ITR_ENABLE'),
                    'DIRECTOR_CIBIL_CONSENT_FLAG' => env('DIRECTOR_CIBIL_CONSENT_FLAG')
                ], 200); 
            }


        }




}

public function verifymobileOTP()
{

    $this->validate($this->request, [
        'mobileNo' => 'required',
        'otp' => 'required'
    ]);

    $checkMobileVerifyFlag = DB::table('dsa_front_m_partner')
                        ->where('phone_no', $this->request->mobileNo)
                        ->where('is_rejected',0)
                        ->value('mobile_verify_flag');

    if($checkMobileVerifyFlag == 1)
    {
        return response()->json([
            'status'=> 500,
            'message' => 'Mobile number already verified',
            'error'=>true
        ], 200);
    }  
    else 
    {

        if($this->request->type == 'verify-mobile-otp')
        {
            $checkMobileNo = DB::table('dsa_front_m_partner')
                            ->where('phone_no', $this->request->mobileNo)
                            ->where('is_rejected',0)
                            ->where('mobile_verify_otp', $this->request->otp)->value('verify_otp_time');  
        }
            $endTime = Carbon::parse($checkMobileNo)->addMinutes(59)->format('Y-m-d H:i:s');

            if ($checkMobileNo == null)
            {
                return response()->json([
                    'status'=> 500,
                    'message' => 'OTP is invalid, Please enter valid OTP',
                    'error'=>true
                ], 200);
        
            }
            else {
                if($endTime < Carbon::parse(carbon::now())->format('Y-m-d H:i:s'))
                {
                    return response()->json([
                        'status'=> 500,
                        'message' => 'OTP is expired' ,
                        'error'=>true
                    ], 200);
                }
                else {

                    if($this->request->type == 'verify-mobile-otp')
                    {
                        $updateData=DB::table('dsa_front_m_partner')
                                        ->where('phone_no', $this->request->mobileNo)
                                        ->where('is_rejected',0) 
                                            ->update([
                                                'mobile_verify_flag' => 1,
                                    ]);
            
                        return response()->json([
                            'status'=> 200,
                            'message' => 'Mobile No Verified',
                            'error'=>false
                        ], 200); 
                    }

                }


            }
    } 




}

public function verifyemailOTP()
{

    $this->validate($this->request, [ 
        'emailId' => 'required',
        'otp' => 'required'
    ]);

    $checkemailVerifyFlag = DB::table('dsa_front_m_partner')
                        ->where('email_id', $this->request->emailId)
                        ->where('is_rejected',0)
                        ->value('email_verify_flag');

    if($checkemailVerifyFlag == 1)
    {
        return response()->json([
            'status'=> 500,
            'message' => 'Email id is already verified',
            'error'=>true
        ], 200);
    }  
    else 
    {

        if($this->request->type == 'verify-email-otp')
        {
            $checkEmail = DB::table('dsa_front_m_partner')
                            ->where('email_id', $this->request->emailId)
                            ->where('is_rejected',0)
                            ->where('email_otp', $this->request->otp)->value('email_otp_time');  
        }
            $endTime = Carbon::parse($checkEmail)->addMinutes(59)->format('Y-m-d H:i:s');

            if ($checkEmail == null)
            {
                return response()->json([
                    'status'=> 500,
                    'message' => 'OTP is invalid, Please enter valid OTP',
                    'error'=>true
                ], 200);
        
            }
            else {
                if($endTime < Carbon::parse(carbon::now())->format('Y-m-d H:i:s'))
                {
                    return response()->json([
                        'status'=> 500,
                        'message' => 'OTP is expired' ,
                        'error'=>true
                    ], 200);
                }
                else {

                    if($this->request->type == 'verify-email-otp')
                    {
                        $updateData=DB::table('dsa_front_m_partner')
                                        ->where('email_id', $this->request->emailId) 
                                        ->where('is_rejected',0)
                                            ->update([
                                                'email_verify_flag' => 1,
                                    ]);
            
                        return response()->json([
                            'status'=> 200,
                            'message' => 'EmailId is Verified',
                            'error'=>false
                        ], 200); 
                    }

                }


            }
    } 




}




public function saveapplicationForm()
{

    $user = $this->request->auth;
    $applicationNo="";
    $saveStageCount=1;

    try {
        
        DB::beginTransaction();

        $caseStageCount=DB::table('dsa_front_m_case_master')->where('case_id', $this->request->appId)->value('stage_count');
     
        if($caseStageCount>$this->request->stageCount){
            $saveStageCount=$caseStageCount;
        }else{
            $saveStageCount=$this->request->stageCount;
        }

        if($this->request->stageCount == 1)
        {
            Log::info("Basic Details".print_r($this->request->getContent(), true));

            if($this->request->appId)
            {
                if($this->request->has('source') && $this->request->has('source') == 'RPDIY'){
                    DB::table('dsa_front_m_case_master')->where('case_id', $this->request->appId)
                    ->update([
                        'applicant_fullname' => $this->request->fullName,
                        'phone_number' => $user->mobile,
                        'email_id' => $this->request->EmailID,
                        'partner_type' => $this->request->partnerType,
                        'branch' =>$this->request->branch,
                        'pincode' =>$this->request->pincode, 
                        'constitution_type' =>$this->request->constitutionType,
                        'stage_count'=>$saveStageCount,
                        'created_at' => Carbon::now(),
                        'created_by'=>$this->request->has('employee_code') ? DB::table('master_employee')->where('employee_code',  $this->request->employee_code)->value('employee_id') : null,
                        'date_of_birth'=>$this->request->has('date_of_birth') ? $this->request->date_of_birth : null,
                        'gender'=> $this->request->has('gender') ? $this->request->gender : null
                    ]);   
                } else {
                    DB::table('dsa_front_m_case_master')->where('case_id', $this->request->appId)
                    ->update([
                        'applicant_fullname' => $this->request->fullName,
                        'phone_number' => $user->mobile,
                        'email_id' => $this->request->EmailID,
                        'partner_type' => $this->request->partnerType,
                        'branch' =>$this->request->branch,
                        'pincode' =>$this->request->pincode, 
                        'constitution_type' =>$this->request->constitutionType,
                        'stage_count'=>$saveStageCount,
                        'created_at' => Carbon::now()
                    ]);   
                }

                $fisArray = [
                    'fisnameone' => $this->request->fisnameone,
                    'fisnametwo' => $this->request->fisnametwo,
