                'consent_check'=>$this->request->consentCheck,
                'stage_count'=>$saveStageCount,
                'submitted_from_device'=>$this->request->device,
                'legal_option' => 'No'
            ]);
            $advisoryCaseData = DB::table('dsa_front_m_case_master')->where('case_id', $this->request->appId)->get(); 

            if ($advisoryCaseData[0]->created_by == null) {
                $isSelectAdvisory = true;
            } else {
                $isSelectAdvisory = false;
            }
            if(count($this->request->directorConsent)>0)
            {
                foreach ($this->request->directorConsent as $dirConcent) {
                    if($dirConcent['directorId'])
                    {
                    DB::table('dsa_front_t_case_director')->where('case_id', $this->request->appId)->where('tid',$dirConcent['directorId'])
                        ->update([
                            'cibil_consent_check' => $dirConcent['concent'],
                        ]);
                    }
                }
            }
            
            $caseSubmittedCount = DB::table('dsa_m_case')->where('mobile_no',$advisoryCaseData[0]->phone_number)->count();
            if($caseSubmittedCount == 0) {
                if ($isSelectAdvisory) {
                    $smDetails = null;
                }else {
                    $smEmployeeId = DB::table('dsa_front_m_case_master')->where('case_id', $this->request->appId)->get()[0]->created_by; 
                    $smDetails = DB::table('master_employee')->where('employee_id',$smEmployeeId)->get();
                }
                // if ($this->request->log) {
                //     dd($smDetails);
    
                // }
                if($this->request->isRpOnboard){
                    $this->addcaseRecord($this->request->appId,$isSelectAdvisory,$smDetails,$this->request->dsa_no); 
                } else {
                    $this->addcaseRecord($this->request->appId,$isSelectAdvisory,$smDetails); 
                }

            } else {
                return response()->json([
                    'Status'=> 500,
                    'message' => 'Application Case details already submitted'
                ], 200);
            }
