public function getpartnerApplicationCount()
{
      $user = $this->request->auth; 
      $condition="";
        if($this->request->type == 'Monthly')
        {
            $condition="and MONTH(created_at) = MONTH(NOW())";
        }
        else if($this->request->type == 'Yearly') 
        {
            $startDate=Carbon::now()->year.'-04-01';
            $endDate=Carbon::parse(Carbon::now())->addYears(1)->format('Y').'-03-31';
            $d1 = Carbon::parse($startDate)->format('Y-m-d');
            $d2 = Carbon::parse($endDate)->format('Y-m-d');
            $condition = "and created_at between '$d1'  and  '$d2'";
        }
        else if($this->request->type == 'Range') {

        }

        if ($this->request->fromDate && $this->request->toDate) {
            $d1 = Carbon::parse($this->request->fromDate)->format('Y-m-d');
            $d2 = Carbon::parse($this->request->toDate)->add('day', 1)->format('Y-m-d');
            $condition = "and created_at between '$d1'  and  '$d2'"; 
        }


        $all = DB::select("select count(*) as INTERESTED from dsa_front_m_case_master  where stage_count < 8  and created_by = $user->employee_id $condition");
        $submitCount = DB::select("select count(*) as APPLICATION from dsa_front_m_case_master where stage_count = 8  and created_by = $user->employee_id $condition"); 
         
        $data=[
                'Interested' => $all[0]->INTERESTED,
                'Application' => $submitCount[0]->APPLICATION, 
            ];
            return response()->json([   
                'data' => $data,
                'error' => false
            ], 200);


}

