public function getpartnerDashboardList()
{
        $user = $this->request->auth; 
        $condition="";$condition1="";$condition2="";$condition3="";    
        $newCondition="";$newCondition1="";$newCondition2="";$newCondition3="";   
        if($this->request->searchTerm)
        {
            $condition="and (dp.partner_name like '%" . $this->request->searchTerm ."%'  )";
            $condition1="and (applicant_name like '%" . $this->request->searchTerm ."%')";
            $condition2="and (dm.applicant_name like '%" . $this->request->searchTerm ."%' )";
            $newCondition3 = "and (dp.partner_name like '%" . $this->request->searchTerm ."%' )"; 
        } 

        if ($this->request->fromDate && $this->request->toDate) {
            $d1 = Carbon::parse($this->request->fromDate)->format('Y-m-d');
            $d2 = Carbon::parse($this->request->toDate)->add('day', 1)->format('Y-m-d');
            $condition = $condition." and dm.created_at between '$d1'  and  '$d2'";
            $condition1 = $condition1." and dmc.created_at between '$d1'  and  '$d2'";
            $condition2 = $condition2." and dq.created_at between '$d1'  and  '$d2'";  
            $condition3 = $condition2." and dp.created_at between '$d1'  and  '$d2'"; 
            $newCondition3 = $newCondition3." and dp.created_at between '$d1'  and  '$d2'"; 
        } 
        
        if ($this->request->partnerType) {

            $Pdata = "'" . implode ( "', '", $this->request->partnerType ) . "'";
            $condition = $condition." and dp.partner_type in ($Pdata)";
            $condition1 = $condition1." and partner_type in ($Pdata)";
            $condition2 = $condition2." and partner_type in ($Pdata)";
            $condition3= $condition3." and dp.partner_type in ($Pdata)";  
            $newCondition3 = $newCondition3." and dp.partner_type in ($Pdata)";   
        }

                
        if ($this->request->branchList) {

            $Branchdata = "'" . implode ( "', '", $this->request->branchList ) . "'";
           
            $condition = $condition." and dp.branch_name in ($Branchdata)";
            $newCondition3 = $newCondition3." and dp.branch_name in ($Branchdata)";   

            // $condition1 = $condition1." and partner_type in ($Pdata)";
            // $condition2 = $condition2." and partner_type in ($Pdata)";
            // $condition3= $condition2." and dp.partner_type in ($Pdata)";    
        } 



       
        if($this->request->filterType == 'Monthly')
        {
            $newCondition="and MONTH(dm.created_at) = MONTH(NOW())";
            $newCondition1="and MONTH(dmc.created_at) = MONTH(NOW())";
            $newCondition2="and MONTH(dq.created_at) = MONTH(NOW())";
            $newCondition3=$newCondition3." and MONTH(dp.created_at) = MONTH(NOW())";
        }
        else if($this->request->filterType == 'Yearly')
        {
            $startDate=Carbon::now()->year.'-04-01';
            $endDate=Carbon::parse(Carbon::now())->addYears(1)->format('Y').'-03-31';
            $d1 = Carbon::parse($startDate)->format('Y-m-d');
            $d2 = Carbon::parse($endDate)->format('Y-m-d');
            $newCondition = "and dm.created_at between '$d1'  and  '$d2'"; 
            $newCondition1 = "and dmc.created_at between '$d1'  and  '$d2'";
            $newCondition2 = "and dq.created_at between '$d1'  and  '$d2'";
            $newCondition3 = $newCondition3." and dp.created_at between '$d1'  and  '$d2'";
        }

        $partnerList = DB::select("select dpan.status as pan_status, dp.partner_id as id,dp.partner_name as applicant_name,dp.phone_no as mobile_no,dp.email_id,dp.branch_name,dp.sm_approve_training_consent,'' as caseId,'Partner' as status,dp.partner_type, dftrcs.status as training_module_status, dftrcs.created_at as training_m_date from dsa_front_m_partner as dp LEFT JOIN dsa_front_m_case_master dm on dp.phone_no=dm.phone_number LEFT JOIN dsa_front_m_pan_master dpan on dm.pan_number=dpan.pan_no left join dsa_front_t_resource_center_status as dftrcs on dp.phone_no=dftrcs.mobile where dp.phone_no not in (select phone_number from dsa_front_m_case_master) and dp.created_by = $user->employee_id  $newCondition3");
        $interestedList = DB::select("select dpan.status as pan_status, dp.partner_id as id,dp.partner_name as applicant_name,dp.phone_no as mobile_no,dp.email_id,dp.branch_name,dp.sm_approve_training_consent,case_id as caseId,'Application' as status,dp.partner_type,dftrcs.status as training_module_status, dftrcs.created_at as training_m_date from dsa_front_m_partner as dp     inner join  dsa_front_m_case_master as dm on dp.phone_no=dm.phone_number LEFT JOIN dsa_front_m_pan_master dpan on dm.pan_number=dpan.pan_no left join dsa_front_t_resource_center_status as dftrcs on dp.phone_no=dftrcs.mobile where dm.stage_count < 8  and dp.created_by = $user->employee_id $condition $newCondition");
        $applicationList = DB::select("select dpan.status as pan_status, dp.partner_id as id,dp.partner_name as applicant_name,dp.phone_no as mobile_no,dp.email_id,dp.branch_name,dp.sm_approve_training_consent,case_id as caseId,'Application' as status,dp.partner_type,dftrcs.status as training_module_status, dftrcs.created_at as training_m_date from dsa_front_m_partner as dp     inner join  dsa_front_m_case_master as dm on dp.phone_no=dm.phone_number LEFT JOIN dsa_front_m_pan_master dpan on dm.pan_number=dpan.pan_no left join dsa_front_t_resource_center_status as dftrcs on dp.phone_no=dftrcs.mobile where dm.stage_count = 8  and dp.created_by = $user->employee_id $condition $newCondition");
        $reviewList = DB::select("select dpan.status as pan_status,dmc.id as id,dmc.applicant_name,dmc.mobile_no,dmc.email_id,dmc.case_pincode as branch_name,dmc.dsa_case_id as caseId,'Under Review' as status,dp.sm_approve_training_consent,dp.partner_type, dftrcs.status as training_module_status, dftrcs.created_at as training_m_date  from dsa_m_case dmc left join dsa_front_t_resource_center_status as dftrcs on dmc.mobile_no=dftrcs.mobile left join dsa_front_m_partner as dp on dp.phone_no=dftrcs.mobile   LEFT JOIN dsa_front_m_case_master dm on dp.phone_no=dm.phone_number LEFT JOIN dsa_front_m_pan_master dpan on dm.pan_number=dpan.pan_no where dmc.case_status in ('In Progress')  and dmc.created_by = $user->employee_id $condition1 $newCondition1");
        $approvedList = DB::select("select dpan.status as pan_status,dmc.id as id,dmc.applicant_name,dmc.mobile_no,dmc.email_id,dmc.case_pincode as branch_name,dmc.dsa_case_id as caseId,'Agreement In Progress' as status,dp.sm_approve_training_consent,dp.partner_type,dftrcs.status as training_module_status, dftrcs.created_at as training_m_date from dsa_m_case as dmc left join dsa_front_t_resource_center_status as dftrcs on dmc.mobile_no=dftrcs.mobile left join dsa_front_m_partner as dp on dp.phone_no=dftrcs.mobile  LEFT JOIN dsa_front_m_case_master dm on dp.phone_no=dm.phone_number  LEFT JOIN dsa_front_m_pan_master dpan on dm.pan_number=dpan.pan_no where dmc.case_status in ('Approved')  and dmc.created_by = $user->employee_id $condition1 $newCondition1");
        $completedist = DB::select("select dpan.status as pan_status,dmc.id as id,dmc.applicant_name,dmc.mobile_no,dmc.email_id,dp.sm_approve_training_consent,dmc.case_pincode as branch_name,dmc.dsa_case_id as caseId,'Onboarding' as status,dp.partner_type,dftrcs.created_at as training_m_date from dsa_m_case as dmc left join dsa_front_t_resource_center_status as dftrcs on dmc.mobile_no=dftrcs.mobile left join dsa_front_m_partner as dp on dp.phone_no=dftrcs.mobile  LEFT JOIN dsa_front_m_case_master dm on dp.phone_no=dm.phone_number  LEFT JOIN dsa_front_m_pan_master dpan on dm.pan_number=dpan.pan_no where dmc.case_status in ('Completed')  and dmc.created_by = $user->employee_id $condition1 $newCondition1");
        $queryist = DB::select("select dpan.status as pan_status,dm.id as id,dm.applicant_name,dm.mobile_no,dm.email_id,dp.sm_approve_training_consent,dm.case_pincode as branch_name,dm.dsa_case_id as caseId,'Query' as status,dp.partner_type,dq.query_description, dftrcs.status as training_module_status, dftrcs.created_at as training_m_date  from dsa_m_case as dm inner join  dsa_case_query_details as dq on dm.dsa_case_id=dq.dsa_case_id left join dsa_front_t_resource_center_status as dftrcs on dm.mobile_no=dftrcs.mobile left join dsa_front_m_partner as dp on dp.phone_no=dftrcs.mobile  LEFT JOIN dsa_front_m_case_master dcm on dp.phone_no=dcm.phone_number  LEFT JOIN dsa_front_m_pan_master dpan on dcm.pan_number=dpan.pan_no where dq.query_type= 'External' and dq.query_status in ('Open','Reopen')  and dm.created_by = $user->employee_id $condition2 $newCondition2");
       
        $list; 

        $data=array();

        if($this->request->type == 'All')
        {

            if(count($partnerList)>0)
            {
                foreach ($partnerList as $value) {
                    $a=(object) [
                        'id' => $value->id,
                        'applicant_name' => $value->applicant_name,
                        'mobile_no' => $value->mobile_no,
                        'email_id' => $value->email_id,
                        'branch_name' => $value->branch_name,
                        'status' => $value->status,
                        'caseId' => $value->caseId,
                        'partner_type' => $value->partner_type,
                        'training_module_status' => $value->training_module_status,
                        'training_m_date' => $value->training_m_date,
                        'sm_approve_training_consent' => $value->sm_approve_training_consent,
                        'pan_status'=>$value->pan_status
                    ];
                    array_push($data,$a);
                }
                
            }

            if(count($interestedList)>0)
            {
                foreach ($interestedList as $value) {
                    $a=(object) [
                        'id' => $value->id,
                        'applicant_name' => $value->applicant_name,
                        'mobile_no' => $value->mobile_no,
                        'email_id' => $value->email_id,
                        'branch_name' => $value->branch_name,
                        'status' => $value->status,
                        'caseId' => $value->caseId,
                        'partner_type' => $value->partner_type,
                        'training_m_date' => $value->training_m_date,
                        'sm_approve_training_consent' => $value->sm_approve_training_consent,
                        'pan_status'=>$value->pan_status

                    ];
                    array_push($data,$a);
                }
                
            }
            if(count($applicationList)>0)
            {
                foreach ($applicationList as $value) {
                    $a=(object) [
                        'id' => $value->id,
                        'applicant_name' => $value->applicant_name,
                        'mobile_no' => $value->mobile_no,
                        'email_id' => $value->email_id,
                        'branch_name' => $value->branch_name,
                        'status' => $value->status,
                        'caseId' => $value->caseId,
                        'partner_type' => $value->partner_type,
                        'training_m_date' => $value->training_m_date,
                        'sm_approve_training_consent' => $value->sm_approve_training_consent,
                        'pan_status'=>$value->pan_status

                    ];
                    array_push($data,$a);
                }
            }
            if(count($reviewList)>0)
            {
                foreach ($reviewList as $value) {
                    $a=(object) [
                        'id' => $value->id,
                        'applicant_name' => $value->applicant_name,
                        'mobile_no' => $value->mobile_no,
                        'email_id' => $value->email_id,
                        'branch_name' => $value->branch_name,
                        'status' => $value->status,
                        'caseId' => $value->caseId,
                        'partner_type' => $value->partner_type,
                        'training_m_date' => $value->training_m_date,
                        'sm_approve_training_consent' => $value->sm_approve_training_consent,
                        'pan_status'=>$value->pan_status

                    ];
                    array_push($data,$a);
                }
            }
            if(count($approvedList)>0)
            {
                foreach ($approvedList as $value) {
                    $a=(object) [
                        'id' => $value->id,
                        'applicant_name' => $value->applicant_name,
                        'mobile_no' => $value->mobile_no,
                        'email_id' => $value->email_id,
                        'branch_name' => $value->branch_name,
                        'status' => $value->status,
                        'caseId' => $value->caseId,
                        'partner_type' => $value->partner_type,
                        'training_m_date' => $value->training_m_date,
                        'sm_approve_training_consent' => $value->sm_approve_training_consent,
                        'pan_status'=>$value->pan_status

                    ];
                    array_push($data,$a);
                }
            }
            if(count($completedist)>0)
            {
                foreach ($completedist as $value) {
                    $a=(object) [
                        'id' => $value->id,
                        'applicant_name' => $value->applicant_name,
                        'mobile_no' => $value->mobile_no,
                        'email_id' => $value->email_id,
                        'branch_name' => $value->branch_name,
                        'status' => $value->status,
                        'caseId' => $value->caseId,
                        'partner_type' => $value->partner_type,
                        'training_m_date' => $value->training_m_date,
                        'sm_approve_training_consent' => $value->sm_approve_training_consent,
                        'pan_status'=>$value->pan_status

                    ];
                    array_push($data,$a);
                }
            }
            if(count($queryist)>0)
            {
                foreach ($queryist as $value) {
                    $a=(object) [
                        'id' => $value->id,
                        'applicant_name' => $value->applicant_name,
                        'mobile_no' => $value->mobile_no,
                        'email_id' => $value->email_id,
                        'branch_name' => $value->branch_name,
                        'status' => $value->status,
                        'caseId' => $value->caseId,
                        'partner_type' => $value->partner_type,
                        'training_m_date' => $value->training_m_date,
