                        'pan_status'=>$value->pan_status

                    ];
                    array_push($data,$a);
                }
            }
            $list=$data;
        }
        else if($this->request->type == 'Interested')
        {
                $list =$interestedList;
        }
        else if($this->request->type == 'Application')
        {
                $list =$applicationList;
        }
        else if($this->request->type == 'Under Review')
        {
                $list =$reviewList;
        }
        else if($this->request->type == 'Agreement In Progress')
        {
                $list =$approvedList;
        }
        else if($this->request->type == 'Onboarding')
        {
                $list =$completedist;
        }
        else if($this->request->type == 'Queries')
        {
            $quryData=array();
                foreach ($queryist as $value) {
                    if(count($quryData)==0){
                        $a=(object) [
                            'id' => $value->id,
                            'applicant_name' => $value->applicant_name,
                            'mobile_no' => $value->mobile_no,
                            'email_id' => $value->email_id,
                            'branch_name' => $value->branch_name,
                            'status' => $value->status,
                            'caseId' => $value->caseId,
                            'partner_type' => $value->partner_type,
                            'queryData'=>array()
                        ];
                        array_push($a->queryData,$value->query_description);
                        array_push($quryData,$a);
                    }else{
                        $isRecordFound=false;
                        foreach ($quryData as $value2){
                            if($value2->caseId==$value->caseId){
                                array_push($value2->queryData,$value->query_description);
                                $isRecordFound=true;
                            }
                        }

                        if($isRecordFound!=true){
                            $a=(object) [
                                'id' => $value->id,
                                'applicant_name' => $value->applicant_name,
                                'mobile_no' => $value->mobile_no,
                                'email_id' => $value->email_id,
                                'branch_name' => $value->branch_name,
                                'status' => $value->status,
                                'caseId' => $value->caseId,
                                'partner_type' => $value->partner_type,
                                'queryData'=>array()
                            ];
                            array_push($a->queryData,$value->query_description);
                            array_push($quryData,$a);
                        }
                    }
                    
                }

                foreach ($quryData as $value2){
                    $value2->queryCount=count($value2->queryData);
                }

                $list =$quryData;
        }

            return response()->json([   
                'data' => $list,
                'error' => false
            ], 200);


}

