                        'x-karza-key' => env('UAT_API_KARZA_KEY')
                    ],
                    'verify' => false
                ]);

                $response = $client->post(
                    'https://testapi.karza.in/v2/pan',
                    //local
                    // 'https://ezgatewayuat.insideabc.com/v2/pan',//uat
                    // 'https://ezgateway.insideabc.com/v2/pan',//prod
                    [
                        'body' => json_encode(
                            [
                                "consent" => "Y",
                                "pan" => $this->request->panNumber,
                                "getCOntactDetails" => "Y",
                                "PANStatus" => "Y"
                            ]
                        ),
                        'verify' => false
                    ]
                );
                $response = json_decode($response->getBody()->getContents());

                $errorCode = $response->{'status-code'};
                if ($errorCode == 101) {

                    $name = $response->{'result'}->{'name'};

                    $updateData = DB::table('dsa_front_m_case_master')
                        ->where('case_id', $this->request->caseId)
                        ->update([
                            'pan_verify_flag' => 1,
                            'pan_number' => $this->request->panNumber,
                            'panfullname' => $name,
                            //'father_name' => $fatherName[1],
                        ]);


                    // return response()->json([
                    //     'error' => false,
                    //     'data' => $response,
                    //     'message' => 'Pan number is verified',
                    // ], 200);

                } else {
                    return response()->json([
                        'error' => true,
                        'message' => $response
                    ], 200);
                }


            }
            $type=$caseDetails->partner_type=='DSA'?'DAA':'RPA';
            
            
            $panPresentList = DB::table('dsa_front_m_pan_master')
            // ->where('status', 'LIKE','%Blacklisted%')
            ->where('pan_no', $this->request->panNumber)->orderBy('id','DESC')->get()->toArray();
            $isHardStop=false;
            $isSendConsent=false;
            $name='';
            $code='';
            $msg='';
           
            $blackList=array_filter($panPresentList, function($item)  {
                return $item->status == 'Blacklisted';
            });

            if(count($blackList)>0){
                $isPanPresent=$blackList[array_keys($blackList)[0]];
                $name=$isPanPresent->entity_name;
                $code=$isPanPresent->dsa_rp_code;
                $rspn = DB::table('dsa_front_m_case_master')
                    ->where('case_id', $this->request->caseId)
                    ->update([
                        'pan_verify_flag' => 0,
                         'entered_pan_status' => $isPanPresent->status
                    ]);

                    
                if ($isPanPresent->status == "Blacklisted") {
                    $isHardStop=true;
                    $isSendConsent=false;
                    $msg='The requested PAN number is blaklisted with DSA/RP code ' . $code . '.';
                        DB::table('dsa_front_m_case_master_pan_dedupe')
                        ->updateOrInsert(
                            [
                                'case_id'=>$this->request->caseId,
                            ],
                            [
                            'pan_no'=>$this->request->panNumber,
                            'pan_status'=>$isPanPresent->status,
                            'entity_name'=>$name,
                            'vendor_status'=>$isPanPresent->vendor_status,
                            'city'=>$isPanPresent->city,
                            'mobile_no'=>$isPanPresent->mobile_no,
                            'email_id'=>$isPanPresent->email_id,
                            'dsa_rp_code'=>$isPanPresent->dsa_rp_code,
                            'isHardStop'=>$isHardStop,
                            'pan_verify_flag' => $isHardStop == true ? 0 :1,
                            'isSendConsent'=>$isSendConsent,
                            'msg'=>$msg,

                        ]);
                    return response()->json([
                        'error' => true,
                        'data' => $response,
                        'status'=>$isPanPresent->status,
                        'name'=>$name,
                        'code'=>$code,
                        'isHardStop'=>$isHardStop,
                        'isSendConsent'=>$isSendConsent,
                        'message' => 'The requested PAN number is blaklisted with DSA/RP code ' . $isPanPresent->dsa_rp_code . '.'
                    ], 400);
                }

            }
            // if ($this->request->log) {
            //     dd(count($panPresentList));
            // }
            if(count($panPresentList) > 0){
                $isPanPresent=$panPresentList[0];
            } else {
                $isPanPresent = null;
            }

            if ($isPanPresent) {
                $name=$isPanPresent->entity_name;
                $code=$isPanPresent->dsa_rp_code;


                $typeCase=str_contains($isPanPresent->dsa_rp_code,'DAA')?'DSA':'RP';
                $rspn = DB::table('dsa_front_m_case_master')
                    ->where('case_id', $this->request->caseId)
                    ->update([
                        'entered_pan_status' => $isPanPresent->status
                    ]);
                if ($isPanPresent->status == "Blacklisted") {
                    $isHardStop=true;
                    $isSendConsent=false;
                    // return response()->json([
                    //     'error' => true,
                    //     'message' => 'The requested PAN number is blaklisted with DSA/RP code ' . $isPanPresent->dsa_rp_code . '.'
                    // ], 400);
                    $msg='The requested PAN number is blaklisted with DSA/RP code ' . $code . '.';
                } else if ($isPanPresent->status == "Active") {
                  
                    if(str_contains($isPanPresent->dsa_rp_code,$type)){
                        $isHardStop=true;
                        $msg='The requested PAN number is '.$isPanPresent->status.' with '.$name.' code ' . $code . '.';
                        // dd("KD");
                        DB::table('dsa_front_m_case_master')
                        ->where('case_id', $this->request->caseId)
                        ->update([
                            'pan_verify_flag' => 0
                        ]);
                        // PAN is already exist with the Name of RP name and RP code
                    } else{
                        $isHardStop=false;
                        $msg='Do you want to apply for '.$caseDetails->partner_type.' PAN is already present as '.$typeCase.' for '.$name.' and '.$code.'';
                        $isSendConsent=true;
                    }
                }else if ($isPanPresent->status == "Deactive"||strtolower($isPanPresent->status) == "inactive") {
                    $isHardStop=false;
                    $isSendConsent=false;
                    $msg='Pan is verified.The requested PAN number is '.$isPanPresent->status.' with '.$name.' code ' . $code . '.';

                }

                DB::table('dsa_front_m_case_master_pan_dedupe')
                    ->updateOrInsert(
                        [
                            'case_id'=>$this->request->caseId,
                        ],
                        [
                        'pan_no'=>$this->request->panNumber,
                        'pan_status'=>$isPanPresent->status,
                        'entity_name'=>$name,
                        'vendor_status'=>$isPanPresent->vendor_status,
                        'city'=>$isPanPresent->city,
                        'mobile_no'=>$isPanPresent->mobile_no,
                        'email_id'=>$isPanPresent->email_id,
                        'dsa_rp_code'=>$isPanPresent->dsa_rp_code,
                        'isHardStop'=>$isHardStop,
                        'isSendConsent'=>$isSendConsent,
                        'msg'=>$msg,
                    ]);


                return response()->json([
                    'error' => false,
                    'data' => $response,
                    'status'=>$isPanPresent->status,
                    'name'=>$name,
                    'code'=>$code,
                    'isHardStop'=>$isHardStop,
                    'isSendConsent'=>$isSendConsent,
                    // 'message' => 'The requested PAN number is already '.$isPanPresent->status.' with DSA/RP code ' . $isPanPresent->dsa_rp_code . '.'
                    'message' => $msg
                ], 200);
            }else{
                //BlackList
                // if ($isPanPresent->status == "Blacklisted") {
                //     $rspn = DB::table('dsa_front_m_case_master')
                //         ->where('case_id', $this->request->caseId)
                //         ->update([
                //             'entered_pan_status' => "Blacklisted",
                //         ]);

                //     return response()->json([
                //         'error' => true,
                //         'message' => 'The requested PAN number is blaklisted with DSA/RP code ' . $isPanPresent->dsa_rp_code . ', And the PAN is blaklisted.'
                //     ], 400);


                // }
            }

            $isPanAlreadyUsedInBackendCase = DB::table('dsa_m_case')
            ->where('case_status','!=','Approved')->where('pan_no', $this->request->panNumber)->first();
            
           
            if ($isPanAlreadyUsedInBackendCase) {
                $rspn = DB::table('dsa_front_m_case_master')
                    ->where('case_id', $this->request->caseId)
                    ->update([
                        'pan_verify_flag' => 0,
                         'entered_pan_status' => "Already In Backend",
                    ]);
                    
                return response()->json([
                    'error' => true,
                    'error' => false,
                    'data' => $response,
                    'name'=>$name,
                    'code'=>$code,
                    'isHardStop'=>$isHardStop,
                    'isSendConsent'=>$isSendConsent,
                    'message' => 'The requested PAN number is already in system mapped with ' . $isPanAlreadyUsedInBackendCase->applicant_name . ' applicant.'
                ], 400);
            }

            $isPanAlreadyUsedInFrontCase = DB::table('dsa_front_m_case_master')
            ->where('email_id','!=','Approved')->where('pan_number', $this->request->panNumber)
            ->where('case_id','!=', $this->request->caseId)->first();

            // dd($isPanAlreadyUsedInFrontCase,$isPanAlreadyUsedInBackendCase);
            if ($isPanAlreadyUsedInFrontCase) {

                $rspn = DB::table('dsa_front_m_case_master')
                    ->where('case_id', $this->request->caseId)
                    ->update([
                        'pan_verify_flag' => 0,
                        'entered_pan_status' => "Already In Frontend",
                    ]);

                return response()->json([
                    'error' => true,
                    'data' => $response,
                    'name'=>$name,
                    'code'=>$code,
                    'isHardStop'=>$isHardStop,
                    'isSendConsent'=>$isSendConsent,
                    'message' => 'The requested PAN number is already in system mapped with ' . $isPanAlreadyUsedInFrontCase->applicant_fullname . ' applicant.'
                ], 400);

            }

            return response()->json([
                'error' => false,
                'data' => $response,
                'name'=>$name,
                'code'=>$code,
                'isHardStop'=>$isHardStop,
                'isSendConsent'=>$isSendConsent,
                'message' => 'Pan number is verified',
            ], 200);
        } catch (\Exception $e) {
            dd($e);
            $errorCode = $e->errorInfo[1];
            if ($errorCode == 1062 || $errorCode == 2627) {
                return response()->json([
                    'error' => true,
                    'message' => 'Internal error.'.$e
                ], 400);
            }
            return response()->json([
                'error' => true,
                'message' => 'Internal error.'
            ], 400);
        }
    }
public function verifyPan1(){
    $user = $this->request->auth; 

    // $faker = Faker::create();

    $this->validate($this->request, [
        'panNumber' => 'required',
    ]);

    try {

        $isPanPresent=DB::table('dsa_front_m_pan_master')->where('pan_no', $this->request->panNumber)->first();


            if($isPanPresent){
                if($isPanPresent->status=="Blacklisted"){
                    return response()->json([
                        'error'=>true,
                        'message' => 'The requested PAN number is blaklisted with DSA/RP code '.$isPanPresent->dsa_rp_code.', And the PAN is blackisted.'
                    ], 400);
                }else if($isPanPresent->status=="Active"){
                    return response()->json([
                        'error'=>true,
                        'message' => 'The requested PAN number is already active with DSA/RP code '.$isPanPresent->dsa_rp_code.'.'
                    ], 400);
                }
            }

            $isPanAlreadyUsedInBackendCase=DB::table('dsa_m_case')->where('pan_no', $this->request->panNumber)->first();

            if($isPanAlreadyUsedInBackendCase){
                return response()->json([
                    'error'=>true,
                    'message' => 'The requested PAN number is already in system mapped with '.$isPanAlreadyUsedInBackendCase->applicant_name.' applicant.'
                ], 400);
            }

            $isPanAlreadyUsedInFrontCase=DB::table('dsa_front_m_case_master')->where('pan_number', $this->request->panNumber)->first();

            if($isPanAlreadyUsedInFrontCase){
                return response()->json([
                    'error'=>true,
                    'message' => 'The requested PAN number is already in system mapped with '.$isPanAlreadyUsedInFrontCase->applicant_fullname.' applicant.'
                ], 400);
            }



        if(env('APP_API_PAN') == 'local'){
            $response =[
                "requestId"=> "3484c202-3f6b-47cb-8620-168f10af1050",
                "result"=>([
                    "name"=> $faker->name,  
                    ] ),
    
                "statusCode"=> 101,
                "clientData"=> ([
                    "caseId"=> "123456"
                ])];

                $errorCode = $response['statusCode'];
                if($errorCode==101){
                    $name=$response['result']['name'];  
                    $updateData=DB::table('dsa_front_m_case_master')
                    ->where('case_id', $this->request->caseId)  
                        ->update([
                            'pan_verify_flag' => 1,
                            'pan_number' => $this->request->panNumber,
                            'panfullname' => $name,
                            // 'authorised_flag' => 1,
                            // 'father_name' => $fatherName[1],
                     ]);
                    return response()->json([
                        'error'=>false,
                        'data' => $response,
                        'message' => 'PAN Number is verified',
                    ], 200);
                }
        }else{
            $client = new \GuzzleHttp\Client([
                'headers' => [
                    'Content-Type' => 'application/json',
                    // 'x-karza-key' => 'inTexg7pvh4Huiye'
                    // 'x-karza-key' => 'p5kMaaFfaOlekbeJ' 
                    'x-karza-key' => env('UAT_API_KARZA_KEY2') 
                ],
                'verify'=>false
            ]);
    
            $response = $client->post(
                    // 'https://testapi.karza.in/v2/pan',//local
                       'https://ezgatewayuat.insideabc.com/v2/pan',//uat
                    // 'https://ezgateway.insideabc.com/v2/pan',//prod
                ['body' => json_encode(
                    [
                        "consent"=>"Y",
                        "pan"=>$this->request->panNumber,
                        "getCOntactDetails"=>"Y",
                        "PANStatus"=>"Y"
                    ]
                    ),'verify' => false],
            ); 
                $response = json_decode($response->getBody()->getContents());
                $errorCode = $response->{'status-code'};    
    // dd($errorCode);

                if($errorCode==101){
                    
                    $name=$response->{'result'}->{'name'};
    
                    $updateData=DB::table('dsa_front_m_case_master')
                    ->where('case_id', $this->request->caseId)  
                        ->update([
                            'pan_verify_flag' => 1,
                            'pan_number' => $this->request->panNumber,
                            'panfullname' => $name,
                            // 'authorised_flag' => 1,
                     ]);
                    return response()->json([
                    'error'=>false,
                    'data' => $response,
                    'message' => 'Pan number is verified',
                ], 200);
    
                }else{
                    return response()->json([
                        'error'=>true,
                        'message' =>  $response
                    ], 200);
                }
        }
    } catch (\Exception $e) {
        // dd(json_encode($e->getMessage())->error);
        // dd($e);
            // $errorCode = $e->errorInfo[1];
            // if ($errorCode == 1062 || $errorCode == 2627) {
            //     return response()->json([
            //     'error'=>true,
            //         'message' => 'Internal error.'
            //     ], 400);
            // }
            return response()->json([
                'error'=>true,
                'message' => $e->getMessage()
            ], 200);
    }
