public function checkcurrentAddress()
{
    if($this->request->addressFlag == 1)
    {
        $updateData=DB::table('dsa_front_m_case_master')
        ->where('case_id', $this->request->caseId) 
            ->update([
                'current_address_flag' => $this->request->addressFlag, 
        ]);

        $addressData = DB::table('dsa_front_t_case_address as dca')
                        ->where('dca.case_id', $this->request->caseId)
                        ->select('dca.*')->get();
       
        DB::table('dsa_front_t_case_address')->insert(  
            [
                'case_id' => $this->request->caseId,
                'address_type' => 'Current',
                'addressline1' => $addressData[0]->addressline1,
                'addressline2' => $addressData[0]->addressline2,
                'pincode' => $addressData[0]->pincode,
                'area' => $addressData[0]->area,
                'landmark' => $addressData[0]->landmark,
                'city' => $addressData[0]->city,
                'district' => $addressData[0]->district,
                'state' => $addressData[0]->state,
                'country' => $addressData[0]->country,
                'resident_type' => '2',
            ] 
        );

        return response()->json([
            'error'=>false,
            'message' => 'Current address updated'
        ], 200);
    }

}

