public function uploadApplicantphoto()
{
    //  dd('$this->request ',$this->request->file);
    //$user = $this->request->auth;
    $this->validate($this->request, [
        'caseId' => 'required|integer',
        'file' => 'required'
    ]);
    if (env('STORAGE_LOCATION') == 'FILE_SYSTEM') {
        //save docs
        $destinationPath = 'uploads/dsa_front/';
        $fileInitials = date('YmdHis') . '_' . $this->randomCode(6);
        $file = $this->request->file('file'); 
        $name = $this->request->file->getClientOriginalName(); 
        $contentType = $this->request->file->getMimeType();
        $file->move($destinationPath, $fileInitials . '.' . $file->getClientOriginalExtension());
        $filePath = $fileInitials . '.' . $file->getClientOriginalExtension();
        $fullPath='D:\\API\\public\\uploads\\dsa_front\\'. $fileInitials . '.' . $file->getClientOriginalExtension();

        if(env('UPLOAD_DMS') == 'server'){
            $dmsID=$this->callUpload($this->request->caseId,3,$this->randomCode(3),$fullPath,$filePath,$contentType);
     
            if($dmsID['error'] == false)
            {
                $updateData=DB::table('dsa_front_m_case_master')
                ->where('case_id', $this->request->caseId) 
                    ->update([
                        'other_adhar_file_name' => $fileInitials . '.' . $file->getClientOriginalExtension(), 
                        'other_adhar_file_path' => $destinationPath, 
                        'other_adhar_dms_id'=>$dmsID['documentID'] 
                ]);
                
               // unlink($fullPath); 
                return response()->json([
                    'error'=>false,
                   'message' => 'Attachment\'s saved.'
               ], 200);
            }
            else {
    
                return response()->json([
                    'error'=>true,
                    'message' => $dmsID['message']
                ], 500);
            }
        }else{
                $updateData=DB::table('dsa_front_m_case_master')
                ->where('case_id', $this->request->caseId) 
                    ->update([
                        'other_adhar_file_name' => $fileInitials . '.' . $file->getClientOriginalExtension(), 
                        'other_adhar_file_path' => $destinationPath, 
                ]);

     
                return response()->json([
                    'error'=>false,
                   'message' => 'Attachment\'s saved.'
               ], 200);
        }
     } 

    return response()->json([
        'error'=>false,
        'message' => 'Applicant photo saved'
    ], 200);
} 

public function verifyGst(){
    $user = $this->request->auth;

    $this->validate($this->request, [
        'gstNumber' => 'required',
        'caseId' => 'required',
    ]);

    try {
        if(env('APP_API_GST') == 'local'){
            $updateData=DB::table('dsa_front_m_case_master')
            ->where('case_id', $this->request->caseId)  
                ->update([
                    'gst_verify_flag' => 1, 
                    'gst_applicable' => $this->request->gstApplicable, 
                    'gst_number' => $this->request->gstNumber,   
            ]);
            $response=[];
            return response()->json([
            'error'=>false,
            'data' => $response,
            'message' => 'GST Number is verified',
            ], 200); 
        }else{
            $client = new \GuzzleHttp\Client([
                'headers' => [
                    'Content-Type' => 'application/json',
                    'x-karza-key' => env('UAT_API_KARZA_KEY') 
                ],
                'verify'=>false
            ]);

            $response = $client->post(
            'https://ezgatewayuat.insideabc.com/gst/uat/v2/gstdetailed',//uat
             //'https://ezgateway.insideabc.com/gst/prod/v2/gstdetailed'//prod
            // 'https://api.karza.in/gst/uat/v2/gstdetailed',//local
            ['body' => json_encode(
                [
                    "consent"=>"Y",
                    "additionalData"=>false,
                    "gstin"=>$this->request->gstNumber
                ]
                ),'verify' => false]
        );
        $response = json_decode($response->getBody()->getContents());
        $errorCode = $response->{'statusCode'};
        // dd($response);
        $response->{'result'}->{'tradeNam'} = 'Yatin Sitaram Rai';
        $response->{'result'}->{'contacted'}->{'name'} = 'Yatin Sitaram Rai';
        if($errorCode==101){

            
            // $gstUserName = strtolower($response->{'result'}->{'tradeNam'});
            $gstUserName = strtolower($response->{'result'}->{'contacted'}->{'name'});

            $caseData = DB::table('dsa_front_m_case_master')
            ->where('case_id', $this->request->caseId)->get();

            $panUserName=strtolower($caseData[0]->panfullname);
// dd($panUserName);
            if($gstUserName!=$panUserName){
                return response()->json([
                    'error'=>true,
                    'message' =>  "Name captured in PAN does not match with name belongs to GST." 
                ], 200);
            }else{
                $updateData=DB::table('dsa_front_m_case_master')
                ->where('case_id', $this->request->caseId) 
                    ->update([
                        'gst_verify_flag' => 1, 
                        'gst_applicable' => $this->request->gstApplicable, 
                        'gst_number' => $this->request->gstNumber,   
                ]);
    
                return response()->json([
                'error'=>false,
                'data' => $response,
                'message' => 'GST Number is verified'
                    ], 200);
            }


        }else{
            return response()->json([
                'error'=>true,
                'message' =>  "Someting went wrong, please try again" 
            ], 200);
        }
        }
    } catch (\Exception $e) {
        dd($e->getMessage());
        $errorCode = $e->errorInfo[1];
        if ($errorCode == 1062 || $errorCode == 2627) {
            return response()->json([
            'error'=>true,
                'message' => 'Internal error.'
            ], 400);
        }
        return response()->json([
            'error'=>true,
            'message' => 'Internal error.'
        ], 400);
    }
}




