                'caseId'=>'required',
                // 'directorId'=>'required'
            ]);
            
            $panNumber=Crypt::encryptString($this->request->panNumber);
            $response =[
                "requestId"=> "3484c202-3f6b-47cb-8620-168f10af1050",
                "result"=>([
                    "name"=> $faker->name,  
                    ] ),
                    
                    "statusCode"=> 101,
                    "clientData"=> ([
                        "caseId"=> "123456"
                        ])];
                        
                $errorCode = $response['statusCode'];

                if($errorCode==101){
                     $name=$response['result']['name'];  
    
