                        ->where('case_id', $this->request->caseId) 
                        ->where('tid', $this->request->directorId) 
                                ->update([
                                    // 'director_pan' =>$this->request->panNumber, 
                                    'director_pan' =>$panNumber, 
                                    'director_pan_verify_flag' => 1, 
