                    ], 200);
                }else{
                    $did=DB::table('dsa_front_t_case_director')->insertGetId( 
                        [
                            'case_id' => $this->request->caseId,
                            // 'director_pan' => $this->request->panNumber,
                            'director_pan' =>$panNumber, 
                            'director_pan_verify_flag' => 1,
                            'director_full_name' => $name,
                            'authorised_flag'=>1
                            // 'director_father_name' => $fatherName[1], 
                        ] 
                    );

                    return response()->json([ 
                        'directorId'=>$did,
                        'error'=>false,
                        'data' => $response,
                        'message' => 'PAN Number is verified', 
                    ], 200);
                }
            }else{
                return response()->json([
                    'error'=>true,
                    'message' =>  'Failed to verify PAN. Please try again...'
                ], 400);
            }
    
        }
    } catch (\Exception $e) {
        return response()->json([
