public function deleteDirector()
{
        $user = $this->request->auth;
        $this->validate($this->request, [
            'directorId' => 'required' 
        ]);

        try {
            DB::table('dsa_front_t_case_director')
                ->where('tid', $this->request->directorId)
                ->update([
                    'deletion_flag' => 1,
                    'deleted_by'=>1,
                    'authorised_flag'=>0,
                    'deleted_at' => Carbon::now(),
                ]);

            return response()->json([
                'message' => 'Director deleted.'
            ], 200);
        } catch (\Exception $e) {
            dd($e->getMessage());
            $errorCode = $e->errorInfo[1];
            if ($errorCode == 1062 || $errorCode == 2627) {
                return response()->json([
                    'message' => 'error.'
                ], 400);
            }
            return response()->json([
                'message' => 'Please contact administrator.'
            ], 400);
        }
}

