public function uploadbankcancelCheque()
{
    // dd('$this->request ',$this->request);
    $user = $this->request->auth;
    $this->validate($this->request, [ 
        'caseId' => 'required|integer',
        'file' => 'required'
    ]);
    if (env('STORAGE_LOCATION') == 'FILE_SYSTEM') {
        //save docs
        $destinationPath = 'uploads/dsa_front/';
        $fileInitials = date('YmdHis') . '_' . $this->randomCode(6);

        $file = $this->request->file('file');

        $name = $this->request->file->getClientOriginalName();
        $fileSize = $this->request->file->getSize();
        $contentType = $this->request->file->getMimeType();

        $file->move($destinationPath, $fileInitials . '.' . $file->getClientOriginalExtension());
        $filePath = $fileInitials . '.' . $file->getClientOriginalExtension();
        $fullPath='D:\\API\\public\\uploads\\dsa_front\\'. $fileInitials . '.' . $file->getClientOriginalExtension();
        try {

            $docCount = DB::table('dsa_front_t_case_attachment')
                            ->where('case_id', $this->request->caseId)->where('document_id',12)->where('deletion_flag',0)->count();
            if($docCount == 0)
            {
                $did= DB::table('dsa_front_t_case_attachment')->insertGetId([
                    'case_id' => $this->request->caseId,
                    'document_id' => 12,
                    'name' => $name,
                    'path' => $filePath,
                    'fileSize' => $fileSize,
                    'contentType' => $contentType,
                    'created_by' => 1,
                    'storage_location' => env('STORAGE_LOCATION')
                ]);
                if(env('UPLOAD_DMS') == 'server'){
                $dmsID=$this->callUpload($this->request->caseId,12,$did,$fullPath,$filePath,$contentType);

                if($dmsID['error'] == false)
                {
                    DB::table('dsa_front_t_case_attachment')
                    ->where('id', $did) 
                    ->update([
                        'dms_id'=> $dmsID['documentID']
                    ]);  
                    unlink($fullPath);
                    return response()->json([
                        'error'=>false,
                       'message' => 'Attachment\'s saved.'
                   ], 200);
                }
                else {
                    DB::table('dsa_front_t_case_attachment')->where('id',$did)->delete();
                    return response()->json([
                        'error'=>true,
                        'message' => $dmsID['message']
                    ], 500);
                }
             }
                
            }
            else {

                $did = DB::table('dsa_front_t_case_attachment')->where('case_id', $this->request->caseId)->where('document_id',12)->where('deletion_flag',0)->value('id');

                         
                if(env('UPLOAD_DMS') == 'server'){
                    $dmsID=$this->callUpload($this->request->caseId,12,$did,$fullPath,$filePath,$contentType);

                    if($dmsID['error'] == false)
                    {
                        DB::table('dsa_front_t_case_attachment') 
                        ->where('id', $did) 
                        ->update([
                           'name' => $name,
                           'path' => $filePath,
                           'fileSize' => $fileSize,
                           'contentType' => $contentType, 
                           'dms_id'=> $dmsID['documentID']
                        ]);

                        unlink($fullPath);
                        return response()->json([
                            'error'=>false,
                           'message' => 'Attachment\'s saved.'
                       ], 200);
                    }
                    else {
                        DB::table('dsa_front_t_case_attachment')->where('id',$did)->delete();
                        return response()->json([
                            'error'=>true,
                            'message' => $dmsID['message']
                        ], 500);
                    }

                }else{
                    DB::table('dsa_front_t_case_attachment') 
                        ->where('id', $did) 
                        ->update([
                           'name' => $name,
                           'path' => $filePath,
                           'fileSize' => $fileSize,
                           'contentType' => $contentType, 
                        ]);
                    
                        unlink($fullPath);
                        return response()->json([
                            'error'=>false,
                           'message' => 'Attachment\'s saved.'
                       ], 200);
                }
                
            }
        } catch (\Exception $e) {

            DB::rollback();
            // dd("error--" . $e->getMessage());
            $errorCode = $e->getMessage();
            if ($errorCode == 1062 || $errorCode == 2627) {
                return response()->json([
                    'message' => 'Project Name Can\'t be Same.' . $e
                ], 400);
            }
            return response()->json([
                'message' => 'Please contact administrator.' . $e
            ], 400);
        }
    } else {
        DB::table('tejora_t_case_property_attachments')->insert([
            'case_id' => $this->request->caseId,
            'document_id' => 12,
            'name' => $this->request->file->getClientOriginalName(),
            'path' => base64_encode(file_get_contents($this->request->file('file'))), 
            'fileSize' => $this->request->file->getSize(),
            'contentType' => $this->request->file->getMimeType(),
            'created_by' => 1,
            'storage_location' => env('STORAGE_LOCATION')

        ]);
    }

    return response()->json([
        'message' => 'Attachment\'s saved.'
    ], 200);
}

