public function callUpload($caseId,$documentId,$did,$fullPath,$filePath,$contentType,$b2dCaseId = null,$b2dCaseName = null)
{
    if($caseId != ""){
        $caseData = DB::table('dsa_front_m_case_master')
        ->where('case_id', $caseId)->get();
    }
    
    $docData = DB::table('dsa_front_m_document_type')
        ->where('did', $documentId)->get();

    //dd($docData);    
    
    $applicantcaseId= $b2dCaseId == null ? $caseData[0]->case_id : $b2dCaseId;
    $applicantName= $b2dCaseName == null ? $caseData[0]->applicant_fullname : $b2dCaseName; 
    $applicantoldId=$b2dCaseName == null ?$caseData[0]->new_case_id:"";
    // $contactNo=$caseData[0]->phone_number;
    $tmpId="";
    if($docData[0]->document_type=='Others'){
        $tmpId="";
    }else{
        $tmpId=$did;
    }
    $a=  
