public function downloadFile()
{
    
    $this->validate($this->request, [
        'DID' => 'required',  
        // 'DID' => 'nullable',  
        // 'documentType' => 'nullable',  
    ]);

    // if($this->request->documentType=="Agreement"){
    //     return response()->json([
    //             'error'=>true,
    //             'message' => 'Aggrement not ready, please try after sometime.'
    //         ], 200);
    // }else if($this->request->documentType=="Application"){
    //     return response()->json([
    //         'error'=>true,
    //         'message' => 'Application not ready, please try after sometime.'
    //     ], 200);
    // }else if($this->request->DID==NULL){
    //     return response()->json([
    //         'error'=>true,
    //         'message' => 'Document id is required.'
    //     ], 200);
    // }

    try {

        $client = new \GuzzleHttp\Client([
            'headers' => [
                'Content-Type' => 'application/json',
                // 'x-karza-key' => env('UAT_API_KARZA_KEY') 
            ],'verify' => false,
        ]);
        $response1 = $client->post(
            'https://ezgatewayuat.insideabc.com/rest/download/doc',
            ['body' => json_encode(
                [
                        "DID" => $this->request->DID,
                        "token" => 'viewertoken', 
                ]
            )]
        );
      //  dd($response1->getHeaders());
        $contentType = '';
        $contentDisposition = '';
        foreach ($response1->getHeaders() as $name => $value) {

        
            if($name == 'Content-Type') $contentType = $value;

            if($name == 'Content-Disposition') $contentDisposition = $value;
        }
            // dd($contentType[0]);
        return response($response1->getBody())
        ->header('Content-Type', $contentType[0])
        ->header('Content-Disposition', $contentDisposition[0]);

        

    } catch (\Exception $e) {
        dd($e);
        $errorCode = $e->errorInfo[1];
        if ($errorCode == 1062 || $errorCode == 2627) {
            return response()->json([
            'error'=>true,
                'message' => 'Internal error.'
            ], 400);
        }
        return response()->json([
            'error'=>true,
            'message' => 'Internal error.'
        ], 400);
    }
}


