public function deletecaseDocument()
{
    $user = $this->request->auth;

        $this->validate($this->request, [
            'did' => 'required', 
        ]);

        DB::table('dsa_front_t_case_attachment')
        ->where('id', $this->request->did)
        ->update([
            'deletion_flag' => 1,  
            'deleted_by'=>1,
            'deleted_at' => Carbon::now(),   
        ]);
    

    return response()->json([
        'status'=> 200,
        'message' => 'Document deleted',

    ], 200); 

}


public function adddsaEvent()
{   
 $user = $this->request->auth;
    $this->validate($this->request, [
        'eventTitle' => 'required',
        'eventType' => 'required',
        'eventMode' => 'required',
        'eventDuration' => 'required',
        'startDate' => 'required',
        'startTime' => 'required',
        'endDate' => 'required',
        'endTime' => 'required',
        'agentType' => 'required',
        'eventStatus' => 'required'
    ]);

 try {
    DB::beginTransaction();
     $eventId=DB::table('dsa_front_t_event')->insertGetId([
         'event_title' => $this->request->eventTitle,
         'event_type'=>$this->request->eventType,     
         'event_mode' => $this->request->eventMode,
         'event_duration'=> $this->request->eventDuration,
         'start_date' => $this->request->startDate, 
         'start_time' =>   $this->request->startTime,
         'end_date' =>   $this->request->endDate,
         'end_time' =>   $this->request->endTime,  
         'event_description' => $this->request->eventDescription,
         'agent_type' =>   $this->request->agentType,
         'event_status' =>   $this->request->eventStatus,
         'individual_name' =>   $this->request->individualName, 
         'individual_contact_no' =>   $this->request->individualcontactNo,
         'individual_email_id' =>   $this->request->individualemailId, 
         'appointment_status' => 'New Appointment', 
         'created_by'=>$user->employee_id,
     ]);
   

            foreach ($this->request->teamMember as $item) {

                DB::table('dsa_front_t_event_member')->insertGetId([
                    'event_id' => $eventId, 
                    'member_id'=>$item,     
                    'created_by'=>$user->employee_id,
                ]);
            }

            $userName = DB::table('master_employee')->where('employee_id',  $user->employee_id)->value('employee_name');

            DB::table('dsa_front_t_event_logs')->insert([
                'event_id' => $eventId, 
                'created_by_name' => $userName,
                'log_description' =>$this->request->eventDescription,
                'log_status' => 'New Appointment', 
                'Role'=> 'Admin',
                'remark' => 'Event '.$this->request->eventTitle.' is added by '.$userName,
                'created_by' => $user->employee_id,
                'assign_to_name' => 'user',   
            ]);



            DB::commit();
            return response()->json([
                'Status'=> 200,
                'message' => 'Event added',
           
            ], 200); 
           
    } catch (\Exception $e) {

        DB::rollback();
        // dd("error--" . $e->getMessage());
        $errorCode = $e->errorInfo[1];
        return response()->json([
            'message' => 'Please contact administrator.' . $e
        ], 400);
    }


}

public function updateeventSchedule()
{
        $user = $this->request->auth;


        $this->validate($this->request, [
            'eventId' => 'required' 
        ]);

        $isClosed= DB::table('dsa_front_m_appointment_status')->where('appointment_status',  $this->request->appointmentStatus)->value('is_closed');
        $sDate="";$sTime="";
        if($this->request->startDate && $this->request->startTime)
        {
            $sDate=$this->request->startDate;
            $sTime=$this->request->startTime;
        }
        else {
            $sDate=DB::table('dsa_front_t_event')->where('event_id',  $this->request->eventId)->value('start_date');
            $sTime=DB::table('dsa_front_t_event')->where('event_id',  $this->request->eventId)->value('start_time');
        }
        try {
            DB::table('dsa_front_t_event')
                ->where('event_id', $this->request->eventId)
                ->update([
                    'appointment_status' => $this->request->appointmentStatus,
                    'appointment_disposition' => $this->request->appointmentDisposition,
                    'appointment_subdisposition' => $this->request->appointmentSubdisposition,
                    'event_description' => $this->request->rescheduleDescription,
                    'reschedule_description' => $this->request->rescheduleDescription,
                    'start_date' => $sDate, 
                    'start_time' =>   $sTime,
                    'end_date' =>   $sDate,
                    // 'end_time' =>   $this->request->startTime,  
                    'event_reminder' =>   $this->request->eventReminder, 
                    'event_status' =>$isClosed == 1 ? 'Closed':'Open',
                    'updated_by'=>$user->employee_id,
                    'updated_at' => Carbon::now(),
                ]);
                $eventName = DB::table('dsa_front_t_event')->where('event_id', $this->request->eventId)->value('event_title');
                $userName = DB::table('master_employee')->where('employee_id',  $user->employee_id)->value('employee_name');
                DB::table('dsa_front_t_event_logs')->insert([
                    'event_id' =>  $this->request->eventId, 
                    'created_by_name' => $userName, 
                    'log_status' => $this->request->appointmentStatus, 
                    'log_description' =>$this->request->rescheduleDescription,
                    'Role'=> 'Admin',
                    'remark' => 'Event '.$eventName.' status is '.$this->request->appointmentStatus . ' updated by ' .$userName,
                    'created_by' => $user->employee_id,
                    'assign_to_name' => 'user',  
                ]);
    

            return response()->json([
                'message' => 'Event Schedule Updated.'
            ], 200);
        } catch (\Exception $e) {
            // dd($e->getMessage());
            $errorCode = $e->errorInfo[1];
            if ($errorCode == 1062 || $errorCode == 2627) {
                return response()->json([
                    'message' => 'error.'
                ], 400);
            }
            return response()->json([
                'message' => 'Please contact administrator.'
            ], 400);
        }
}

