public function geteventList()
{ 
    $user = $this->request->auth;
    
    $eventData = "";
    $eventData = DB::table('dsa_front_t_event')->where('created_by',$user->employee_id);  

    $eventData->where(function ($eventData) {   
        $eventData->where('event_title', 'like', '%' . $this->request->searchTerm . '%')
            ->orWhere('event_type', 'like', '%' . $this->request->searchTerm . '%')
            ->orWhere('event_mode', 'like', '%' . $this->request->searchTerm . '%')
            ->orWhere('individual_name', 'like', '%' . $this->request->searchTerm . '%')
            ->orWhere('individual_contact_no', 'like', '%' . $this->request->searchTerm . '%')
            ->orWhere('individual_email_id', 'like', '%' . $this->request->searchTerm . '%')
            ->orWhere('agent_type', 'like', '%' . $this->request->searchTerm . '%');  
    }); 

    $days=$this->calculateHolidays($this->request->startDate,$this->request->startDate);

    if($this->request->type == 'Monthly')
    {
       $eventData->whereRaw("MONTH(start_date) = MONTH(NOW())");

    }
    else if($this->request->type == 'Yearly')
    {
        $startDate=Carbon::now()->year.'-04-01';
        $endDate=Carbon::parse(Carbon::now())->addYears(1)->format('Y').'-03-31';

        $eventData->whereBetween('start_date', [(Carbon::parse($startDate)->format('Y-m-d')), (Carbon::parse($endDate)->add('day', 1)->format('Y-m-d'))]);
    }

    else if($this->request->type == 'Range') {
 
    }

    if($this->request->fromDate && $this->request->toDate)
    {
        $eventData->whereBetween('start_date', [(Carbon::parse($this->request->fromDate)->format('Y-m-d')), (Carbon::parse($this->request->toDate)->add('day', 1)->format('Y-m-d'))]);
    }
    
    if($this->request->startDate) 
    {
        $eventData->whereRaw("'".$this->request->startDate."'  between DATE_FORMAT(start_date,'%Y-%m-%d') and DATE_FORMAT(end_date,'%Y-%m-%d')");
    }
    if($this->request->agentType)
    {
        $eventData->whereIn('agent_type',$this->request->agentType);
    }
    if($this->request->eventTitle)
    {
         $eventData->whereIn('event_title',$this->request->eventTitle);
    } 
    if($this->request->eventType)
    {
         $eventData->whereIn('event_type',$this->request->eventType);
    }

    if($this->request->eventStatus)
    {
         $eventData->where('appointment_status',$this->request->eventStatus); 
    }

    
    if(count($eventData->get())>0){
        $edata=[];
        foreach ($eventData->get() as $item) {
         
            $member = DB::table('dsa_front_t_event_member as dem')
            ->leftjoin('dsa_front_m_team_member as dtm','dem.member_id', '=', 'dtm.member_id' )
            ->select('dem.member_id','dtm.member_name')
            ->where('dem.event_id', $item->event_id)->get();
           // $item->memberList=$member;
            if($item->event_duration == 'All Day')
            { 
                array_push($edata,$item);
            }
            else if($item->event_duration == 'Working Days' && $days!=1)
            { 
                array_push($edata,$item);
            }
        }
            

            return response()->json([
        'message' => 'Event Data found',
        'eventData'=>$edata
    ], 200); 
       
    }
    else {
        return response()->json([
            'error'=>false,
            'message' => 'Record not found.'
            ], 200);
    }


}

public function geteventDashboardCount()
{
        $user = $this->request->auth;
        $condition="";
        $condition1="";
        if($this->request->type == 'Monthly')
        {
            $condition="and MONTH(start_date) = MONTH(NOW()) and created_by = $user->employee_id";
            $condition1="where MONTH(start_date) = MONTH(NOW()) and created_by = $user->employee_id";  
        }
        else if($this->request->type == 'Yearly')
        {
            $startDate=Carbon::now()->year.'-04-01';
            $endDate=Carbon::parse(Carbon::now())->addYears(1)->format('Y').'-03-31';
            $d1 = Carbon::parse($startDate)->format('Y-m-d');
            $d2 = Carbon::parse($endDate)->format('Y-m-d');
            $condition = "and start_date between '$d1'  and  '$d2' and created_by = $user->employee_id";
            $condition1 = "where start_date between '$d1'  and  '$d2' and created_by = $user->employee_id ";
        }
        else if($this->request->type == 'Range') {
            if ($this->request->fromDate && $this->request->toDate) {
                $d1 = Carbon::parse($this->request->fromDate)->format('Y-m-d');
                $d2 = Carbon::parse($this->request->toDate)->add('day', 1)->format('Y-m-d');
                $condition = "and start_date between '$d1'  and  '$d2' and created_by = $user->employee_id";
                $condition1 = "where start_date between '$d1'  and  '$d2' and created_by = $user->employee_id";
            }
        }
        
        
        $all = DB::select("select count(DISTINCT event_id) as allCount from dsa_front_t_event as dmc $condition1 ");
        $Followup = DB::select("select count(DISTINCT event_id)  as FollowupCount from dsa_front_t_event as dmc where appointment_status='Followup' $condition");
        $Converted = DB::select("select count(DISTINCT event_id)  as ConvertedCount from dsa_front_t_event as dmc where appointment_status='Converted' $condition");
        $NotInterested = DB::select("select count(DISTINCT event_id)  as NotInterestedCount from dsa_front_t_event as dmc where appointment_status='Not Interested' $condition");
        $WrongNumber = DB::select("select count(DISTINCT event_id)  as WrongNumberCount from dsa_front_t_event as dmc where appointment_status='Wrong Number' $condition");
        $NewAppointment = DB::select("select count(DISTINCT event_id)  as NewAppointmentCount from dsa_front_t_event as dmc where appointment_status='New Appointment' $condition");
        $Renewal = DB::select("select count(DISTINCT event_id)  as RenewalCollectedCount from dsa_front_t_event as dmc where appointment_status='Renewal Collected' $condition");
            
            $data=[
                'All' => $all[0]->allCount,
                'Follow Up' => $Followup[0]->FollowupCount,
                'Converted' => $Converted[0]->ConvertedCount,
                'Wrong Number' => $WrongNumber[0]->WrongNumberCount,
                'Not Interested' => $NotInterested[0]->NotInterestedCount, 
                'New Appointment'  => $NewAppointment[0]->NewAppointmentCount,
                'Renewal Collected'  => $Renewal[0]->RenewalCollectedCount,
            ];
            return response()->json([   
                'data' => $data,
                'error' => false 
            ], 200);


}

