public function addMaterialDetails()
{

    $this->validate($this->request, [
        'categoryID' => 'required',
        'subcategoryID' => 'required',
        'title' => 'required',
        'description' => 'required',
        'language' => 'required',
        'uploadFiles' => 'required'
    ]);


    try{

        $mID=DB::table('dsa_front_m_material')->insertGetId([ 
                'category_id' => $this->request->categoryID, 
                'sub_category_id'=>$this->request->subcategoryID,     
                'title'=>$this->request->title,    
                'description' => $this->request->description, 
                'language'=>$this->request->language,    
                'created_by' =>  '1',  
            ]);

        if($this->request->uploadFiles)
        {
        
             
            if (env('STORAGE_LOCATION') == 'FILE_SYSTEM') {
                //save docs
                $destinationPath = 'uploads/dsa_front/resource_center/';
                $fileInitials = date('YmdHis') . '_' . $this->randomCode(6);
                $file = $this->request->file('uploadFiles');
                $name = $this->request->uploadFiles->getClientOriginalName();
                $fileSize = $this->request->uploadFiles->getSize();
                $contentType = $this->request->uploadFiles->getMimeType();
    
                $file->move($destinationPath, $fileInitials . '.' . $file->getClientOriginalExtension());
                $filePath = $fileInitials . '.' . $file->getClientOriginalExtension();
                try {

                    DB::table('dsa_front_m_material')
                    ->where('mid', $mID)
                    ->update([
                        'upload_file_name' => $name,
                        'upload_file_path' => $filePath,
                        'upload_file_size' => $fileSize,
                        'upload_file_type' => $contentType,
                        'upload_file_datetime' => Carbon::now(),
                        'updated_by'=>1,
                        'updated_at' => Carbon::now(),
                    ]);

                } catch (\Exception $e) {
    
                    DB::rollback();
                    // dd("error--" . $e->getMessage());
                    $errorCode = $e->errorInfo[1];
                    return response()->json([
                        'message' => 'Please contact administrator.' . $e
                    ], 400);
                }
            } 
        }

        if($this->request->uploadcoverphotoFile) 
        {
        
            if (env('STORAGE_LOCATION') == 'FILE_SYSTEM') {
                //save docs
                $destinationPath = 'uploads/dsa_front/resource_center/';
                $fileInitials = date('YmdHis') . '_' . $this->randomCode(6);
                $file = $this->request->file('uploadcoverphotoFile');
                $name = $this->request->uploadcoverphotoFile->getClientOriginalName();
                $fileSize = $this->request->uploadcoverphotoFile->getSize();
                $contentType = $this->request->uploadcoverphotoFile->getMimeType();
    
                $file->move($destinationPath, $fileInitials . '.' . $file->getClientOriginalExtension());
                $filePath = $fileInitials . '.' . $file->getClientOriginalExtension();
                try {

                    DB::table('dsa_front_m_material')
                    ->where('mid', $mID)
                    ->update([
                        'upload_coverphoto_filename' => $name,
                        'upload_coverphoto_filepath' => $filePath,
                        'upload_coverphoto_size' => $fileSize,
                        'upload_coverphoto_type' => $contentType,
                        'upload_coverphoto_datetime' => Carbon::now(),
                        'updated_by'=>1,
                        'updated_at' => Carbon::now(),
                    ]);

                } catch (\Exception $e) {
    
                    DB::rollback();
                    // dd("error--" . $e->getMessage());
                    $errorCode = $e->errorInfo[1];
                    return response()->json([
                        'message' => 'Please contact administrator.' . $e
                    ], 400);
                }
            } 
        }
    
        return response()->json([
            'Status'=> 200,
            'message' => 'Material details save', 
    
        ], 200); 
    }
    catch (\Exception $e) {
        DB::rollback();
        
        return response()->json([
            'Status' => 500,
            'message' => $e->getMessage()
        ], 400);
    }


}

