public function calculateHolidays($tempstartDate1,$endDate){
    $temp;
    $holidayConfig=DB::table('master_holiday_configuration')->first();
    $holidays=DB::table('master_holiday_calendar')->where('deletion_flag',0)->select('holiday_date')->get()->toArray();
    
    $holidayDates=[]; 
    foreach ($holidays as $object) {
        array_push($holidayDates,$object->holiday_date);
    }    
    // array_push($holidayDates,'2022-09-12');
    
    // $tempstartDate1='2022-09-12';
    // $endDate='2022-09-18';
    $totalHolidays=0;
    if($holidayConfig->holiday_config_type==0){
        while (Carbon::parse($tempstartDate1)->format('Y-m-d') <= Carbon::parse($endDate)->format('Y-m-d')) {
            if (Carbon::parse($tempstartDate1)->format('w') == 0||in_array(Carbon::parse($tempstartDate1)->format('Y-m-d'),$holidayDates)) {
                $totalHolidays+=1;
                array_push($holidayDates,Carbon::parse($tempstartDate1)->format('Y-m-d'));
            }
            $tempstartDate1=Carbon::parse($tempstartDate1)->addDays(1);
        }
        
    }
     
    if($holidayConfig->holiday_config_type==1){
        while (Carbon::parse($tempstartDate1)->format('Y-m-d') <= Carbon::parse($endDate)->format('Y-m-d')) {
            if (Carbon::parse($tempstartDate1)->format('l') == "Sunday"||Carbon::parse($tempstartDate1)->format('l') == "Saturday"||
            in_array(Carbon::parse($tempstartDate1)->format('Y-m-d'),$holidayDates)) {
                
                $totalHolidays+=1;
                array_push($holidayDates,Carbon::parse($tempstartDate1)->format('Y-m-d'));
                
            }
            $tempstartDate1=Carbon::parse($tempstartDate1)->addDays(1);
        }
    }
   
     if($holidayConfig->holiday_config_type==2){
        while (Carbon::parse($tempstartDate1)->format('Y-m-d') <= Carbon::parse($endDate)->format('Y-m-d')) {
            if (Carbon::parse($tempstartDate1)->format('w') == 0||(Carbon::parse($tempstartDate1)->format('l') == "Saturday"&&((new ApiController($this->request))->weekOfMonth(strtotime(Carbon::parse($tempstartDate1)->format('Y-m-d')))%2==0))
            ||in_array(Carbon::parse($tempstartDate1)->format('Y-m-d'),$holidayDates)) {
                $totalHolidays+=1;
                array_push($holidayDates,Carbon::parse($tempstartDate1)->format('Y-m-d'));
    
            }
            $tempstartDate1=Carbon::parse($tempstartDate1)->addDays(1);
        }
                   
     }
    
     if($holidayConfig->holiday_config_type==3){
        while (Carbon::parse($tempstartDate1)->format('Y-m-d') <= Carbon::parse($endDate)->format('Y-m-d')) {
            if (Carbon::parse($tempstartDate1)->format('w') == 0||(Carbon::parse($tempstartDate1)->format('l') == "Saturday"&&((new ApiController($this->request))->weekOfMonth(strtotime(Carbon::parse($tempstartDate1)->format('Y-m-d')))%2!=0))
            ||in_array(Carbon::parse($tempstartDate1)->format('Y-m-d'),$holidayDates)) {
                $totalHolidays+=1;
                array_push($holidayDates,Carbon::parse($tempstartDate1)->format('Y-m-d'));
            }
            $tempstartDate1=Carbon::parse($tempstartDate1)->addDays(1);
        }
     }
    
     if($holidayConfig->holiday_config_type==4){
        while (Carbon::parse($tempstartDate1)->format('Y-m-d') <= Carbon::parse($endDate)->format('Y-m-d')) {
            if (Carbon::parse($tempstartDate1)->format('l')=='Thursday'||in_array(Carbon::parse($tempstartDate1)->format('Y-m-d'),$holidayDates)) {
                $totalHolidays+=1;
                array_push($holidayDates,Carbon::parse($tempstartDate1)->format('Y-m-d'));
            }
            $tempstartDate1=Carbon::parse($tempstartDate1)->addDays(1);
        }
         
     }
    
    if($holidayConfig->holiday_config_type==5){
        while (Carbon::parse($tempstartDate1)->format('Y-m-d') <= Carbon::parse($endDate)->format('Y-m-d')) {
            if (Carbon::parse($tempstartDate1)->format('l') == "Sunday"||
            (Carbon::parse($tempstartDate1)->format('l') == "Saturday"&&(Carbon::parse($tempstartDate1)->lastOfMonth(Carbon::SATURDAY)->format('Y-m-d')!=Carbon::parse($tempstartDate1)->format('Y-m-d')))
            ||in_array(Carbon::parse($tempstartDate1)->format('Y-m-d'),$holidayDates)) {
               
                $totalHolidays+=1;

            }
            $tempstartDate1=Carbon::parse($tempstartDate1)->addDays(1);
            
           
        }
         
    }
     
    return  $totalHolidays;
    
}

