        //             'deviation_type' => 'Exprience Deviation',
        //             'deviation_value' => $caseData[0]->applicant_experience,
        //             'remark' => '',
        //             'deviation_status' => 'Open',
        //             // 'rm_code' => DB::table('master_employee')->where('employee_code',  $this->request->RMCode)->value('employee_id'),
        //             // 'zm_code' => DB::table('master_employee')->where('employee_code',  $zmId)->value('employee_id'),
        //            'rm_code' => $rmData->employee_id,
        //            'zm_code' =>  $zmData->employee_id,
        //         //    'rm_code' => $RMID,
        //         // 'zm_code' =>  $ZMID,
        //         ]); 

        //         $rmName = DB::table('master_employee')->where('employee_id',  $rmData->employee_id)->value('employee_name');

        //         DB::table('dsa_t_case_logs')->insert([
        //             'dsa_case_id' => $applicationNo, 
        //             'log_id'=> $dvNo, 
        //             'created_by_name' => 'User',
        //             'log_status' => 'Open', 
        //             'Role'=> 'RM',
        //             'remark' => 'Deviation '.$dvNo.' is assinged to ' .$rmName,
        //             'created_by' => "",
        //             'assign_to_name' => $rmName, 
        //         ]); 


        //         if (env('DSA_EMAIL_FLAG')) {

        //             $discription=  " "."Kindly click the below link to review Experience deviation , for the onboarding of DSA/RA  ".$caseData[0]->applicant_fullname ." application no "." "."<b>".$applicationNo ." </b>.";
    
        //             $data = [
        //                 'Application_No' => $applicationNo, 
        //                 'sender1'=>'Dear RM,',
        //                 'details' => $discription, 
        //                 'link' => "https://ezflouat.insideabc.com/",
        //                 'detail1'=>'Thanks and Regards,',
        //                 'detail2'=>'Aditya Birla Housing Finance.'
        //             ];
    
                
        //             $senderName = DB::table('master_employee')->where('employee_id', $rmData->employee_id)->value('email_id');
        //             Queue::push(new DSAInitiateEmailJob( 
        //                 $senderName,
        //                 explode(',', env('dsa_cc_Email')), 
        //                 "Deviation creation of Experince < 2 ", 
        //                 $data, 
        //             ));
   
    
        //         } 
           
        // } 

        if($caseData[0]->constitution_type == 'Individual' || $caseData[0]->constitution_type =='Proprietor'){
            if($caseData[0]->cibil_score < 600 && $caseData[0]->cibil_score > 1 && $caseData[0]->consent_check==1)
            {
               
                DB::table('dsa_m_case')
                ->where('dsa_case_id', $applicationNo) 
                ->update([
                    'case_status'=> 'Rejected',
                    'rejection_reason'=>'Partner CIBIL score is less than 600.',
                    'rejection_date_time'=>Carbon::now()
                ]);
            }
        }
        

        if($caseData[0]->constitution_type != 'Proprietor'  && $caseData[0]->constitution_type != 'Individual'){
            $isCaseReject=false;
            if(count($directorData)>0){
                foreach ($directorData as $director) {
                    if($director->authorised_flag==1 && $director->cibil_consent_check==1 && ($director->cibil_score<600 && $director->cibil_score>1)){
                        $isCaseReject=true;
                    }
                }
            }

            if($isCaseReject==true){
                DB::table('dsa_m_case')
                    ->where('dsa_case_id', $applicationNo) 
                    ->update([
                        'case_status'=> 'Rejected',
                        'rejection_reason'=>'One or more directors cibil score is less than 600. OR One or more directors age is less than 20.',
                        'rejection_date_time'=>Carbon::now()
                    ]); 

            }
        }

        return $applicationNo;
       
        // return response()->json([
        //             'error'=>false,
        //             'message' => 'data added',
        //             'caseId' => $applicationNo 
        //         ], 200);  
    }
    catch (\Exception $e) {
        DB::rollback();
        dd($e);
        return response()->json([
            'Status' => 500,
            'message' => $e->getMessage()
        ], 400);
    }
    



}

