                    'storage_location' => env('STORAGE_LOCATION')
                ]);

                // dd(".,s,s,",$did);
                // dd($files->filePath);
                if(env('UPLOAD_DMS') == 'server'){
                $dmsID=$this->callUpload($caseid,4,$did,$files->filePath,$files->filePath,$files->contentType);
    
                if($dmsID['error'] == false)
                {
                    DB::table('dsa_front_t_case_attachment')
                    ->where('id', $did) 
                    ->update([
                        'dms_id'=> $dmsID['documentID']
                    ]);  
                  
                //     return response()->json([
