                   // 'https://testapi.karza.in/v3/digilocker/download',//Local
                     'https://ezgatewayuat.insideabc.com/v3/digilocker/download',//Server
                //  'https://ezgateway.insideabc.com/v3/digilocker/download',//prod
                    ['body' => json_encode(
                        [
                            "consent" => "Y",
                            "accessRequestId" => $this->request->accessRequestId,
                            "files"=> [([
                                "uri"=>$response->{'result'}[0]->{'uri'},
                                "pdfB64"=> true,
                                "parsed"=> true,
                                "xml"=> true,
                            ])],
                        ]
                    )]
                );
                $response2 = json_decode($response2->getBody()->getContents());
                $statusCode2 = $response2->{'statusCode'};
                // dd($response2->{'result'}[0]->{'parsedFile'}->{'data'}->{'issuedTo'}->{'photo'}->{'content'});
                if($statusCode==101){
                    $base64string=$response2->{'result'}[0]->{'parsedFile'}->{'data'}->{'issuedTo'}->{'photo'}->{'content'};        
                    $aadharNo=$response2->{'result'}[0]->{'parsedFile'}->{'data'}->{'issuedTo'}->{'uid'};        
                    
                    $bin = base64_decode($base64string);
                    $im = imageCreateFromString($bin);
                    if (!$im) {
                    die('Base64 value is not a valid image');
                    }
                    $uploadpath   = 'uploads/dsa_front/';
        
                    $name=date('YmdHis') . '_' . $this->randomCode(6) . '.png';
                    $img_file =  $uploadpath . $name;
                    imagepng($im, $img_file, 0);

                    $file = $im;
                    $filePath = $name;

                    $fullPath='D:\\API\\public\\uploads\\dsa_front\\'. $name;
                  //  dd($fullPath);
                    $contentType="image/png";

                    if(env('UPLOAD_DMS') == 'server'){
                        $dmsID=$this->callUpload($this->request->caseId,1,$this->randomCode(3),$fullPath,$filePath,$contentType);
                        if($dmsID['error'] == false)
                        {
    
                             $updateData=DB::table('dsa_front_t_case_director')
                             ->where('case_id', $this->request->caseId) 
                             ->where('tid', $this->request->directorId)
                                 ->update([
                                     'director_adhar_file_name' => $name, 
                                     'director_adhar_file_path' => $uploadpath, 
                                     'director_adhaar_verify_flag' => 1, 
                                     'director_dob' => $response['result'][0]['parsedFile']['data']['issuedTo']['dob'],
                                     'director_gender' => $response['result'][0]['parsedFile']['data']['issuedTo']['gender'],
                                     'director_aadhar'=>$aadharNo,
                                     'director_adhar_dms_id' => $dmsID['documentID']
                                    
                             ]);
    
                        }
                        else {
                             return response()->json([
                                 'message' => $dmsID['message']
                             ], 500);
                        }
                    }else{
                    
                         $updateData=DB::table('dsa_front_t_case_director')
                         ->where('case_id', $this->request->caseId) 
                         ->where('tid', $this->request->directorId)
                             ->update([
                                 'director_adhar_file_name' => $name, 
                                 'director_adhar_file_path' => $uploadpath, 
                                 'director_adhaar_verify_flag' => 1, 
                                 'director_dob' => $response['result'][0]['parsedFile']['data']['issuedTo']['dob'],
                                 'director_gender' => $response['result'][0]['parsedFile']['data']['issuedTo']['gender'],
                                 'director_aadhar'=>$aadharNo,
                         ]);

                    }
        
                    return response()->json([ 
                        'error'=>false,
                        'message' => 'Adhaar Number is verified',
                    ], 200);
    
    
                }else{
                    return response()->json([
                        'error'=>true,
                        'message' => 'Aadhar verification failed, please try again.'
                    ], 400);
                }
                return response()->json([
                    'error'=>true,
                    'message' => 'Aadhar verification failed, please try again.' 
                ], 400);
            }else{
                return response()->json([
                    'error'=>true,
                    'message' =>  "Aadhar verification failed, please try again." 
                ], 400);
            }
        }
       
 

    } catch (\Exception $e) {
         dd("......".$e);
        return response()->json([
            'error'=>true,
            'message' => 'Aadhar verification failed, please try again.'
        ], 200);
    }
}  


