public function cibilEmail($id,$type,$file,$link=null)
{

    if (env('DSA_FRONT_EMAIL_FLAG')) {
      
        $files = [];
        array_push($files, env('TEJORA_IMAGE_FOLDER').$file); 

        // $discription=  " "."Thank you for connecting with Aditya Birla, Please find attachment of cibil report.  </b>";
        $discription=  " "."Please find the enclosed your CIBIL report .To view your CIBIL report ,please double click on the attachment .To open this file you need Adobe Acrobat Reader. <br><strong> This is Soft pull (soft credit check) and DOES NOT AFFECT your Credit Score as you're not applying for credit.</strong> <br> Your Password to open the PDF is your 10 Digit PAN number .";
        if($link == null){
            $loginLink = "https://ezportaluat.adityabirlacapital.com/";
        } else {
            $loginLink = $link;
        }
        $data = [
            'Application_No' =>$id, 
            'sender1'=>'Dear Team,',
            'details' => $discription,
            // 'link' => "https://ezportaluat.adityabirlacapital.com/",
            'link' => $loginLink,
            'detail1'=>'Thanks and Regards,',
            'detail2'=>'Aditya Birla Housing Finance.', 
            'files' => $files
        ];
        $senderName="";
        if($type == 'case')
        {
            $senderName = DB::table('dsa_front_m_case_master')->where('case_id', $id)->value('email_id');
        
        }
        else  if($type == 'director') {
            $senderName = DB::table('dsa_front_t_case_director')->where('tid', $id)->value('director_email');
           
        }
        
        // dd('================== ',$senderName);
        Queue::push(new RCUInitiateEmailJob( 
            $senderName,
             explode(',', env('dsa_front_cc_Email')), 
            "Cibil Report", 
            $data, 
            
           ));

        //    dd("====");
    } 
}


public function getResourceCenterCategories()
    {
        $user = $this->request->auth;

        
        try {
            $categories = DB::table('dsa_front_t_category_role as dftcr')
                ->leftJoin('dsa_front_m_category as dfmc', 'dfmc.category_id', '=', 'dftcr.category_id')
                ->where('dfmc.deleted_at', null)
                ->where('dftcr.role', $user->partnerType)
                ->select('dfmc.category_id', 'dfmc.category_name')
                ->distinct()
                ->get()
                ->toArray();

            $subCategories = DB::table('dsa_front_m_category')
                ->where('deleted_at', null)
                ->whereIn('parent', array_column($categories, 'category_id'))
                ->distinct()
                ->get()
                ->toArray();

            $isCompleted = DB::table('dsa_front_t_resource_center_status')
                ->where('deleted_at', null)
                ->where('mobile', $user->mobile)
                ->first();



            // DB::table('dsa_front_t_category_documents_user_progress')->updateOrInsert(
            //         ['mobile' => $this->request->mobile, 'document_id' => $this->request->document_id],
            //         ['mobile' => $this->request->mobile, 'document_id' => $this->request->document_id, 'status' => $this->request->status]
            // );


            for ($i = 0; $i < count($subCategories); $i++) {
                $ind = array_search($subCategories[$i]->parent, array_column($categories, 'category_id'));
                if ($ind !== false) {
                    $categories[$ind]->childs[] = array('category_id' => $subCategories[$i]->category_id, 'category_name' => $subCategories[$i]->category_name);
                }
            }


            return response()->json([
                'error' => false,
                'data' =>  $categories,
                'isCompleted' => $isCompleted ? true : false
            ], 200);
        } catch (\Exception $e) {
            dd($e->getMessage());
            return response()->json([
                'error' => true,
                'message' => 'Internal error.'
            ], 200);
        }
    }

    public function getResourceCenterDocuments()
    {
        $user = $this->request->auth;
        try {
            $categories = DB::table('dsa_front_t_category_role as dftcr')
                ->leftJoin('dsa_front_m_category as dfmc', 'dfmc.category_id', '=', 'dftcr.category_id')
                ->where('dfmc.deleted_at', null)
                ->where('dftcr.role', $user->partnerType)
                ->select('dfmc.category_id', 'dfmc.category_name')
                ->distinct()
                ->get()
                ->toArray();

            $subCategories = DB::table('dsa_front_m_category')
                ->where('deleted_at', null)
                ->whereIn('parent', array_column($categories, 'category_id'))
                ->distinct()
                ->get()
                ->toArray();

                $myLanguage = DB::table('dsa_front_m_category_documents as dcd')
                ->leftJoin('dsa_front_t_category_documents_user_progress as dcup', 'dcd.id', '=', 'dcup.document_id')
                ->where('dcup.mobile', $user->mobile)
                ->select('dcd.language')
                ->first();
            $language=null;
            if($myLanguage)
            {
               $language=$myLanguage->language;  
            }

            // dd(array_column($subCategories, 'category_id'));

            $documents = DB::table('dsa_front_m_category_documents as dfmcd')
            
            ->leftJoin('dsa_front_t_category_documents_user_progress as dftcd', function($join) use($user)
            {
                $join->on('dftcd.document_id', '=', 'dfmcd.id');
                $join->where('dftcd.mobile', $user->mobile);
            })
                // ->leftJoin('dsa_front_t_category_documents_user_progress as dftcd', 'dftcd.document_id', '=', 'dfmcd.id' )
                ->where('dfmcd.is_deleted', 0)
                // ->where('dftcd.mobile', $this->request->mobile)
                ->where('dfmcd.deactivation_date', '>', carbon::now()->format('Y-m-d'))
                ->whereIn('dfmcd.category_id', array_column($subCategories, 'category_id'))
                ->select('dfmcd.id', 'dfmcd.category_id', 'dfmcd.title', 'dfmcd.description', 'dfmcd.photo', 'dfmcd.attachment', 'dfmcd.contentType', 'dfmcd.language', 'dfmcd.isMandatory', 'title', 'dftcd.status')
                ->get();


            return response()->json([
                'error' => false,
                'data' =>  $documents ,
                'language' => $language,
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'error' => true,
                'message' => 'Internal error.'
            ], 200);
        }
    }

    public function updateResourceCenterDocumentStatus()
    {
        $this->validate($this->request, [
            'mobile' => 'required',
            'status' => 'required',
            'document_id' => 'required',
        ]);
        try {


            DB::table('dsa_front_t_category_documents_user_progress')->updateOrInsert(
                ['mobile' => $this->request->mobile, 'document_id' => $this->request->document_id],
                ['mobile' => $this->request->mobile, 'document_id' => $this->request->document_id, 'status' => $this->request->status]
            );

            return response()->json([
                'error' => false,
                'data' =>  'Status changed'
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'error' => true,
                'message' => 'Internal error.',
                'messageq' => $e->getMessage()
            ], 200);
        }
    }

    public function markResourceCenterCompleted()
    {
        $this->validate($this->request, [
            'mobile' => 'required'
        ]);
        try {
            DB::table('dsa_front_t_resource_center_status')->updateOrInsert(
                ['mobile' => $this->request->mobile],
                ['mobile' => $this->request->mobile, 'status' => 'Completed']
            );

            return response()->json([
                'error' => false,
                'data' =>  'Thank you.'
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'error' => true,
                'message' => 'Internal error.',
                'messageq' => $e->getMessage()
            ], 200);
        }
    }

