public function dsaUpdateCurrentAddress(){
    $this->validate($this->request, [
       'caseId' => 'required',
       'address_type' => 'required',
       'checkValue' => 'required', 
       'rid' => 'required',

   ]);

   $data = DB::table('dsa_front_t_case_address')
   ->where('aid', $this->request->rid)->get();

    try { 

         if($this->request->address_type == 'Permanent') {
            if($this->request->checkValue == 1) {
                DB::table('dsa_front_m_case_master')->where('case_id', $this->request->caseId)
                ->update([ 
                    'permanent_address_flag'=>'1',
                    'permanent_adhaar_address_proof'=>'1'  
                ]);

                DB::table('dsa_front_t_case_address')->insert(  
                    [
                        'case_id' => $data[0]->case_id,
                        'address_type' => 'Permanent',
                        'addressline1' => $data[0]->addressline1,
                        'addressline2' => $data[0]->addressline2,
                        'pincode' => $data[0]->pincode,
                        'area' => $data[0]->area,
                        'landmark' => $data[0]->landmark,
                        'city' => $data[0]->city,
                        'district' => $data[0]->district,
                        'state' => $data[0]->state,
                        'country' => $data[0]->country,
                        'resident_type' => '2',
                    
                    ] 
                );
            }
            else if($this->request->checkValue == 0) {
                DB::table('dsa_front_m_case_master')->where('case_id', $this->request->caseId)
                ->update([ 
                    'permanent_address_flag'=>'0',
                    'permanent_adhaar_address_proof'=>'0'  
                ]);

                DB::table('dsa_front_t_case_address')
                ->where('case_id', $this->request->caseId)
                ->where('address_type','Permanent')
               ->delete();
            }

        }

        else if($this->request->address_type == 'Office')
        {
            if($this->request->checkValue == 1) {
            DB::table('dsa_front_m_case_master')->where('case_id', $this->request->caseId)
            ->update([
                'office_address_flag'=>'1'
            ]);

            DB::table('dsa_front_t_case_address')->insert(  
                [
                    'case_id' => $data[0]->case_id,
                    'address_type' => 'Office',
                    'addressline1' => $data[0]->addressline1,
                    'addressline2' => $data[0]->addressline2,
                    'pincode' => $data[0]->pincode,
                    'area' => $data[0]->area,
                    'landmark' => $data[0]->landmark,
                    'city' => $data[0]->city,
                    'district' => $data[0]->district,
                    'state' => $data[0]->state,
                    'country' => $data[0]->country,
                    'resident_type' => '2',
                   
                ] 
            );
         }
            else {
                DB::table('dsa_front_m_case_master')->where('case_id', $this->request->caseId)
                ->update([ 
                    'office_address_flag'=>'0'
                ]);

                DB::table('dsa_front_t_case_address')
                ->where('case_id', $this->request->caseId)
                ->where('address_type','Office')
               ->delete();
            }
        }



       return response()->json([
        'error'=>false,
        'message' =>'Address updated.'
        ], 200);

           } catch (\Exception $e) {
    //    dd(";;;",$e);
    dd($e->getMessage());
       return response()->json([

           'error'=>true,
           'message' => 'Address not updated, please try again.'
       ], 200);
   }

}

public function dsaGetBranch(){
    $user = $this->request->auth; 

   $this->validate($this->request, [
       'searchTerm' => 'nullable'
   ]);

        $query = DB::table('dsa_front_m_branch_master as dfbm')
        ->leftJoin('user_branch_mapping as ubm', 'dfbm.id', '=', 'ubm.branch_id')
        ->where('ubm.employee_id',$user->employee_id)
        ->where(function ($query) {
            $query->where('branch_desc', 'like', '%' . $this->request->searchTerm . '%');
        })
        ->select('dfbm.id','dfbm.branch_short_code','dfbm.branch_desc')
        ->orderBy('id', 'desc');

       return response()->json([
        'error'=>false,
        'message' =>'Branch available.',
        'data'=> $query->get()
        ], 200);

}

