public function DSAupdateConsent()
{
  //  $user = $this->request->auth;
    $this->validate($this->request, [
       'caseId' => 'required',
       'consentType' => 'required'  
   ]);
   $column1="";$column2="";$column3="";
   if($this->request->consentType == 'GST')
   {
        $column1="gst_applicable";
        $column2="gst_number";
        $column3="gst_verify_flag";
   }
   else  if($this->request->consentType == 'MSME')
   {
        $column1="msme_applicable";
        $column2="msme_number";
        $column3="msme_verify_flag";
   }
   else  if($this->request->consentType == 'TRIN')
   {
        $column1="trin_applicable";
        $column2="trin_number";
        $column3="trin_verify_flag";
   }
   else  if($this->request->consentType == 'Legal')
   {
        $column1="legal_option";
        $column2="legal_description";
        $column3="legal_verify_flag";
   }


   try { 

   if($this->request->consentType == 'relation')
   {
        $updateData=DB::table('dsa_front_m_case_master')
        ->where('case_id', $this->request->caseId) 
            ->update([
                'aditya_birla_consent' => $this->request->checked, 
                'aditya_birla_applicable' => $this->request->option, 
        ]);

   }    
   else {
        $updateData=DB::table('dsa_front_m_case_master')
        ->where('case_id', $this->request->caseId) 
            ->update([
                $column1 => $this->request->option, 
                $column2 => $this->request->value, 
                $column3 => $this->request->checked, 
        ]);
   }

    return response()->json([
        'error'=>false,
        'message' =>'Consent updated.',
        ], 200);
   } catch (\Throwable $th) {
        return response()->json([
        'error'=>true,
        'message' =>'Consent unchecked failed, please try again.',
        ], 200);
   }
}

 public function captcha($mobileNo,$log=null)
    {   
        // dd('uploads/dsa_front/'.date('YmdHis') . '_' . $this->randomCode(6) . '.png');
            $IP = $this->get_IP_address();




            $width = 130;
            $height = 30;
            $font_size = 20;
            $font = "./downloads/verdana.ttf";
            $font = realpath($font);
            $chars_length = 6;

            $captcha_characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';

            $image = imagecreatetruecolor($width, $height);
            $bg_color = imagecolorallocate($image, 204, 31, 53);
            $font_color = imagecolorallocate($image, 255, 255, 255);
            imagefilledrectangle($image, 0, 0, $width, $height, $bg_color);

            //background random-line
            $vert_line = round($width / 15);
            $color = imagecolorallocate($image, 255, 255, 255);
            for ($i = 0; $i < $vert_line; $i++) {
                imageline($image, mt_rand(0, $width), mt_rand(0, $height), mt_rand(0, $height), mt_rand(0, $width), $color);
            }
         
            $xw = ($width / $chars_length);
            $x = 0;
            $font_gap = $xw / 2 - $font_size / 2;
            $digit = '';
            for ($i = 0; $i < $chars_length; $i++) {
                $letter = $captcha_characters[mt_rand(0, strlen($captcha_characters) - 1)];
                $digit .= $letter;
                if ($i == 0) {
                    $x = 0;
                } else {
                    $x = $xw * $i;
                }
                imagettftext($image, $font_size, mt_rand(-20, 20), $x + $font_gap, mt_rand(22, $height - 5), $font_color, $font, $letter);
            } 
         

            // record token in session variable
            // $_SESSION['captcha_token'] = strtolower($digit);

            // display image
            header('Content-Type: image/png');

            // $base64string=$request['result']['dataFromAadhaar']['image'];        
            // $bin = base64_decode($base64string);
            // $im = imageCreateFromString($bin);
            // if (!$im) {
            // die('Base64 value is not a valid image');
            // }
            $uploadpath   = 'uploads/dsa_front/';

            $name=date('YmdHis') . '_' . $this->randomCode(6) . '.png';
            $img_file =  $uploadpath . $name;
            // if ($this->request->log) {
                // dd($img_file);
            // }
            imagepng($image, $img_file, 0);



         //   imagepng($image);
         //   imagedestroy($image);
            $updateData=DB::table('dsa_front_m_partner')
                        ->where('phone_no', $this->request->mobileNo) 
                        ->update([
                            // 'login_captcha' => $digit, 
                            'login_captcha' => "ABCDEF", 
                            'captcha_path' => $name
                        ]);
            // if($log){
                // dd($log);
                // dd(gettype(imagepng($image, $img_file, 0)));
                // return imagepng($image, $img_file, 0);
                return 'D:\\API\\public\\uploads\\dsa_front\\'.$name;
            // }
    }

    function get_IP_address()
    {
        $ipaddress = '';
        if (isset($_SERVER['HTTP_CLIENT_IP']))
            $ipaddress = $_SERVER['HTTP_CLIENT_IP'];
        else if (isset($_SERVER['HTTP_X_FORWARDED_FOR']))
            $ipaddress = $_SERVER['HTTP_X_FORWARDED_FOR'];
        else if (isset($_SERVER['HTTP_X_FORWARDED']))
            $ipaddress = $_SERVER['HTTP_X_FORWARDED'];
        else if (isset($_SERVER['HTTP_FORWARDED_FOR']))
            $ipaddress = $_SERVER['HTTP_FORWARDED_FOR'];
        else if (isset($_SERVER['HTTP_FORWARDED']))
            $ipaddress = $_SERVER['HTTP_FORWARDED'];
        else if (isset($_SERVER['REMOTE_ADDR']))
            $ipaddress = $_SERVER['REMOTE_ADDR'];
        else
            $ipaddress = 'UNKNOWN';
        return $ipaddress;
    }

