    public function deleteIFSCCodeMaster()
    {
            //  $user = $this->request->auth;
            $this->validate($this->request, [
                'id' => 'required'
            ]); 

            try {

                $isRecordAlreadyDeleted= DB::table('dsa_front_m_ifsc_master')
                ->where('id', $this->request->id)
                ->where('is_deleted',1)
                ->select()
                ->first();
        
                if($isRecordAlreadyDeleted){
                    return response()->json([
                        'error'=>true,
                        'message' => 'Record already deleted.'
                    ], 200);
                }
                
        
                $isRecordAvailable= DB::table('dsa_front_m_ifsc_master')
                ->where('id', $this->request->id)
                ->select()
                ->first();
        
                if($isRecordAvailable==null){
                    return response()->json([
                        'error'=>false,
                        'message' => 'Record not found.'
                        ], 200);
                }
                DB::table('dsa_front_m_ifsc_master')
                ->where('id', $this->request->id)
                ->update([
                    'is_deleted'=>1,
                ]);
        
                    return response()->json([
                    'error'=>false,
                    'message' => 'Record deleted.'
                ], 200);
            } catch (\Exception $e) {
                dd($e);
                $errorCode = $e->errorInfo[1];
                if ($errorCode == 1062 || $errorCode == 2627) {
                    return response()->json([
                    'error'=>true,
                        'message' => 'Record already deleted.'
                    ], 400);
                }
                return response()->json([
                    'error'=>true,
                    'message' => 'Record not deleted, please try again.'
                ], 400);
            }
    }

