public function addresourcecenterDocument()
{

 $this->validate($this->request, [
     'categoryId' => 'required',
     'title' => 'required',
     'description' => 'required',
     'language' => 'required',
     'contentType' => 'required',
     'isMandatory' => 'required',
     'deactivationDate' => 'required',
 ]);


 try{

    $did= DB::table('dsa_front_m_category_documents')->insertGetId([
        'category_id' => $this->request->categoryId,
        'title' => $this->request->title,
        'description' => $this->request->description,
        'language' => $this->request->language,
        'contentType' => $this->request->contentType,
        'isMandatory'=>$this->request->isMandatory,
        'deactivation_date'=>$this->request->deactivationDate,
        'created_by' => 1
    ]);

     if($this->request->photo)
     {
        
         if (env('STORAGE_LOCATION') == 'FILE_SYSTEM') {
             //save docs
             $destinationPath = 'uploads/dsa_front/resource_center/';
             $fileInitials = date('YmdHis') . '_' . $this->randomCode(6);
  
             $file = $this->request->file('photo');
            // dd('111111111111111111',$file); 
             $name = $this->request->photo->getClientOriginalName();
              $fileSize = $this->request->photo->getSize();
             $contentType = $this->request->photo->getMimeType();
  
             $file->move($destinationPath, $fileInitials . '.' . $file->getClientOriginalExtension());
             $filePath = $fileInitials . '.' . $file->getClientOriginalExtension();
             try {
                    DB::table('dsa_front_m_category_documents')
                    ->where('id', $did) 
                    ->update([
                        'photo'=>  $destinationPath.$filePath
                    ]);
             } catch (\Exception $e) {
  
                 DB::rollback();
                 dd("error--" . $e->getMessage());
                 $errorCode = $e->errorInfo[1];
                 return response()->json([
                     'message' => 'Please contact administrator.' . $e
                 ], 400);
             }
         } 
     }

     if($this->request->file)
     {
        
         if (env('STORAGE_LOCATION') == 'FILE_SYSTEM') {
             //save docs
             $destinationPath = 'uploads/dsa_front/resource_center/';
             $fileInitials = date('YmdHis') . '_' . $this->randomCode(6);
  
             $file = $this->request->file('file');
            // dd('111111111111111111',$file); 
             $name = $this->request->file->getClientOriginalName();
              $fileSize = $this->request->file->getSize();
             $contentType = $this->request->file->getMimeType();
  
             $file->move($destinationPath, $fileInitials . '.' . $file->getClientOriginalExtension());
             $filePath = $fileInitials . '.' . $file->getClientOriginalExtension();
             try {
                    DB::table('dsa_front_m_category_documents')
                    ->where('id', $did) 
                    ->update([
                        'attachment'=>  $destinationPath.$filePath
                    ]);
             } catch (\Exception $e) {
  
                 DB::rollback();
                 dd("error--" . $e->getMessage());
                 $errorCode = $e->errorInfo[1];
                 return response()->json([
                     'message' => 'Please contact administrator.' . $e
                 ], 400);
             }
         } 
     } 
 
     return response()->json([
         'Status'=> 200,
         'message' => 'Document Added', 
 
     ], 200); 
 }
 catch (\Exception $e) {
     DB::rollback();
    
     return response()->json([
         'Status' => 500,
         'message' => $e->getMessage()
     ], 400);
 }


}


