public function getResourcedocumentList()
{
          //  $user = $this->request->auth;
          $this->validate($this->request, [
            'searchTerm' => 'nullable',
            'perPage' => 'nullable',
        ]);


        $query = DB::table('dsa_front_m_category_documents as dcd')
        ->leftJoin('dsa_front_m_category as dcm', 'dcm.category_id', '=', 'dcd.category_id')
        ->where('dcd.is_deleted',0)
        ->orderBy('dcd.id', 'desc');

        $query->where(function ($query) {
            $query->where('dcd.title', 'like', '%' . $this->request->searchTerm . '%')
                ->orWhere('dcd.description', 'like', '%' . $this->request->searchTerm . '%')
                ->orWhere('dcd.contentType', 'like', '%' . $this->request->searchTerm . '%')
                ->orWhere('dcd.language', 'like', '%' . $this->request->searchTerm . '%')
                ->orWhere('dcd.id', 'like', '%' . $this->request->searchTerm . '%'); 
        });

        if($this->request->perPage)
        {
            $perPage = $this->request->perPage; 
            $list = $query->paginate($perPage);
        
        }
        else{
            $list = $query->get();
        }

        return response()->json($list, 200);
}



public function dsaDigilockerAdharVerification()
{
//  $user = $this->request->auth;
    $this->validate($this->request, [
       'caseId' => 'required'
   ]);


try { 
$client = new \GuzzleHttp\Client([
    'headers' => [
        'Content-Type' => 'application/json',
        'account-id' => '13136e72fa76/1d15b94c-be5b-4d0a-9bba-0cd4d3a8a485',
        'api-key'=>'41353d4d-1944-437d-b7b0-dac5043c466a'
    ],
    'verify'=>false
]);

$mobileNo = DB::table('dsa_front_m_case_master')->where('case_id', $this->request->caseId)->value('phone_number');

$referenceID=Carbon::now()->format('YmdHis'). $mobileNo;

DB::table('dsa_front_m_case_master')
->where('case_id', $this->request->caseId)
->update([
    'reference_id' => $referenceID,  
    'is_adhar_error' => 0,  
        'adhar_error' => NULL, 
]);

$response = $client->post(
    // 'https://api.kyc.idfy.com/document-fetcher/digilocker/api/fetch-documents',
    'https://ezgatewayuat.insideabc.com/document-fetcher/digilocker/api/fetch-documents',
     ['body' => json_encode(
         [
      
             "reference_id" => $referenceID,
             "key_id" => "cad7df9e-8a5f-4175-9d8a-629e08cc39ac",
             "ou_id"=>"13136e72fa76",
             "callback_url"=>"https://ezgatewayuat.adityabirlacapital.com/api/dsaDigilockerAdharCallbackUrl",
