public function getbranchMaster()
{
        //  $user = $this->request->auth;
        $this->validate($this->request, [
            'searchTerm' => 'nullable',
            'perPage' => 'nullable',
        ]);

        $query = DB::table('dsa_front_m_branch_master')  
        ->where('deletion_flag',0)
        ->where(function ($query) {
            $query->where('branch_short_code', 'like', '%' . $this->request->searchTerm . '%')
                ->orWhere('branch_desc', 'like', '%' . $this->request->searchTerm . '%')
                ->orWhere('branch_desc_l', 'like', '%' . $this->request->searchTerm . '%');
        });
 

        if($this->request->perPage)
        {
            $perPage = $this->request->perPage; 
            $list = $query->paginate($perPage);
        
        }
        else{
            $list = $query->get();
        }

        return response()->json($list, 200);
}

public function addbranchMaster()
{
        //  $user = $this->request->auth;
        $this->validate($this->request, [
            'branchShortCode' => 'required',
            'branchName' => 'required',
            'branchDescription' => 'required',
        ]);

        try {

            $isRecordFound=DB::table('dsa_front_m_branch_master')
            ->where('branch_desc', $this->request->branchName) 
            ->where('deletion_flag',0)
            ->select()
            ->first();
        
            if($isRecordFound){
                return response()->json([
                    'error'=>false,
                    'message' => 'Record already added.'
                ], 200);
            }

            DB::table('dsa_front_m_branch_master')->insert([
            'branch_short_code' => $this->request->branchShortCode,
            'branch_desc' => $this->request->branchName,
            'branch_desc_l' => $this->request->branchDescription,
            ]);
        
                return response()->json([
                'error'=>false,
                'message' => 'Branch added.'
            ], 200);
        } catch (\Exception $e) {
            $errorCode = $e->errorInfo[1];
            if ($errorCode == 1062 || $errorCode == 2627) {
                return response()->json([
                'error'=>true,
                    'message' => 'Record already exist.'
                ], 400);
            }
            return response()->json([
                'error'=>true,
                'message' => 'Record not updated, please try again.'
            ], 400);
        }
}

public function updatebranchMaster()
{
        //  $user = $this->request->auth;
        $this->validate($this->request, [
            'id' => 'required',
            'branchShortCode' => 'required',
            'branchName' => 'required', 
            'branchDescription' => 'required', 
        ]);

        try {

            $isRecordFound=DB::table('dsa_front_m_branch_master')
            ->where('id', $this->request->id) 
            ->where('deletion_flag',0)
            ->select()
            ->first();
        
            if($isRecordFound==null){
                return response()->json([
                    'error'=>false,
