                    'branch_desc_l' => $this->request->branchDescription,
                ]);
        
                return response()->json([
                'error'=>false,
                'message' => 'Record updated.'
            ], 200);
        } catch (\Exception $e) {
            $errorCode = $e->errorInfo[1];
            if ($errorCode == 1062 || $errorCode == 2627) {
                return response()->json([
                'error'=>true,
                    'message' => 'Record already exist.'
                ], 400);
            }
            return response()->json([
                'error'=>true,
                'message' => 'Record not updated, please try again.'
            ], 400);
        }
}


public function deletebranchMaster()
{
        //  $user = $this->request->auth;
        $this->validate($this->request, [
            'id' => 'required' 
        ]);

        try {

            $isRecordAlreadyDeleted= DB::table('dsa_front_m_branch_master')
            ->where('id', $this->request->id)
            ->where('deletion_flag',1)
            ->select()
            ->first();
    
            if($isRecordAlreadyDeleted){
                return response()->json([
                    'error'=>true,
                    'message' => 'Record already deleted.'
                ], 200);
            }
            
    
            $isRecordAvailable= DB::table('dsa_front_m_branch_master')
            ->where('id', $this->request->id)
            ->select()
            ->first();
    
            if($isRecordAvailable==null){
                return response()->json([
                    'error'=>false,
                    'message' => 'Record not found.'
                    ], 200);
            }
            DB::table('dsa_front_m_branch_master')
            ->where('id', $this->request->id)
            ->update([
                'deletion_flag'=>1,
            ]);
    
                return response()->json([
                'error'=>false,
                'message' => 'Record deleted.'
            ], 200);
        } catch (\Exception $e) {
