public function getResourceSubcategoryMaster()
{
          //  $user = $this->request->auth;
          $this->validate($this->request, [
            'searchTerm' => 'nullable',
            'perPage' => 'nullable',
        ]);

        $query = DB::table('dsa_front_m_sub_category as resourceSubCat')
        ->leftJoin('dsa_front_m_category as resourceCat', 'resourceCat.category_id', '=', 'resourceSubCat.category_id')
        ->where('resourceSubCat.is_deleted',0)
        ->where('resourceSubCat.subcategory_name', 'like', '%' . $this->request->searchTerm . '%')
        ->orderBy('resourceSubCat.sub_category_id', 'desc')
        ->select('resourceSubCat.*','resourceCat.category_name');

        if($this->request->perPage)
        {
            $perPage = $this->request->perPage; 
            $list = $query->paginate($perPage);
        
        }
        else{
            $list = $query->get();
        }

        return response()->json($list, 200);
}

