public function verifyDirectorMobileOTP()
        {
        
            $this->validate($this->request, [
                'mobileNo' => 'required',
                'otp' => 'required',
                'directorId'=>'required',
                'caseId'=>'required'
            ]);
        
            $checkMobileVerifyFlag = DB::table('dsa_front_t_case_director')
                                ->where('tid', $this->request->directorId)
                                ->where('case_id', $this->request->caseId)
                                ->where('director_mobile', $this->request->mobileNo)
                                ->value('isMobileVerified');
    
            if($checkMobileVerifyFlag == 1)
            {
                return response()->json([
                    'message' => 'Mobile number already verified',
                    'error'=>true
                ], 200);
            }  
            else 
            {
              
                $otpSendedTime = DB::table('dsa_front_t_case_director')
                                ->where('tid', $this->request->directorId)
                                ->where('case_id', $this->request->caseId)
                                ->where('director_mobile', $this->request->mobileNo)
                                ->where('verify_mobile_otp', $this->request->otp)
                                ->value('mobile_otp_time');  
            
                $endTime = Carbon::parse($otpSendedTime)->addMinutes(3)->format('Y-m-d H:i:s');
            
                if ($otpSendedTime == null)
                {
                    return response()->json([
                        'status'=> 500,
                        'message' => 'OTP is invalid, Please enter valid OTP',
                        'error'=>true
                    ], 200);
                
                }
                else {
                    if($endTime < Carbon::parse(carbon::now())->format('Y-m-d H:i:s'))
                    {
                        return response()->json([
                            'status'=> 500,
                            'message' => 'OTP is expired' ,
                            'error'=>true
                        ], 200);
                    }
                    else {
                        $updateData=DB::table('dsa_front_t_case_director')
                        ->where('tid', $this->request->directorId)
                        ->where('case_id', $this->request->caseId)
                        ->where('director_mobile', $this->request->mobileNo)
                        ->where('verify_mobile_otp', $this->request->otp) 
                        ->update([
                            'isMobileVerified' => 1,
                        ]);
                                
                        return response()->json([
                            'status'=> 200,
                            'message' => 'Mobile No Verified',
                            'error'=>false
                        ], 200); 
                    }
                }
            } 
        }

