                        ->where('tid', $this->request->directorId)
                            ->update([
                                'other_adhar_file_name' => $fileInitials . '.' . $file->getClientOriginalExtension(), 
                                'other_adhar_file_path' => $destinationPath, 
                                'other_adhar_dms_id'=>$dmsID['documentID'] 
                        ]);
                        
                        // unlink($fullPath);
                        return response()->json([
                            'error'=>false,
                           'message' => 'Attachment\'s saved.'
                       ], 200);
                    }
                    else {
            
                        return response()->json([
                            'error'=>true,
                            'message' => $dmsID['message']
                        ], 500);
                    }
                }else{
                        $updateData=DB::table('dsa_front_t_case_director')
                        ->where('case_id', $this->request->caseId) 
                        ->where('tid', $this->request->directorId)
                            ->update([
                                'other_adhar_file_name' => $fileInitials . '.' . $file->getClientOriginalExtension(), 
                                'other_adhar_file_path' => $destinationPath, 
                        ]);
        
             
                        return response()->json([
                            'error'=>false,
                           'message' => 'Attachment\'s saved.'
                       ], 200);
                }
             } 
        
            return response()->json([
                'error'=>false,
                'message' => 'Applicant photo saved'
            ], 200);
    }    
    
    
    public function getDsaOnboardingCount1()
    {
        try {
            $results = DB::select("select
            (select count(*)  from dsa_front_m_case_master  where stage_count < 8) as 'INTERESTED',
            (select count(*)  from dsa_front_m_case_master where stage_count = 8) as 'APPLICATION',
                 (select count(*) from dsa_m_case where case_status in ('In Progress') )  as 'Under Review',
                 (select count(*) from dsa_m_case where case_status in ('Approved') )  as 'Agreement In Progress',
                 (select count(*) from dsa_m_case where case_status in ('Completed'))   as 'Onboarding' ,
                (select count(*) from dsa_front_m_partner where phone_no not in
                (select phone_number from dsa_front_m_case_master))   as 'partnerCount'");

            $resultsData = DB::select("SELECT me.employee_code as 'RM Code',dfp.partner_id as 'Lead Id',dcm.new_case_id as 'Application Id',dcm.case_id as 'Case Id',me.employee_name as 'RM Name',dfp.branch_name as 'Branch Name',
                dfp.partner_name as 'Applicant Name',dfp.created_at as 'Lead Creation Date time',
                dcm.created_at as 'Application Start Date & Time',dcm.updated_at as 'Application Submit Date & Time',
                dcrd.created_at as 'RCU Initiation Date',CASE WHEN dcrd.rcu_status='Positive' OR dcrd.rcu_status='Negative' THEN dcrd.updated_at else NULL end as 'RCU Closer Date',dmc.case_status as 'Status'
                           


                FROM dsa_front_m_partner as dfp
                left join master_employee as me on dfp.created_by=me.employee_id
                left join dsa_front_m_case_master  dcm on dfp.phone_no=dcm.phone_number
                left join dsa_case_rcu_details  dcrd on dcm.new_case_id=dcrd.dsa_case_id
                left join dsa_m_case  dmc on dcm.new_case_id=dmc.dsa_case_id order by dfp.partner_id");

                
                // dd($results);

                return response()->json([
                    'error'=>false,
                    'data'=>$results,
                    'resultsData'=> $resultsData
                ], 200); 
        } catch (\Exception $e) {
            // dd($e);
            return response()->json([
                'status'=> 400,
                'message' => 'Not able to get count.',
                'error'=>true
            ], 400); 
        }
    }
    
