    public function getTrainingReportDetails()
        {
            try {
                $whereClause = "";
                if($this->request->has('formDate')&&$this->request->has('toDate')&&$this->request->formDate&&$this->request->toDate){
                    $whereClause = " and DATE_FORMAT(dfmp.created_at,'%Y-%m-%d') BETWEEN '" . $this->request->formDate . "' and '" . $this->request->toDate."'";
                }

                $getPrev = DB::select("SELECT DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 1 YEAR), '%Y-12-01') AS previousDay");
                $getNext = DB::select("SELECT DATE_ADD(CURDATE(), INTERVAL 1 DAY) AS nextDay");
                //$getNext = DB::select("SELECT DATE_ADD(DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 1 YEAR), '%Y-12-%d'), INTERVAL 1 MONTH) AS nextDay");
                // print_r($getPrev[0]->previousDay);
                // print_r($getNext[0]->nextDay);
                $previousDay = $getPrev[0]->previousDay;
                $nextDay = $getNext[0]->nextDay;
                
                $results = DB::select("SELECT dfmp.partner_name, dftrcs.status,dftrcs.created_at,dfmp.phone_no as dsa_phone,dfmp.email_id as dsa_email, 
                me.employee_name,me.employee_code,me.contact_number as sm_phone,me.email_id as sm_email,me.employee_code,dfmp.sm_approve_training_consent,dfmcm.onboarding_type as Source,
                dmc.category as Category, dfmcm.new_case_id,
                dfmp.sm_approve_training_consent_datetime,dfmp.ops_approve_training_consent,dfmp.ops_approve_training_consent_datetime 
                FROM dsa_front_m_partner dfmp left JOIN dsa_front_t_resource_center_status dftrcs ON dfmp.phone_no=dftrcs.mobile 
                LEFT JOIN master_employee me on dfmp.created_by=me.employee_id 
                left JOIN dsa_front_m_case_master dfmcm ON dfmcm.phone_number=dfmp.phone_no 
                left join dsa_m_case  dmc on dfmcm.phone_number = dmc.mobile_no where dfmp.partner_type='DSA' 
                AND dfmcm.partner_type = 'DSA' 
                AND dfmp.created_at >= '$previousDay 00:00:00'
                AND dfmp.created_at+INTERVAL 1 YEAR<=DATE_FORMAT(DATE_ADD(CURDATE(), INTERVAL 1 DAY), '%Y-12-01')
                ".$whereClause);

                    // dd($results);
                if($this->request->has('perPage')){
                    $list = $this->custom_paginate($results);
                }else{
                    $list = $results;
                }

                return response()->json([
                    'error'=>false,
                    'data'=>$list
                ], 200); 
            } catch (\Exception $e) {
                //  dd($e);
                return response()->json([
                    'status'=> 400,
                    'message' => 'Not able to get count.',
                    'error'=>true
                ], 400); 
            }
        } 

