    public  function custom_paginate($data)
    {
        //Get current page form url e.g. &page=6
        $currentPage = LengthAwarePaginator::resolveCurrentPage();

        //Create a new Laravel collection from the array data
        $collection = new Collection($data);

        //Define how many items we want to be visible in each page
        $per_page = $this->request->perPage;

        //Slice the collection to get the items to display in current page
        $currentPageResults = $collection->slice(($this->request->page - 1) * $per_page, $per_page)->values();
        //Create our paginator and add it to the data array
        $data['results'] = new LengthAwarePaginator($currentPageResults, count($collection), $per_page);

        //Set base url for pagination links to follow e.g custom/url?page=6
        return $data['results'] ;
    }

    public function approveDSATrainingByOPS(){

        try {
            $user=$this->request->auth;
            $this->validate($this->request, [
                'mobile_no' => 'required',
            ]);


            $partnerDetails = DB::table('dsa_front_m_partner') 
            ->where('phone_no',$this->request->mobile_no)
            ->first();

            $partnerTrainingDetails = DB::table('dsa_front_t_resource_center_status') 
            ->where('mobile',$this->request->mobile_no)
            ->first();

            if($partnerTrainingDetails==null){
                return response()->json([
                    'status'=> 400,
                    'message' =>"Partner training is not complete yet.",
                    'error'=>true
                ], 400); 
            }else if($partnerDetails->sm_approve_training_consent==0){
                return response()->json([
                    'status'=> 400,
                    'message' =>"SM not approved the training yet.",
                    'error'=>true
                ], 400); 
            }else{
                DB::table('dsa_front_m_partner')
                ->where('phone_no',$this->request->mobile_no)
                ->update([
                    'ops_approve_training_consent' => 1,
                    'ops_approve_training_consent_datetime'=>Carbon::now(),
                    'ops_approve_training_by'=>$user->employee_id
                ]);
            }

            return response()->json([
                'status'=> 200,
                'message' =>"Training Approved.",
                'error'=>false
            ], 200); 

        } catch (\Exception $e) {
            return response()->json([
                'status'=> 400,
                'message' => $e->getMessage(),
                'error'=>true
            ], 400); 
        }
    }


    public function approveDSATrainingBySM(){
        try {

            $this->validate($this->request, [
                'partnerId' => 'required',
                'mobile_no' => 'required',
