    public function dsaUpdateLegalConsent(){
        $this->validate($this->request, [
            'caseId' => 'required'
        ]);
        $data = DB::table('dsa_front_m_case_master')
        ->where('case_id', $this->request->caseId)->get();
        try { 
            if(count($data) == 0){
                return response()->json([
                    'error'=>true,
                    'message' =>'Case ID does not exist.',
                    ], 200);
            } else if(count($data) == 1){
                if($this->request->caseId){
                    $updateData=DB::table('dsa_front_m_case_master')
                    ->where('case_id', $this->request->caseId)
                        ->update([
                            'dsa_legal_consent' => 1,
                            'legal_option' => 'No'
                        ]);
                }
                return response()->json([
                    'error'=>false,
                    'message' =>'Legal Consent updated.',
                    ], 200);
            }
        } catch (\Exception $e) {
            return response()->json([
                'error'=>true,
                'message' =>'Failed to update Legal Consent! Please try again.',
                ], 200);
        }
    }


