    public function validateBankAccount()
    {
        $this->validate($this->request, [
            'bank_account_no' => 'required',
            'bank_ifsc_code' => 'required',
            'case_id' => 'required',
            'account_holder_name' => 'required'
        ]);

        // dd($this->request->bank_account_no);

        try {

            $caseDetails = DB::table('dsa_front_m_case_master')
                ->where('case_id', $this->request->case_id)
                ->first();

            // dd($caseDetails);

            if (!$caseDetails) {
                return response()->json([
                    'error' => true,
                    'message' => "Case not found."
                ], 400);
            }
            // "bank_account_no": "37962568545",
            // "bank_ifsc_code": "SBIN0011321"

            $checkBankAccountResponse = null;

            // dd($caseDetails->validate_bank_acc_reference_id);
            // if($this->request->log){
            //     dd($caseDetails->validate_bank_acc_reference_id);
            // }
            if ($caseDetails->validate_bank_acc_reference_id != null || $caseDetails->validate_bank_acc_reference_id != "") {
                $clientSecond = new \GuzzleHttp\Client([
                    'headers' => [
                        'Content-Type' => 'application/json',
                        'account-id' => '446bb5af8829/274d1194-921e-4665-8930-557c7987b5bc',
                        'api-key' => 'e2914dac-8dee-4fd5-a53e-eab44506214c'
                    ],
                    'verify' => false
                ]);

                // $responseSecond = $clientSecond->get('https://eve.idfy.com/v3/tasks?request_id=' . $caseDetails->validate_bank_acc_reference_id); //Local

                $responseSecond = $clientSecond->get('https://ezgatewayuat.insideabc.com/v3-0/tasks?request_id='.$caseDetails->validate_bank_acc_reference_id);  //UAT

                $checkBankAccountResponse = json_decode($responseSecond->getBody()->getContents());
                
                // dd($checkBankAccountResponse);

            } else {
                $validateBankAccountTaskId = "";

                if ($caseDetails->validate_bank_acc_task_id) {
                    $validateBankAccountTaskId = $caseDetails->validate_bank_acc_task_id;
                } else {
                    $validateBankAccountTaskId = 'VALIDATE_BANK_ACCOUNT' . Carbon::now()->format('YmdHis');
                }

                DB::table('dsa_front_m_case_master')
                    ->where('case_id', $this->request->case_id)
                    ->update([
                        'validate_bank_acc_task_id' => $validateBankAccountTaskId
                    ]);

                $client = new \GuzzleHttp\Client([
                    'headers' => [
                        'Content-Type' => 'application/json',
                        'account-id' => '446bb5af8829/274d1194-921e-4665-8930-557c7987b5bc',
                        'api-key' => 'e2914dac-8dee-4fd5-a53e-eab44506214c'
                    ],
                    'verify' => false
                ]);

                $response = $client->post(
                    // 'https://eve.idfy.com/v3/tasks/async/verify_with_source/validate_bank_account',
                    //Local
                    'https://ezgatewayuat.insideabc.com/v3-0/tasks/async/verify_with_source/validate_bank_account',
                    //UAT
                    [
                        'body' => '{
                            "task_id": "' . $validateBankAccountTaskId . '",
                            "group_id": "' . env('PENNY_DROP_VALIDATE_BANK_ACC_GROUP_ID') . '",
                            "data": {
                                "bank_account_no": "' . $this->request->bank_account_no . '",
                                "bank_ifsc_code": "' . $this->request->bank_ifsc_code . '"
                            }
                        }'
                    ]
                );

                $response = json_decode($response->getBody()->getContents());

                //  dd($response->request_id);

                

                $clientSecond = new \GuzzleHttp\Client([
                    'headers' => [
                        'Content-Type' => 'application/json',
                        'account-id' => '446bb5af8829/274d1194-921e-4665-8930-557c7987b5bc',
                        'api-key' => 'e2914dac-8dee-4fd5-a53e-eab44506214c'
                    ],
                    'verify' => false
                ]);

                sleep(10);//wait for 10 second

                $responseSecond = $client->get('https://ezgatewayuat.insideabc.com/v3-0/tasks?request_id='.$response->request_id);  //UAT

                $checkBankAccountResponse = json_decode($responseSecond->getBody()->getContents());

                // if($checkBankAccountResponse[0]->status == "completed"){
                if($checkBankAccountResponse[0]->status == "completed" && $checkBankAccountResponse[0]->result->account_exists == 'YES'){
                    DB::table('dsa_front_m_case_master')
                    ->where('case_id', $this->request->case_id)
                    ->update([
                        'validate_bank_acc_reference_id' => $response->request_id
                    ]);
                }

            }

            // dd($checkBankAccountResponse);

            if ($checkBankAccountResponse != null) {

                if ($checkBankAccountResponse[0]->status == "completed") {
                    // if ($checkBankAccountResponse[0]->result->account_exists == "NO") {
                    //     return response()->json([
                    //         'error' => true,
                    //         'message' => $checkBankAccountResponse[0]->result->message
                    //     ], 400);
                    // }

                    if ($checkBankAccountResponse[0]->result->account_exists == "NO" || $checkBankAccountResponse[0]->result->account_exists == null) {
                        if($checkBankAccountResponse[0]->result->message == null){
                            $checkBankAccountResponseMessage = "Account does not exist. Kindly check with the customer once.";
                        } else {
                            $checkBankAccountResponseMessage = $checkBankAccountResponse[0]->result->message;
                        }
                        return response()->json([
                            'error' => true,
                            // 'message' => $checkBankAccountResponse[0]->result->message
                            'message' => $checkBankAccountResponseMessage
                        ], 400);
                    }

                    $nameCheckTaskId = 'NAME_CHECK_TASK_ID_' . Carbon::now()->format('YmdHis');

                    DB::table('dsa_front_m_case_master')
                        ->where('case_id', $this->request->case_id)
                        ->update([
                            'name_match_task_id' => $nameCheckTaskId,
                            'account_holder_name_penny_drop' => $checkBankAccountResponse[0]->result->name_at_bank
                        ]);

                    $clientThird = new \GuzzleHttp\Client([
                        'headers' => [
                            'Content-Type' => 'application/json',
                            'account-id' => '2a07c32e86e0/b64b113a-7316-4351-8075-5a11e89b2b06',
                            'api-key' => 'dcf22084-fc74-48ea-bdc2-b4bbbbe065fd'
                        ],
                        'verify' => false
                    ]);

                    // dd(json_decode('{
                    //     "task_id": "' . $nameCheckTaskId . '",
                    //     "group_id":"' . env('PENNY_DROP_NAME_MATCH_GROUP_ID') . '",
                    //     "data": {
                    //         "name1": "' . $this->request->account_holder_name . '",
                    //         "name2": "' . $checkBankAccountResponse[0]->result->name_at_bank . '"
                    //     }
                    // }'));

                    $responseThird = $clientThird->post(
                        // 'https://eve.idfy.com/v3/tasks/sync/compare/ind_names',
                        //Local
                        'https://ezgatewayuat.insideabc.com/v3-0/tasks/sync/compare/ind_names',     //UAT
                        [
                            'body' => '{
                                "task_id": "' . $nameCheckTaskId . '",
                                "group_id":"' . env('PENNY_DROP_NAME_MATCH_GROUP_ID') . '",
                                "data": {
                                    "name1": "' . $this->request->account_holder_name . '",
                                    "name2": "' . $checkBankAccountResponse[0]->result->name_at_bank . '"
                                }
                            }'
                        ]
                    );

                    $responseThird = json_decode($responseThird->getBody()->getContents());

                    // dd($responseThird);

                    if ($responseThird->status == "completed") {
                        DB::table('dsa_front_m_case_master')
                            ->where('case_id', $this->request->case_id)
                            ->update([
                                'validate_bank_acc_name_check_count' => $responseThird->result->match_output->name_match,
                                'is_bank_acc_validation_check' => 1,
                                'ifsc_code' => $this->request->bank_ifsc_code,
                                'account_number' => $this->request->bank_account_no,
                                'account_holder_name' => $this->request->account_holder_name,
                            ]);

                        return response()->json([
                            'error' => false,
                            'message' =>$responseThird->result->match_output->name_match<=3?"Your PAN name and Bank Name not match, Please upload canceled cheque.":"Name match found."
                        ], 200);
                    } else {
                        return response()->json([
                            'error' => true,
                            'message' => $responseThird
                        ], 400);
                    }
                } else {
                    DB::table('dsa_front_m_case_master')
                        ->where('case_id', $this->request->case_id)
                        ->update([
                            'validate_bank_acc_task_id' => null,
                            'name_match_task_id' => null,
                            'validate_bank_acc_reference_id' => null,
                            'validate_bank_acc_name_check_count' => null,
                            'is_bank_acc_validation_check' => null
                        ]);
                    $message = '';
                    if (!property_exists($checkBankAccountResponse[0],'message')) {
                        $message = 'Invalid bank account number provided';
                    } else {
                        $message = $checkBankAccountResponse[0]->message;
                    }
                    
                    return response()->json([
                        'error' => true,
                        'message' => $message
                    ], 400);
                }

            }
        } catch (\Exception $e) {
            dd($e->getMessage());
            return response()->json([
                'error' => true,
                'message' => $e->getMessage()
            ], 400);
        }
    }

    public function unverifyPennyDropDetails(){
        $this->validate($this->request, [
            'case_id'=>'required',
        ]);

        try{
            DB::table('dsa_front_m_case_master')
            ->where('case_id', $this->request->case_id) 
            ->update([
                'name_match_task_id'=>"",
                'account_holder_name_penny_drop'=>"",
                'account_holder_name'=>"",
                'ifsc_code'=>"",
                'validate_bank_acc_task_id'=>"",
                'validate_bank_acc_reference_id'=>"",
                'is_bank_acc_validation_check'=>0,
                'validate_bank_acc_name_check_count'=>0,
                'account_number'=>"",
                'bank_name'=>""

            ]);

            return response()->json([
                'error'=>false,
                'message' =>"Case details updated."
            ], 200);
        }catch (\Exception $e) {
            // dd($e->getMessage());
            return response()->json([
                'error'=>true,
                'message' => $e->getMessage()
            ], 400);
        }
    }


    // Select Flow Advisory
    public function getBranchList(){
        try {
            $branchArray = DB::table('dsa_front_m_branch_master')->where('deletion_flag',0)->get();
            $branchList = [];
            for($i=0;$i<count($branchArray);$i++){ 
                array_push($branchList,['title'=>$branchArray[$i]->branch_desc,'value'=>$branchArray[$i]->branch_desc]);
            }
            return response()->json([
                    'error'=>false,
                    'status'=> 200,
                    'message' => 'Branch details fetched succesfully',
                    'branch_data' => $branchList
                ], 200);
        } catch (\Exception $e) {
            return [
                'error'=>true,
                'message' => $e->getMessage(),
            ];
        }
    }

