    // Select Flow Advisory

    public function updateDSAPartner(){
        $user = $this->request->auth;

        try{
            $this->validate($this->request, [
                'partnerName' => 'required',
                'typeOfAgent' => 'required',
                'phoneNo' => 'required',
                'emailId' => 'required',
                'branchName' => 'required',
                'source' => 'required'
            ]);
            $checkMobileNo = DB::table('dsa_front_m_partner')
            ->where(function ($checkMobileNo) {
                $checkMobileNo->where('phone_no',  $this->request->phoneNo)
                                ->where('is_rejected','=',0)
                                ->orWhere('email_id',  $this->request->emailId);
            })->count();
            if($checkMobileNo == 1)
            {
                    DB::table('dsa_front_m_partner')
                    ->where('phone_no',  $this->request->phoneNo)
                    ->update([
                        'partner_name' => $this->request->partnerName,
                        'partner_type'=>$this->request->typeOfAgent,    
                        'phone_no' => $this->request->phoneNo,
                        'email_id'=>$this->request->emailId,  
                        'scheme_id' => 0,
                        'branch_name'=> $this->request->branchName,
                        'created_by' =>  $user->employee_id,  
                        // 'created_by' =>  null,
                        'onboarding_type' =>  $this->request->source,
                        'house_loan_selling_exp' =>  $this->request->houseLoanSellingExperience,  
                        'total_lending_insurance_sales_experience' =>  $this->request->insuranceSalesExperience,  
                        'other_than_DSA_RPA_business' =>  $this->request->whichOtherBusinessDo,  
                        'persona_of_channel' =>  $this->request->personaOfChannel,  
                        'number_of_employees_manpower' =>  $this->request->NumberOfEmployee,  
                        'number_of_FIs_empanelled_with' =>  $this->request->NumberOfFI,  
                        'top_3_FIs_Name' =>  $this->request->topFisName,  
                        'do_you_own_a_car_or_bike' =>  $this->request->ownCar,  
                        'do_you_have_builder_connects' =>  $this->request->builderConnects,  
                        'total_monthly_income_in_lacs' =>  $this->request->totalMonthlyIncome,  
