                        'number_of_files_processed_in_a_month' =>  $this->request->filesprocessedMonth,  
                        'number_of_files_processed_for_mortgage_in_a_month' =>  $this->request->filesprocessedMortgage,
                        'fisnameone'=>$this->request->fisnameone,
                        'fisnametwo'=>$this->request->fisnametwo,
                        'fisnamethre'=>$this->request->fisnamethre,
                        'builder1'=>$this->request->builder1,
                        'builder2'=>$this->request->builder2,
                        'builder3'=>$this->request->builder3,
                        'mentionBusiness'=>$this->request->mentionBusiness,
                    ]);
                    $partnerInfo = DB::table('dsa_front_m_partner')->where('phone_no',$this->request->phoneNo)->get();
                return response()->json([
                    'error'=>false,
                    'status'=> 200,
                    'message' => 'Partner details updated',
                    'partner_data' => $partnerInfo
                ], 200);
            }
            else {
                return response()->json([
                    'error'=>true,
                    'status'=> 500,
                    'message' => 'Partner is already updated.',
                ], 200);
            }
        }  catch (\Exception $e) {
            return [
                'error'=>true,
                'message' => $e->getMessage(),
            ];
        }
    }


