public function checkPanDedupe()
{
    $user = $this->request->auth;

    $faker = Faker::create();

    $this->validate($this->request, [
        'pan' => 'required',
    ]);

    $this->request->panNumber=$this->request->pan;
    $response=(object)[];
    try {
        
        $caseDetails = DB::table('dsa_front_m_case_master')
        ->where('pan_number', $this->request->panNumber)->first();
        $response;
        $type="";
        if($caseDetails){

            $type=$caseDetails->partner_type=='DSA'?'DAA':'RPA';
        }
        $isPanPresent=null;            
        $panPresentList = DB::table('dsa_front_m_pan_master')
        // ->where('status', 'LIKE','%Blacklisted%')
        ->where('pan_no', $this->request->panNumber)->orderBy('id','DESC')->get()->toArray();
        $isHardStop=false;
        $isSendConsent=false;
        $name='';
        $code='';
        $msg='';
       
        $blackList=array_filter($panPresentList, function($item)  {
            return $item->status == 'Blacklisted';
        });

        if(count($blackList)>0){
            $isPanPresent=$blackList[array_keys($blackList)[0]];
            $name=$isPanPresent->entity_name;
            $code=$isPanPresent->dsa_rp_code;
             
            if ($isPanPresent->status == "Blacklisted") {
                $isHardStop=true;
                $isSendConsent=false;
                $msg='The requested PAN number is blaklisted with DSA/RP code ' . $code . '.';
                     
                return response()->json([
                    'error' => true,
                    'data' => $response,
                    'status'=>$isPanPresent->status,
                    'name'=>$name,
                    'code'=>$code,
                    'isHardStop'=>$isHardStop,
                    'isSendConsent'=>$isSendConsent,
                    'message' => 'The requested PAN number is blaklisted with DSA/RP code ' . $isPanPresent->dsa_rp_code . '.'
                ], 400);
            }

        }
        if(count($panPresentList)>0){

            $isPanPresent=$panPresentList[0];
        }

        if ($isPanPresent) {
            $name=$isPanPresent->entity_name;
            $code=$isPanPresent->dsa_rp_code;
            // $rspn = DB::table('dsa_front_m_case_master')
            //     ->where('case_id', $this->request->caseId)
            //     ->update([
            //         'entered_pan_status' => $isPanPresent->status
            //     ]);
            if ($isPanPresent->status == "Blacklisted") {
                $isHardStop=true;
                $isSendConsent=false;
                // return response()->json([
                //     'error' => true,
                //     'message' => 'The requested PAN number is blaklisted with DSA/RP code ' . $isPanPresent->dsa_rp_code . '.'
                // ], 400);
                $msg='The requested PAN number is blaklisted with DSA/RP code ' . $code . '.';
            } else if ($isPanPresent->status == "Active") {
              if($type){

                  if(str_contains($isPanPresent->dsa_rp_code,$type)){
                      $isHardStop=true;
                      $msg='The requested PAN number is '.$isPanPresent->status.' with '.$name.' code ' . $code . '.';
                      // PAN is already exist with the Name of RP name and RP code
                  } else{
                      $isHardStop=false;
                      $msg='Do you want to apply for '.$caseDetails->partner_type.' PAN is already present as DSA for '.$name.' and '.$code.'';
                      $isSendConsent=true;
                  }
              }else{
                // if(str_contains($code,'DAA')){
                    $msg='The requested PAN number is '.$isPanPresent->status.' with '.$name.' code ' . $code . '.';
                // }
                //$type=$caseDetails->partner_type=='DSA'?'DSA':'RP';
              }
            }else if ($isPanPresent->status == "Deactive"||strtolower($isPanPresent->status) == "inactive") {
                $isHardStop=false;
                $isSendConsent=false;
                $msg='Pan is verifyed.The requested PAN number is '.$isPanPresent->status.' with '.$name.' code ' . $code . '.';

            }

             


            return response()->json([
                'error' => false,
                'data' => $response,
                'status'=>$isPanPresent->status,
                'name'=>$name,
                'code'=>$code,
                'isHardStop'=>$isHardStop,
                'isSendConsent'=>$isSendConsent,
                // 'message' => 'The requested PAN number is already '.$isPanPresent->status.' with DSA/RP code ' . $isPanPresent->dsa_rp_code . '.'
                'message' => $msg
            ], 200);
        }else{
            return response()->json([
                'error' => false,
                'data' => $response,
                 
                'isHardStop'=>$isHardStop,
                'isSendConsent'=>$isSendConsent,
                // 'message' => 'The requested PAN number is already '.$isPanPresent->status.' with DSA/RP code ' . $isPanPresent->dsa_rp_code . '.'
                'message' => "The Pan does not exists."
            ], 200);
        }

        
    } catch (\Exception $e) {
        dd($e);
        $errorCode = $e->errorInfo[1];
        if ($errorCode == 1062 || $errorCode == 2627) {
            return response()->json([
                'error' => true,
                'message' => 'Internal error.'.$e
            ], 400);
        }
        return response()->json([
            'error' => true,
            'message' => 'Internal error.'
        ], 400);
    }
}

public function addReferralPartner()
{
    $user = $this->request->auth;

        $this->validate($this->request, [
            'partnerName' => 'required',
            'typeOfAgent' => 'required',
            'phoneNo' => 'required',
            'emailId' => 'required',
            // 'schemeId' => 'required',
            'branchName' => 'required' 
        ]);
        $phoneno=$this->request->phoneNo;
        $emailId=$this->request->emailId;
        $checkMobileNo = DB::table('dsa_front_m_partner')
        ->where(function ($checkMobileNo) use($phoneno,$emailId){
            $checkMobileNo->where(function($q) use($phoneno,$emailId){
                $q->where('phone_no',  $phoneno)
                ->orWhere('email_id',  $emailId);
            })->where('is_rejected','0');
        })->count(); 

        // dd($checkMobileNo);
        if($checkMobileNo == 0)
        {
                DB::table('dsa_front_m_partner')->insert([
                    'partner_name' => $this->request->partnerName, 
                    'partner_type'=>$this->request->typeOfAgent,     
                    'phone_no' => $this->request->phoneNo,
                    'email_id'=>$this->request->emailId,   
                    'scheme_id' => $this->request->schemeId,
                    'branch_name'=> $this->request->branchName,
                    'created_by' =>  $user->employee_id,  
                ]);
                
                $sm_employee_id = $user->employee_id;
                $partner_phone = $this->request->phoneNo;
                $RmDetails =   DB::table('master_employee')
                                ->where('employee_id', $sm_employee_id)
                                ->select('employee_code')
                                ->first();

                $partnerSource = DB::table('dsa_front_m_partner')
                                ->where('phone_no',$partner_phone)
                                ->select('onboarding_type')
                                ->first(); 
                                
            return response()->json([
                'error'=>false,
                'status'=> 200,
                'message' => 'Partner details added',
                "rm_ad_id" => $RmDetails->employee_code,
                "source" => $partnerSource->onboarding_type
            ], 200); 
        }
        else {
            $RmDetails =   DB::table('dsa_front_m_partner as dfmp')
                            ->leftJoin('master_employee as me','dfmp.created_by','=','me.employee_id')
                            ->where('dfmp.phone_no',$this->request->phoneNo)
                            ->select('dfmp.*','me.employee_code')->first();

            return response()->json([
                'error'=>true,
                'status'=> 500,
                'message' => 'Partner is already added.',
                'rm_ad_id' => $RmDetails->employee_code,
                'source' => $RmDetails->onboarding_type
            ], 200); 
        }


}

