            'other_dms_id' =>$caseData[0]->other_adhar_dms_id,  
            'cibil_dms_id' =>$caseData[0]->cibil_dms_id,  
            // 'created_by' => DB::table('dsa_front_m_partner')->where('phone_no',$caseData[0]->phone_number)->value('created_by'),
            'created_by' => $createdBy,
            'source' => $caseData[0]->onboarding_type,
            'branch' => $caseData[0]->branch,
            'name_as_per_aadhar' => $caseData[0]->name_as_per_aadhar,
