        $documentData = $requestPayload->documentData;
        // $documentData = DB::table('dsa_front_t_case_attachment')
        // ->where('case_id', $appId)->get(); 
        // dd($documentData);
        if(count($documentData)>0)
        {
            foreach ($documentData as $dvalue) {
 
                DB::table('dsa_t_case_attachments')->insert([
                    'dsa_case_id' => $applicationNo,
