                'relation' => $caseData[0]->applicant_relation,
                'location' => $caseData[0]->applicant_location,
                'dates' => $caseData[0]->applicant_date,
                'place' => $caseData[0]->applicant_place
            ]);
        }



        if(count($referenceData)>0)
        {
            foreach ($referenceData as $rvalue) {
 
                DB::table('dsa_t_case_reference')->insert([
                    'dsa_case_id' => $applicationNo,
                    'reference_name' => $rvalue->reference_name,
                    'mobile_no' => $rvalue->reference_phone_no,
                    'company_email' => $rvalue->reference_email,
                    'reference_works_with' => $rvalue->reference_works_with,
                    'reference_office_email' => $rvalue->reference_office_email,
                ]); 
            } 
        }

        if(count($directorData)>0)
        {
            foreach ($directorData as $pvalue) {
                DB::table('dsa_t_case_proprietors')->insert([
                    'dsa_case_id' => $applicationNo,
                    'proprietor_applicant_type' => $caseData[0]->constitution_type,
                    'proprietor_salutation' => $pvalue->director_salutation,
                    'proprietor_fullname' => $pvalue->director_full_name, 
                    'proprietor_pan_no' => $pvalue->director_pan,
                    'proprietor_adhaar_no' => $pvalue->director_aadhar, 
                    'dms_id' => $pvalue->director_adhar_dms_id,
                    'director_cibil_dms_id' => $pvalue->director_cibil_dms_id,
                    'director_flag' =>   $pvalue->authorised_flag,
                    'director_email'  => $pvalue->director_email ? $pvalue->director_email : "NA",
                    'constitution_type'  => $caseData[0]->constitution_type,
                    'director_cibil_score'  => $pvalue->cibil_score,
                    'position' => "NA", 
                    'since' => "NA",
                    'proprietor_mobile_no' =>  $pvalue->director_mobile ? $pvalue->director_mobile : "NA", 
                    'is_email_verified' =>  $pvalue->isEmailVerified , 
                    'is_mobile_verified' =>  $pvalue->isMobileVerified, 
                    'is_pan_verified' =>  $pvalue->director_pan_verify_flag, 
                    'is_adhar_verified' =>  $pvalue->director_adhaar_verify_flag, 
                    'adhar_no' =>  $pvalue->director_aadhar, 
                    'director_dob' =>  $pvalue->director_dob, 
                ]);
            }
        }

        if(count($addressData)>0)
        {
            foreach ($addressData as $avalue) {
                if($avalue->address_type == 'Office') 
                {
                    DB::table('dsa_m_case')
                        ->where('dsa_case_id', $applicationNo)
                        ->update([
                            'case_pincode' => '443321', 
                        ]);
                }
                DB::table('dsa_t_case_address')->insert([ 
                    'dsa_case_id' => $applicationNo, 
                    'address_type' => $avalue->address_type,
                    'address_line1' => $avalue->addressline1,
                    'address_line2' => $avalue->addressline2,
                    'landmark' => $avalue->landmark,
                    'pincode' => $avalue->pincode,						
                    'area' => $avalue->area,
                    'city' => $avalue->city,
                    'district' => $avalue->district,
                    'state' => $avalue->state,
                    'country' => $avalue->country,
                    'residence_type' => $avalue->resident_type,
                   
                ]);
            }
        } 

        $age = Carbon::parse($caseData[0]->date_of_birth)->age; 

        if($age < 20 && ($caseData[0]->constitution_type == 'Individual' || $caseData[0]->constitution_type =='Proprietor'))  
        {

            DB::table('dsa_m_case')
                    ->where('dsa_case_id', $applicationNo) 
                    ->update([
                        'case_status'=> 'Rejected',
                        'rejection_reason'=>'Partner age is less than 20 years.',
                        'rejection_date_time'=>Carbon::now()
                    ]); 


        }

        if($caseData[0]->constitution_type == 'Individual' || $caseData[0]->constitution_type =='Proprietor'){
            if($caseData[0]->cibil_score < 600 && $caseData[0]->cibil_score > 1 && $caseData[0]->consent_check==1)
            {
               
                DB::table('dsa_m_case')
                ->where('dsa_case_id', $applicationNo) 
                ->update([
                    'case_status'=> 'Rejected',
                    'rejection_reason'=>'Partner CIBIL score is less than 600.',
                    'rejection_date_time'=>Carbon::now()
                ]);
            }
        }
        

        if($caseData[0]->constitution_type != 'Proprietor'  && $caseData[0]->constitution_type != 'Individual'){
            $isCaseReject=false;
            if(count($directorData)>0){
                foreach ($directorData as $director) {
                    if($director->authorised_flag==1 && $director->cibil_consent_check==1 && ($director->cibil_score<600 && $director->cibil_score>1)){
                        $isCaseReject=true;
                    }
                }
            }

            if($isCaseReject==true){
                DB::table('dsa_m_case')
                    ->where('dsa_case_id', $applicationNo) 
                    ->update([
                        'case_status'=> 'Rejected',
                        'rejection_reason'=>'One or more directors cibil score is less than 600. OR One or more directors age is less than 20.',
                        'rejection_date_time'=>Carbon::now()
                    ]); 

            }
        }

        
       
        return response()->json([
                    'error'=>false,
                    'message' => 'data added',
                    'caseId' => $applicationNo 
                ], 200);  
    }
    catch (\Exception $e) {
        DB::rollback();
        dd($e);
        return response()->json([
            'Status' => 500,
            'message' => $e->getMessage()
        ], 400);
    }
}
    
    public function getAnnualCertificationDetails(){
        try {

            $this->validate($this->request, [
                'mobile_no' => 'required',
            ]);

            $yearCondition = $this->request->year ? $this->request->year : '';
            $checkAnnualCertification = DB::table('dsa_front_m_partner')
            ->where('phone_no', $this->request->mobile_no)
            ->when($yearCondition, function ($query, $yearCondition) {
                return $query->whereRaw('YEAR(created_at) = ?', [$yearCondition]);
            })
            ->first();
        
        // print_r($checkAnnualCertification->phone_no);
        // print_r($checkAnnualCertification);

            if(!$checkAnnualCertification){

                return response()->json([
                    'status' => 200,
                    'message' => "Certification Approved.",
                    'error' => false,
                    'partnerDetails' => '',
                    'partnerTrainingDetails' => ''
                ], 200);
            }
            $partnerDetails = DB::table('dsa_front_m_annual_certification')
                ->where('phone_no', $checkAnnualCertification->phone_no)
                ->first();


            $partnerCertificationDetails = DB::table('dsa_front_t_annual_certification_status')
                ->where('mobile', $checkAnnualCertification->phone_no)
                ->first();

            return response()->json([
                'status' => 200,
                'message' => "Certification Approved.",
                'error' => false,
                'partnerDetails' => $partnerDetails,
                'partnerTrainingDetails' => $partnerCertificationDetails
            ], 200);

        } catch (\Exception $e) {
            return response()->json([
                'status' => 400,
                'message' => $e->getMessage(),
                'error' => true
            ], 400);
        }
    }

    public function approveDSACertificationByOPS()
    {

        try {
            $user = $this->request->auth;
            $this->validate($this->request, [
                'mobile_no' => 'required',
            ]);


            $partnerDetails = DB::table('dsa_front_m_annual_certification')
                ->where('phone_no', $this->request->mobile_no)
                ->first();

            $partnerTrainingDetails = DB::table('dsa_front_t_annual_certification_status')
                ->where('mobile', $this->request->mobile_no)
                ->first();

            if ($partnerTrainingDetails == null) {
                return response()->json([
                    'status' => 400,
                    'message' => "Partner training is not complete yet.",
                    'error' => true
                ], 400);
            } else if ($partnerDetails->sm_approve_certification_consent == 0) {
                return response()->json([
                    'status' => 400,
                    'message' => "SM not approved the training yet.",
                    'error' => true
                ], 400);
            } else {
                DB::table('dsa_front_m_annual_certification')
                    ->where('phone_no', $this->request->mobile_no)
                    ->update([
                        'ops_approve_certification_consent' => 1,
                        'ops_approve_certification_consent_datetime' => Carbon::now(),
                        'ops_approve_certification_by' => $user->employee_id
                    ]);
            }

            return response()->json([
                'status' => 200,
                'message' => "Training Approved.",
                'error' => false
            ], 200);

        } catch (\Exception $e) {
            return response()->json([
                'status' => 400,
                'message' => $e->getMessage(),
                'error' => true
            ], 400);
        }
    }

