            DB::table('dsa_front_t_annual_certification_status')->updateOrInsert(
                ['mobile' => $this->request->mobile],
                ['mobile' => $this->request->mobile, 'status' => 'Completed','mark_as_complete' => 'Completed']
            );
            

            return response()->json([
                'error' => false,
                'data' => 'Thank you.'
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'error' => true,
                'message' => 'Internal error.',
                'messageq' => $e->getMessage()
            ], 200);
        }
    }
    
    public function updateTrainingCenterDocumentStatus()
    {
        $this->validate($this->request, [
            'mobile' => 'required',
            'status' => 'required',
            'document_id' => 'required',
        ]);
        try {

            // echo $this->request->status;
            DB::table('dsa_front_t_annual_certification_status')->updateOrInsert(
                ['mobile' => $this->request->mobile, 'document_id' => $this->request->document_id],
                ['mobile' => $this->request->mobile, 'document_id' => $this->request->document_id, 'status' => $this->request->status]
            );

            return response()->json([
                'error' => false,
                'data' => 'Status changed'
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'error' => true,
                'message' => 'Internal error.',
                'messageq' => $e->getMessage()
            ], 200);
        }
    }

    public function getAnnualDashboardList()
    {
        $user = $this->request->auth;
        // dd($user);
        $condition = "";
        $condition1 = "";
        $condition2 = "";
        $condition3 = "";
        $newCondition = "";
        $newCondition1 = "";
        $newCondition2 = "";
        $newCondition3 = "";
 
       
        if ($this->request->searchTerm) {
            $condition = "and (dp.partner_name like '%" . $this->request->searchTerm . "%'  )";
            $condition1 = "and (applicant_name like '%" . $this->request->searchTerm . "%')";
            $condition2 = "and (dm.applicant_name like '%" . $this->request->searchTerm . "%' )";
            $newCondition3 = "and (dp.partner_name like '%" . $this->request->searchTerm . "%' )";
        }
        // $this->request->year = '2023'
        if ($this->request->year) {
            // $condition = "and (dp.year = '".$this->request->year."'  )";
            $condition = "and ( YEAR(dp.created_at)  = '".$this->request->year."'  )";
                   
        }
 
        if ($this->request->partnerType) {
            $Pdata = "'" . implode("', '", $this->request->partnerType) . "'";
            $condition = $condition . " and dp.partner_type in ($Pdata)";
            $condition1 = $condition1 . " and partner_type in ($Pdata)";
            $condition2 = $condition2 . " and partner_type in ($Pdata)";
            $condition3 = $condition3 . " and dp.partner_type in ($Pdata)";
            $newCondition3 = $newCondition3 . " and dp.partner_type in ($Pdata)";
        }
 
        

        if ($this->request->branchList) {
            $Branchdata = "'" . implode("', '", $this->request->branchList) . "'";
            $condition = $condition . " and dp.branch_name in ($Branchdata)";
            $newCondition3 = $newCondition3 . " and dp.branch_name in ($Branchdata)";  
        }

        $employeeId = $user->employee_id ? $user->employee_id : "";
        $createdByQuery = "";
        if($employeeId){
            $createdByQuery = "AND dp.created_by = $employeeId";
        }       
        
        $getAllList = DB::select("select dp.partner_id as id,dp.partner_name as applicant_name,dp.phone_no as mobile_no,dm.stage_count,dp.email_id,dp.branch_name,dfmac.sm_approve_certification_consent,case_id as caseId,'Application' as status,dp.partner_type,dftrcs.status as training_module_status, dftrcs.created_at as training_m_date,dp.created_by from dsa_front_m_partner as dp inner join dsa_front_m_case_master as dm on dp.phone_no=dm.phone_number left join dsa_front_t_training_center_status as dftrcs on dp.phone_no=dftrcs.mobile  left join dsa_front_m_annual_certification as dfmac on dp.phone_no=dfmac.phone_no where dm.stage_count = 9 and (dfmac.sm_approve_certification_consent is null || dfmac.sm_approve_certification_consent = 0 || dfmac.sm_approve_certification_consent = 1) $createdByQuery $condition $newCondition3");

        $pendingList = DB::select("select dp.partner_id as id,dp.partner_name as applicant_name,dp.phone_no as mobile_no,dm.stage_count,dp.email_id,dp.branch_name,dfmac.sm_approve_certification_consent,case_id as caseId,'Application' as status,dp.partner_type,dftrcs.status as training_module_status, dftrcs.created_at as training_m_date,dp.created_by from dsa_front_m_partner as dp inner join dsa_front_m_case_master as dm on dp.phone_no=dm.phone_number left join dsa_front_t_training_center_status as dftrcs on dp.phone_no=dftrcs.mobile left join dsa_front_m_annual_certification as dfmac on dp.phone_no=dfmac.phone_no where dm.stage_count = 9 and (dfmac.sm_approve_certification_consent is null || dfmac.sm_approve_certification_consent = 0)  $createdByQuery $condition $newCondition3");
       
        $approveList = DB::select("select dp.partner_id as id,dp.partner_name as applicant_name,dp.phone_no as mobile_no,dm.stage_count,dp.email_id,dp.branch_name,dfmac.sm_approve_certification_consent,case_id as caseId,'Application' as status,dp.partner_type,dftrcs.status as training_module_status, dftrcs.created_at as training_m_date,dp.created_by from dsa_front_m_partner as dp inner join dsa_front_m_case_master as dm on dp.phone_no=dm.phone_number left join dsa_front_t_training_center_status as dftrcs on dp.phone_no=dftrcs.mobile left join dsa_front_m_annual_certification as dfmac on dp.phone_no=dfmac.phone_no where dm.stage_count = 9 and (dfmac.sm_approve_certification_consent is null ||  dfmac.sm_approve_certification_consent = 1) $createdByQuery  $condition  $newCondition3");        
 
        $list;
 
        $data = array();
 
        if ($this->request->type == 'All') {
            $list = $getAllList;          
        }else if ($this->request->type == 'Pending') {
            $list = $pendingList;
        }else if ($this->request->type == 'Approval') {
            $list = $approveList;
        }
 
        return response()->json([
             'data' => $list,
            'error' => false
        ], 200);
 
 
    }

