    public function getAnnualTrainingCount()
    {
        $user = $this->request->auth;
        // echo "##########".$user->employee_id;
        $currentYear = Carbon::now()->year;
        $annualTrainingData = DB::select("SELECT
        COUNT(*) as all_count,
        COUNT(CASE WHEN dfmac.sm_approve_certification_consent = 0 THEN 1 END) as Pending,
        COUNT(CASE WHEN dfmac.sm_approve_certification_consent = 1 THEN 1 END) as Approved        
        FROM dsa_front_m_partner as dp 
        INNER JOIN dsa_front_m_case_master as dm ON dp.phone_no = dm.phone_number
        LEFT JOIN dsa_front_t_training_center_status as dftrcs ON dp.phone_no = dftrcs.mobile
        LEFT JOIN dsa_front_m_annual_certification as dfmac ON dp.phone_no = dfmac.phone_no
        WHERE  dm.stage_count = 9  AND dfmac.sm_approve_certification_consent IN (0, 1)
        AND dp.created_by = $user->employee_id  AND YEAR(dp.created_at) = $currentYear");

        return response()->json([
            'Status' => 200,
            'annualTrainingData' => $annualTrainingData,
            'message' => 'annual training details found',

        ], 200);
    }


