            $searchTeamQuery = "AND (dp.phone_no LIKE '%$searchTerm%' OR dp.partner_name LIKE '%$searchTerm%'    
               OR dm.new_case_id LIKE '%$searchTerm%' )";
        }
        if ($this->request->fromDate) {
            $fromDate = Carbon::parse($this->request->fromDate)->format('Y-m-d');         
            $rawQuery = "AND dp.created_at >= '$fromDate'";
        }
         
        if ($this->request->fromDate && $this->request->toDate) {
            $fromDate = Carbon::parse($this->request->fromDate)->format('Y-m-d');
            $toDate = Carbon::parse($this->request->toDate)->addDay()->format('Y-m-d');         
            $rawQuery = "and dp.created_at BETWEEN '$fromDate' AND '$toDate'";          
        }

 
        $query = '';
 
         if ($this->request->type == 'All') {
            $query = '';
        }else if ($this->request->type == 'Completed') {
            $query = ' AND dfmac.ops_approve_certification_consent = 1 and dfmac.sm_approve_certification_consent = 1';
        }else if ($this->request->type == 'In Progress') {
            // $query = 'AND (dfmac.ops_approve_certification_consent = 0 || dfmac.ops_approve_certification_consent IS NULL)
            //   and (dfmac.sm_approve_certification_consent = 0 || dfmac.sm_approve_certification_consent IS NULL )';
            // $trStatus = 'completed';
            // $query = 'AND (dfmac.ops_approve_certification_consent = 0 || dfmac.ops_approve_certification_consent IS NULL) AND   dfmac.sm_approve_certification_consent = 1';  //AND dftacs.status = '$trStatus'`;
            $query ="AND (dfmac.ops_approve_certification_consent = 0 OR dfmac.ops_approve_certification_consent IS NULL) 
            AND dfmac.sm_approve_certification_consent = 1 
            AND dftacs.status = 'Completed'";
        }   
        else if ($this->request->type == 'Actionables') {
            $query = 'AND (dfmac.ops_approve_certification_consent = 0 || dfmac.ops_approve_certification_consent is NULL) 
            AND (dfmac.sm_approve_certification_consent = 0|| dfmac.ops_approve_certification_consent is NULL)
            AND dftacs.status is NULL';
