        }
 
        // $data = DB::select("select dp.partner_id as id,dm.new_case_id,dp.partner_name as applicant_name,dp.phone_no as mobile_no,dm.stage_count,dp.email_id,me.employee_name,dp.branch_name,dfmac.sm_approve_certification_consent as sm_status,dfmac.ops_approve_certification_consent as ops_status,dfmac.ops_approve_certification_consent_datetime as trainingenddate,
        // case_id as caseId,'Application' as status,dp.partner_type,dftrcs.status as training_module_status,
        //  dftrcs.created_at as training_m_date,dp.created_by,me.email_id as smEmailId,dp.created_at,dp.created_at as trainingstartdate,
        //  TIMESTAMPDIFF(YEAR, dp.created_at, NOW()) AS years_since_onboard,
        //  DATE_ADD(dp.created_at, INTERVAL 1 YEAR) AS one_year_later
        //   from dsa_front_m_partner as dp
        //         inner join dsa_front_m_case_master as dm on dp.phone_no=dm.phone_number
        //         left join dsa_front_t_annual_certification_status as dftacs on dp.phone_no=dftacs.mobile
        //         left join dsa_front_t_resource_center_status as dftrcs on dp.phone_no=dftrcs.mobile
        //         left join dsa_front_m_annual_certification as dfmac on dp.phone_no=dfmac.phone_no
        //         LEFT join master_employee me on me.employee_id = dp.created_by
        //         where dm.stage_count = 9 and TIMESTAMPDIFF(YEAR, dp.created_at, NOW()) > 0 $rawQuery $query");
        // AND dp.created_by = $user->employee_id 

        

        $getPrev = DB::select("SELECT DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 1 YEAR), '%Y-12-01') AS previousDay");
        $getNext = DB::select("SELECT  DATE_ADD(CURDATE(), INTERVAL 1 DAY) AS nextDay");
        // print_r($getPrev[0]->previousDay);
        // print_r($getNext[0]->nextDay);
        $previousDay = $getPrev[0]->previousDay;
        $nextDay = $getNext[0]->nextDay;


        //echo '$user->employee_id::::::::::::::::'.$user->employee_id;
        $data = DB::select("WITH RankedRecords AS (
            SELECT
              dm.new_case_id,
              dp.partner_id AS id,
              dp.partner_name AS applicant_name,
              dp.phone_no AS mobile_no,
              dm.stage_count,
              dp.email_id,
              me.employee_name,
              dp.branch_name,
              dfmac.sm_approve_certification_consent AS sm_status,
              dftacs.document_id,
              dfmac.sm_approve_certification_consent_datetime AS sm_training_approve_training_date,
              dfmac.ops_approve_certification_consent AS ops_status,
            --   dfmac.ops_approve_certification_consent_datetime AS trainingenddate,
              dfmac.ops_approve_certification_consent_datetime AS ops_training_approve_training_date,
              dftacs.status AS dsa_training_status,
              dftacs.created_at AS dsa_training_approve_training_date,
              dm.case_id AS caseId,
              'Application' AS status,
              dp.partner_type,
              dftacs.status AS training_module_status,
              dftacs.created_at AS training_m_date,
              dp.created_by,
              me.email_id AS smEmailId,
              dp.created_at,
              dp.created_at AS trainingstartdate,
              TIMESTAMPDIFF(YEAR, dp.created_at, NOW()) AS years_since_onboard,
              DATE_ADD(dp.created_at, INTERVAL 1 YEAR) AS one_year_later,
              ROW_NUMBER() OVER (PARTITION BY dp.phone_no ORDER BY dftacs.document_id DESC) AS RowNum
            FROM
              dsa_front_m_partner AS dp
              INNER JOIN dsa_front_m_case_master AS dm ON dp.phone_no = dm.phone_number
              LEFT JOIN dsa_front_t_annual_certification_status AS dftacs ON dp.phone_no = dftacs.mobile
              LEFT JOIN dsa_front_t_training_center_status AS dftrcs ON dp.phone_no = dftrcs.mobile
              LEFT JOIN dsa_front_m_annual_certification AS dfmac ON dp.phone_no = dfmac.phone_no
              LEFT JOIN master_employee me ON me.employee_id = dp.created_by
            WHERE
              dm.stage_count = 9
              AND dp.partner_type = 'DSA'
              AND dm.partner_type = 'DSA'
              AND dp.created_at >= '$previousDay 00:00:00'
        AND dp.created_at+INTERVAL 1 YEAR<=DATE_FORMAT(DATE_ADD(CURDATE(), INTERVAL 1 DAY), '%Y-12-01')
         $rawQuery $query $searchTeamQuery
          )
          SELECT *
          FROM RankedRecords
          WHERE RowNum = 1");

        $datas = $this->custom_paginate($data);
        return response()->json([
            'Status'=> 200,
            'data'=> $datas,
            'message' => 'Success',
        ], 200);
    }

