    public function uploadAnnualTrainingDocument()
    {
        $this->validate($this->request, [
            'caseId' => 'required|integer',
            'file' => 'required|mimes:pdf', // Only accept PDF files
            'year' => 'required|integer' // Ensure the year is provided
        ]);

        // Define the destination path for storing PDF documents
        $destinationPath = 'uploads/annual_training_documents/';

        // Generate a unique file name
        $fileInitials = date('YmdHis') . '_' . $this->randomCode(6);

        // Retrieve the uploaded file
        $file = $this->request->file('file');

        // Move the file to the destination path
        $file->move($destinationPath, $fileInitials . '.' . $file->getClientOriginalExtension());

        // Insert the file details into the database
        DB::table('annual_training_documents')->insert([
            'case_id' => $this->request->caseId,
            'file_name' => $fileInitials . '.' . $file->getClientOriginalExtension(),
            'file_path' => $destinationPath,
            'content_type' => $file->getMimeType(),
            'year' => $this->request->year // Insert the selected year into the database
        ]);

        // Return success response
        return response()->json([
            'message' => 'Annual training document uploaded successfully.'
        ], 200);
    }

    public function triggerTrainingNotification()
    {
        // Get DSAs whose training is incomplete
        $dsas = Dsa::whereNull('training_completion_date')
                ->orWhere('last_training_date', '<', now()->subMonths(6)->toDateString()) // Assuming training should be completed within 6 months
                ->get();

        // Prepare data for SM email notification
        $tableData = [];

        foreach ($dsas as $dsa) {
            // Send email notification to DSA
            if (env('DSA_FRONT_EMAIL_FLAG')) {
                $description = "Your training is not completed yet. Kindly complete the training.";

                $data = [
                    'Application_No' => "", 
                    'sender1'=>'Dear user,',
                    'details' => $description,
                    // 'link' => "http://localhost:4200/",
                    'detail1'=>'Thanks and Regards,',
                    'detail2'=>'Aditya Birla Housing Finance.'
                ];

                $senderName = $dsa->emailId;
                Queue::push(new DSAInitiateEmailJob(
                    $senderName,
                    explode(',', env('dsa_cc_Email')), 
                    "Training not completed yet", 
                    $data,
                ));

                // Update/insert fields in the new table for DSA email
                DB::table('new_table')->updateOrInsert(
                    ['email' => $senderName],
                    [
                        'dsa_code' => $dsa->code,
                        'dsa_name' => $dsa->name,
                        'phone_no' => $dsa->phone_no,
                        'send_email_to_dsa' => 1, 
                        'send_email_to_dsa_date' => now()->toDateString() // Update with the current date
                    ]
                );
            } 
            
            // Prepare data for SM email notification
            $tableData[] = '<tr>';
            $tableData[] = '<td>' . $dsa->name . '</td>';
            $tableData[] = '<td>' . $dsa->emailId . '</td>';
            $tableData[] = '<td>' . $dsa->phone_no . '</td>';
            $tableData[] = '<td>' . $dsa->onboarding_date . '</td>';
            $tableData[] = '</tr>';
        }

        // Send email to SM with the table
        if (env('SM_FRONT_EMAIL_FLAG')) {
            $description = "The following DSAs have incomplete training:";
            $data = [
                'description' => $description,
                'tableData' => implode('', $tableData), // Join the table data array into a single string
                'detail1' => 'Thanks and Regards,',
                'detail2' => 'Aditya Birla Housing Finance.'
            ];

            // Send email to SM
            $senderName = env('SM_EMAIL_ID'); // Assuming you have SM's email ID in environment variable
            Queue::push(new DSAInitiateEmailJob(
                $senderName,
                explode(',', env('sm_cc_Email')), 
                "Incomplete DSA Trainings", 
                $data,
            ));

            // Update/insert fields in the new table for SM email
            DB::table('new_table')->updateOrInsert(
                ['email' => $senderName],
                [
                    'send_email_to_sm' => 1, 
                    'send_email_to_sm_date' => now()->toDateString(), // Update with the current date
                ]
            );
        } 
    }


