    public function getIncentiveFolders() {
        try {
            $emp = $this->request->employee_code;
            
            $yearArray = DB::table('dsa_front_incentive_scorecard_month_year_master')
            ->select('year')
            ->distinct("year")
            ->get()->toArray();
           
            $yearList = array();
            foreach ($yearArray as $value) {
                array_push($yearList,$value->year);
            }
            
            $monthPathArray = DB::table('dsa_front_incentive_scorecard_month_year_master')
            ->select('month_path')
            ->distinct("month_path")
            ->get()->toArray();
    
            $monthPathList = array();
            foreach ($monthPathArray as $key => $value) {
                array_push($monthPathList,$value->month_path);
            }
            $monthArray = DB::table('dsa_front_incentive_scorecard_month_year_master')
            ->get();
            
            
            $monthList = array();
            foreach ($yearList as $key =>$value) {
                $newArray=collect($monthArray)->where('year', $value)->all();
                $monthListArray = array();
                foreach ($newArray as $monthKey => $monthValue) {
                    array_push($monthListArray,$monthValue);
                }
                array_push($monthList,[$value => $monthListArray]);
            }
            
            $monthYearList = (object)[
                $yearList[0] => $monthList[0][$yearList[0]],
                $yearList[1] => $monthList[1][$yearList[1]],
                $yearList[2] => $monthList[2][$yearList[2]],
            ];
            
            $fileArray = array();
            foreach ($monthPathList as $path) {
                $filesInFolder = File::allFiles($path);
                $files1=File::allFiles($path);
                $files=array_filter($files1,function($item){
                    return strtolower($item->getExtension())=='pdf' 
                    && str_contains(strtolower(($item->getFilename())),strtolower($this->request->employee_code));
                });

                $fileData = (object)[
                    'path' => $path,
                    'files' => [
                        'MIME_TYPE' => $files[0]->getExtension(),
                        'path' => $path.'\\\\'.$files[0]->getFilename(),
                        'name' => $files[0]->getFilename()
                    ]
                ];
                array_push($fileArray,$fileData);
            }
            foreach ($fileArray as $key => $value) {
                $filePathParts = explode('\\', $value->path);
                
                $year = $filePathParts[10];
                $month = $filePathParts[12];
                $yearObj = $monthYearList->$year;
                if ($yearObj) {
                    $monthObj = $yearObj[array_search($month, array_column($yearObj, 'month'))];
                    if ($monthObj) {
                        $monthObj->files = $value->files;
                    }
                }
            }
            return response()->json([
                'yearList' => $yearList,
                'monthList' => $monthList,
                'monthYearList' => $monthYearList,
                'monthPathList' => $monthPathList,
                "filesData" => $fileArray,
                'error' => false 
            ], 200);
            
        } catch (\Exception $e) {
            //throw $th;
            dd($e);
        }
    }


    public function getIncentiveFolders1() {
        try {
            $employeeCode = $this->request->employee_code;
    
            // Fetch distinct years and month data
            $yearsAndMonths = $this->fetchYearsAndMonths();
    
            // Filter files concurrently for each month
            $fileArray = $this->fetchFilteredFiles($yearsAndMonths, $employeeCode);
    
            return response()->json([
                'yearsAndMonths' => $yearsAndMonths,
                'fileArray' => $fileArray,
                'error' => false
            ], 200);
    
        } catch (\Exception $e) {
            // Log the exception or handle it gracefully
            return response()->json(['error' => $e->getMessage()], 500);
        }
    }
    
    protected function fetchYearsAndMonths() {
        return DB::table('dsa_front_incentive_scorecard_month_year_master')
            ->select('year', 'month_path')
            ->distinct()
            ->get()
            ->groupBy('year')
            ->toArray();
    }
    
    protected function fetchFilteredFiles($yearsAndMonths, $employeeCode) {
        $fileArray = [];
    
        // Concurrently filter files for each year and month
        foreach ($yearsAndMonths as $year => $months) {
            foreach ($months as $month) {
                $path = $month->month_path;
                $files = File::files($path);
    
                $filteredFiles = array_filter($files, function ($file) use ($employeeCode) {
                    return $this->isValidFile($file, $employeeCode);
                });
    
                foreach ($filteredFiles as $filteredFile) {
                    $fileArray[] = [
                        'path' => $path,
                        'file' => $filteredFile
                    ];
                }
            }
        }
    
        return $fileArray;
    }
    
    protected function isValidFile($file, $employeeCode) {
        return $file->getExtension() === 'pdf' &&
               str_contains(strtolower($file->getFilename()), strtolower($employeeCode));
    }

