                                ]);
                                $dmsID=$this->callUpload($caseId,16,$did,$fullPath,$filePath,$contentType);
                                // dd($dmsID);
                                // Log::info("CIBIL Report DMS upload success Message ".$dmsID['documentID']);
                                if($dmsID['error'] == false)
                                {
                                    DB::table('dsa_front_m_case_master') 
