            else  if($this->request->stageCount == 7)
            {
                DB::table('dsa_front_m_case_master')->where('case_id', $this->request->appId)
                ->update([
                    'stage_count'=>$saveStageCount,
                ]);

                if(count($this->request->reference)>0)
                {
                    foreach ($this->request->reference as $rvalue) {
                    
                        if($rvalue['rid'])
                        {
                        DB::table('dsa_front_t_case_reference')->where('case_id', $this->request->appId)->where('rid',$rvalue['rid'])
                            ->update([
                                'reference_name' => $rvalue['referenceName'],
                                'reference_relation' => $rvalue['referenceRelation'],
                                'reference_phone_no' => $rvalue['referencePhoneno'],
                                'reference_email' => $rvalue['referenceEmail'],
                                'reference_since' => $rvalue['referenceSince'],
                                'reference_addressline1' => $rvalue['referenceAddressline1'], 
                                'reference_addressline2' => $rvalue['referenceAddressline2'],
                                'reference_landmark' => $rvalue['referenceLandmark'],
                                'reference_pincode' => $rvalue['referencePincode'],
                                'reference_area' => $rvalue['referenceArea'],
                                'reference_postoffice' => $rvalue['referencePostoffice'],
                                'reference_city' => $rvalue['referenceCity'],
                                'reference_district' => $rvalue['referenceDistrict'],
                                'reference_state' => $rvalue['referenceState'],
                                'reference_country' => $rvalue['referenceCountry'],
                                'reference_works_with' => $rvalue['referenceWorkingWith'],
                                'reference_office_email' => $rvalue['referenceOfficeEmail'],
                            ]);
                        }
                        else {
                            DB::table('dsa_front_t_case_reference')->insert([
                                'case_id' => $this->request->appId,
                                'reference_name' => $rvalue['referenceName'],
                                'reference_relation' => $rvalue['referenceRelation'],
                                'reference_phone_no' => $rvalue['referencePhoneno'],
                                'reference_email' => $rvalue['referenceEmail'],
                                'reference_since' => $rvalue['referenceSince'],
                                'reference_addressline1' => $rvalue['referenceAddressline1'],
                                'reference_addressline2' => $rvalue['referenceAddressline2'],
                                'reference_landmark' => $rvalue['referenceLandmark'],
                                'reference_pincode' => $rvalue['referencePincode'],
                                'reference_area' => $rvalue['referenceArea'],
                                'reference_postoffice' => $rvalue['referencePostoffice'],
                                'reference_city' => $rvalue['referenceCity'],
                                'reference_district' => $rvalue['referenceDistrict'],
                                'reference_state' => $rvalue['referenceState'],
                                'reference_country' => $rvalue['referenceCountry'],
                                'reference_works_with' => $rvalue['referenceWorkingWith'],
                                'reference_office_email' => $rvalue['referenceOfficeEmail'],
                            ]);
                        }

                    }
                }
            }
            else if ($this->request->stageCount == 8) {
                DB::table('dsa_front_m_case_master')->where('case_id', $this->request->appId)
                ->update([
                    'stage_count'=>$saveStageCount,
                ]);
                
                $financialInstitutionCount  = DB::table('dsa_front_t_case_financial_institution')->where('case_id', $this->request->appId)->count();
                if($financialInstitutionCount == 0) {
                    DB::table('dsa_front_t_case_financial_institution')
                        ->insert([
                            "case_id" => $this->request->appId,
                            "persona_of_channel" => $this->request->persona_of_channel,
                            "other_persona" => $this->request->other_persona,
                            "experience_in_selling_hl" => $this->request->experience_in_selling_hl,
                            "monthly_business_amount_in_crores" => $this->request->monthly_business_amount_in_crores,
                            "number_of_financial_institutions" => $this->request->number_of_financial_institutions,
                            "financial_institution_name_1" => $this->request->financial_institution_name_1,
                            "financial_institution_name_2" => $this->request->financial_institution_name_2,
                            "financial_institution_name_3" => $this->request->financial_institution_name_3
                        ]);
                }
            }
            else  if($this->request->stageCount == 9)
            {
                Log::info("Bureua Details".print_r($this->request->getContent(), true));
                
                DB::table('dsa_front_m_case_master')->where('case_id', $this->request->appId)
                ->update([
                    'consent_check'=>$this->request->consentCheck,
                    'stage_count'=>$saveStageCount,
                    'submitted_from_device'=>$this->request->device,
                    'legal_option' => 'No'
                ]);
                $advisoryCaseData = DB::table('dsa_front_m_case_master')->where('case_id', $this->request->appId)->get(); 

                if ($advisoryCaseData[0]->created_by == null) {
                    $isSelectAdvisory = true;
                } else {
                    $isSelectAdvisory = false;
                }
                if(count($this->request->directorConsent)>0)
                {
                    foreach ($this->request->directorConsent as $dirConcent) {
                        if($dirConcent['directorId'])
                        {
                        DB::table('dsa_front_t_case_director')->where('case_id', $this->request->appId)->where('tid',$dirConcent['directorId'])
                            ->update([
                                'cibil_consent_check' => $dirConcent['concent'],
                            ]);
                        }
                    }
                }
                
                $caseSubmittedCount = DB::table('dsa_m_case')->where('mobile_no',$advisoryCaseData[0]->phone_number)->count();
                if($caseSubmittedCount == 0) {
                    if ($isSelectAdvisory) {
                        $smDetails = null;
                    }else {
                        $smEmployeeId = DB::table('dsa_front_m_case_master')->where('case_id', $this->request->appId)->get()[0]->created_by; 
                        $smDetails = DB::table('master_employee')->where('employee_id',$smEmployeeId)->get();
                    }
                    // if ($this->request->log) {
                    //     dd($smDetails);
        
                    // }
                    if($this->request->isRpOnboard){
                        $this->addcaseRecord($this->request->appId,$isSelectAdvisory,$smDetails,$this->request->dsa_no); 
                    } else {
                        $this->addcaseRecord($this->request->appId,$isSelectAdvisory,$smDetails); 
                    }

                } else {
                    return response()->json([
                        'Status'=> 500,
                        'message' => 'Application Case details already submitted'
                    ], 200);
                }
            } 

        DB::commit();
            return response()->json([
                'Status'=> 200,
                'message' => 'Application Case details updated'
            ], 200);

        } catch (\Exception $e) {
            DB::rollback();
            // dd($e->getMessage());
            return response()->json([
                'Status' => 500,
                'message' => $e->getMessage()
            ], 400);
        }
    }

