    public function getCibilScoreStatus(){
        $this->validate($this->request, [
            'firstName'=>'required',
            'lastName'=>'required',
            'panNumber' => 'required',
            'streetAddress'=>'required',
            'city'=>'required',
            'postalCode'=>'required',
            'dateOfBirth'=>'required',
            'number'=>'required',
            'email'=>'required',
            'gender'=>'required'
        ]);
        Log::info("B2D Cibil score request: ".print_r($this->request->getContent(), true));
        try {
            
            $randomUserKey='DSA_CIBIL_REQUEST'.Carbon::now()->format('YmdHis');
            $Region=DB::table('dsa_front_m_pin_code_mapping')->where('pincode',$this->request->postalCode)->value('state_code');
            if(strtolower($this->request->gender)=="female"){
                $Gender='Female';
            }else if(strtolower($this->request->gender)=="male"){
                $Gender="Male";
            }else{
                $Gender="Transgender";
            }
            // Change as per new UAT config
            // $client = new \GuzzleHttp\Client([
            //     'headers' => [
            //         'Content-Type' => 'application/json',
            //         'apikey' => 'l738ba78a96b5844efb0f2716a5c1174e2',
            //         'cust-ref-id'=>'HF6362',
            //         'Host'=>'https://api.transunioncibil.com',
            //     ],//,'ezcblprod#2220'
            //     'cert'=>'D:/Certificate/cibil/ezcibil_adityabirlacapital_com.p12',//need to add prod certificate
            //     'curl'=>[CURLOPT_SSLCERTTYPE=>'P12'], 
            //     'base_uri'=>'https://api.transunioncibil.com/',
            //     'verify'=>false,
            //     'proxy'=>''
            // ]);
    
            $client = new \GuzzleHttp\Client([
                'headers' => [
                    'Content-Type' => 'application/json',
                    // 'api_key' => '06ecd9d4b9d13bb3204b2207f8b1abc5'
                ],
                'verify' => false
            ]);
            // Change as per new UAT config
            $response = $client->post(
                'https://ezgatewayuat.insideabc.com/consumer/dtc/v4/fulfilloffer',//Server
                ['body' =>'{
                    "FulfillOfferRequest": {
                    "ProductConfigurationId": "ABHFL01",
                    "SiteName": "ABHFL",
                    "AccountName": "GCVD_ABHFL",
                    "AccountCode": "R0NWRF9BQkhGTA",
                    "ClientKey":"'.$randomUserKey.'",
                    "RequestKey":"'.$randomUserKey.'",
                    "PartnerCustomerId":"'.$randomUserKey.'",
                    "CustomerInfo": {
                        "Name": {
                        "Forename":"'.$this->request->firstName.'",
                        "Surname":"'.$this->request->lastName.'"
                        },
                        "IdentificationNumber": {
                        "IdentifierName": "TaxId",
                        "Id":"'.$this->request->panNumber.'"
                        },
                        "Address": {
                        "StreetAddress": "'.$this->request->streetAddress.'",
                        "City": "'.$this->request->city.'",
                        "PostalCode": "'.$this->request->postalCode.'",
                        "Region": "'.$Region.'",
                        "AddressType": "01"
                        },
                        "DateOfBirth": "'.$this->request->dateOfBirth.'",
                        "PhoneNumber": {
                        "Number":"'.$this->request->number.'"
                        },
                        "Email":"'.$this->request->email.'",
                        "Gender": "'.$Gender.'"
                    },
                    "LegalCopyStatus": "Accept",
                    "UserConsentForDataSharing": "true"
                    }
                }']
            );
    
            $response = json_decode($response->getBody()->getContents());
            $response = $response->body;
            if(property_exists($response,'FulfillOfferResponse')
                && property_exists($response->FulfillOfferResponse,'FulfillOfferError')
                && property_exists($response->FulfillOfferResponse->FulfillOfferError,'ErrorStatus')
                && property_exists($response->FulfillOfferResponse->FulfillOfferError,'Failure')
                && $response->FulfillOfferResponse->FulfillOfferError->Failure != ""){
    
                $errorMessage = count(explode(':', $response->FulfillOfferResponse->FulfillOfferError->Failure)) > 1 
                            ? explode(':', $response->FulfillOfferResponse->FulfillOfferError->Failure)[1] 
                            : $response->FulfillOfferResponse->FulfillOfferError->Failure;
    
                
                return response()->json([
                    'error'=>true,
                    'message' => $errorMessage,
                    "statusCode" => 400
                ], 400);
            }
    
            if (property_exists($response->{'FulfillOfferResponse'},'FulfillOfferError') && $response->{'FulfillOfferResponse'}->{'FulfillOfferError'}->{'Failure'}->{'FailureEnum'} == 'NO_HIT') {
                return response()->json(
                    [
                        'error'=>false,
                        'cibil_score' =>  -1, 
                        'cibil_request_key' => $randomUserKey, 
                        'message' =>  "CIBIL data not present as it is a NO HIT case."
                    ], 200);
            } else {
                return response()->json(
                    [
                        'error'=>false,
                        'cibil_request_key' => $randomUserKey, 
                        'status' =>  $response->FulfillOfferResponse->ResponseStatus,
                        'message'=>"CIBIL data exists"
                    ], 200);
            }
        } catch (\Exception $e) {
            DB::rollback();
            // dd($e->getMessage());
            return response()->json([
                'Status' => 500,
                'message' => $e->getMessage()
            ], 400);
        }
    }

