    public function uploadQueryLogDocument()// Update the endpoint for Production so that it accesses the DSAFront controller instead of DSA controller
    {
        // dd('$this->request ',$this->request);
        // $user = $this->request->auth;
        $this->validate($this->request, [
            'caseId' => 'required',
            'qid' => 'required',
            'file' => 'required'
        ]);
        if (env('STORAGE_LOCATION') == 'FILE_SYSTEM') {
            //save docs
            $destinationPath = 'uploads/DSA/Query_Attachment/';
            $fileInitials = date('YmdHis') . '_' . $this->randomCode(6);
 
            $file = $this->request->file('file');
 
            $name = $this->request->file->getClientOriginalName();
            $fileSize = $this->request->file->getSize();
            $contentType = $this->request->file->getMimeType();
 
            $file->move($destinationPath, $fileInitials . '.' . $file->getClientOriginalExtension());
            $filePath = $fileInitials . '.' . $file->getClientOriginalExtension();
            try {
                DB::table('dsa_t_query_attachment')->insert([
                    'dsa_case_id' => $this->request->caseId,
                    'qid' => $this->request->qid,
                    'name' => $name,
                    'path' => $filePath,
                    'fileSize' => $fileSize,
                    'contentType' => $contentType,
                    // 'created_by' => $user->employee_id,
                    'storage_location' => env('STORAGE_LOCATION')
                ]);
            } catch (\Exception $e) {
 
                DB::rollback();
                dd("error--" . $e->getMessage());
                $errorCode = $e->errorInfo[1];
                return response()->json([
                    'message' => 'Please contact administrator.' . $e
                ], 400);
            }
        } else {
            DB::table('dsa_t_query_attachment')->insert([
                'dsa_case_id' => $this->request->caseId,
                'qid' => $this->request->qid,
                'name' => $this->request->file->getClientOriginalName(),
                'path' => base64_encode(file_get_contents($this->request->file('file'))),
                'fileSize' => $this->request->file->getSize(),
                'contentType' => $this->request->file->getMimeType(),
             //    'created_by' => $user->employee_id,
                'storage_location' => env('STORAGE_LOCATION')
 
            ]);
        }
 
        return response()->json([
            'message' => 'Attachment\'s saved.'
        ], 200);
    } 

    public function getsingleQueryDetails() // Update the endpoint for Production so that it accesses the DSAFront controller instead of DSA controller
   {
    // $user = $this->request->auth;
    
    $this->validate($this->request, [
        'qID' => 'required',
    ]);

    $queryData = DB::table('dsa_case_query_details as dcr')
    ->leftJoin('master_employee as me', 'me.employee_id', '=', 'dcr.assign_to')
    ->select('dcr.*','me.employee_name')
    ->where('dcr.query_id', $this->request->qID)->get();


    $querydocumentData = DB::table('dsa_t_query_attachment')
    ->where('qid', $this->request->qID)->get();
        return response()->json([
            'Status'=> 200,
            'queryData'=>$queryData,
            'querydocumentData'=>$querydocumentData,
            'message' => 'Query details found',

 
        ], 200); 

   }


