            ->where(function ($checkMobileNo) use($phoneno,$emailId){
                $checkMobileNo->where(function($q) use($phoneno,$emailId){
                    $q->where('phone_no',  $phoneno)
                    ->orWhere('email_id',  $emailId);
                })->where('is_rejected','0');
            })->count();

