                                'legal_option' => $kycDetails['legal_option'],
                                'legal_description' => $kycDetails['legal_description'],
                                "pan_verify_flag"=> $kycDetails['pan_verify_flag'],
                                "adhar_verify_flag"=> $kycDetails['adhar_verify_flag'],
                                'salution' => $individualPartnerDetails['salution'],
                                'date_of_birth' => $individualPartnerDetails['date_of_birth'],
                                'mother_name' => $individualPartnerDetails['mother_name'],
                                'gender' => $individualPartnerDetails['gender'],
                                'date_of_incorporation' => $individualPartnerDetails['date_of_incorporation'],
                                'father_name'=>$individualPartnerDetails['father_name'],
                                'applicant_experience'=>$individualPartnerDetails['applicant_experience'],
                                'ifsc_code' => $bankDetails['ifsc_code'],
                                'account_number' => $bankDetails['account_number'],
                                'bank_name' => $bankDetails['bank_name'],
                                'branch_name' => $bankDetails['branch_name'],
                                'no_of_years' => $bankDetails['no_of_years'],
                                'account_type' => $bankDetails['account_type'],
                                'account_holder_name' => $bankDetails['account_holder_name'],
                                "account_holder_name_penny_drop"=> $bankDetails['account_holder_name_penny_drop'],
