                                        'created_by'=>1,
                                        "cibil_consent_check"=>$value['cibil_consent_check'],
                                        "cibil_score" =>$value['cibil_score']
                                    ]);
                                }
                            }
            
                            if(count($this->request->addressDetails) > 0){
                                foreach ($this->request->addressDetails as $key => $value) {
                                    DB::table('dsa_front_t_case_address')->insert([
                                        'case_id' => $caseId,
                                        'address_type' => $value['address_type'],
                                        'addressline1' => $value['addressline1'],
                                        'addressline2' => $value['addressline2'],
                                        'pincode' => $value['pincode'],
                                        'area' => $value['area'],
                                        'landmark' => $value['landmark'],
                                        'city' => $value['city'],
                                        'district' => $value['district'],
                                        'state' => $value['state'],
                                        'country' => $value['country'],
                                        'resident_type' => $value['resident_type'],
                                        'created_by'=>1
                                    ]);
                                }
                            }
            
                            if(count($this->request->documentDetails) > 0){
                                foreach ($this->request->documentDetails as $key => $value) {
                                    DB::table('dsa_front_t_case_attachment')->insert([
                                        'case_id' => $caseId,
                                        'document_id' => $value['document_id'],
                                        'name' => $value['name'],
                                        'path' => $value['path'],
                                        'fileSize' => $value['fileSize'],
                                        'contentType' => $value['contentType'],
                                        'dms_id' => $value['dms_id'],
                                        'created_by'=>1
                                    ]);
                                }
                            }
            
                            if(count($this->request->referenceDetails) > 0){
                                foreach ($this->request->referenceDetails as $key => $value) {
                                    DB::table('dsa_front_t_case_reference')->insert([
                                        'case_id' => $caseId,
