                                        'reference_phone_no' => $value['reference_phone_no'],
                                        'reference_email' => $value['reference_email'],
                                        'reference_works_with' => $value['reference_works_with'],
                                        'reference_office_email' => $value['reference_office_email'],
                                    ]);
                                }
                            }
    
                            // $applicationNumber = $this->addcaseRecord($caseId,false,collect($smDetails)->toArray(),$dsacode);
                            $applicationNumber = $this->addcaseRecord($caseId,false,[$smDetails],$dsacode);
                            
                            return response()->json([
                                'Status'=> 200,
                                'message' => 'Application Case details submitted',
                                "application_number"=> $applicationNumber,
                                "sm_employee_code"=> $smDetails->employee_code,
                                "sm_employee_name"=> $smDetails->employee_name,
                                "sm_employee_email"=> $smDetails->email_id,
                                "sm_employee_phone_number"=> $smDetails->contact_number,
                                "a3s_agent_code"=> $dsacode
                            ], 200);
                        } else {
                            return response()->json([
                                'error'=>true,
                                'status'=> 400,
                                'message' => 'Failed to create '.$basicDetails['partner_type'].' code.',
                            ], 200);
                        }

                    } else {
                        return response()->json([
                            'error'=>true,
                            'status'=> 400,
                            'message' => 'There are no SM present in the entered branch!',
                        ], 200);
                    }
                } else {
                    return response()->json([
                        'error'=>true,
                        'status'=> 400,
                        'message' => 'Entered branch name is not present!',
                    ], 200);
                }
                

                // dd(DB::table("dsa_front_m_partner")->where("phone_no",$phoneno)->get());
                
            } else {
                return response()->json([
                    'error'=>true,
                    'status'=> 400,
                    'message' => 'Partner is already added.',
                ], 200);
            }
        } catch (\Exception $e) {
            DB::rollback();
            // dd($e->getMessage());
            return response()->json([
                'Status' => 500,
                'message' => $e->getMessage()
            ], 400);
        }
    }

    public function approveB2DTraining(){
        try {
            $this->validate($this->request, [
                'mobile_no' => 'required',
            ]);
            // dd($this->request->mobile_no);

            $partnerDetails = DB::table('dsa_front_m_partner')
                // ->where('partner_id', $this->request->partnerId)
                ->where('phone_no', $this->request->mobile_no)
                ->first();

            $dsaTrainingDetails = DB::table('dsa_front_t_resource_center_status')
                                  ->where('mobile', $this->request->mobile_no)
                                  ->get();
            // dd($partnerDetails, $dsaTrainingDetails);
            if($partnerDetails->partner_type != 'DSA'){
                return response()->json([
                    'status' => 400,
                    'message' => "Entered number is not a DSA application.",
                    'error' => true
                ], 400);
            } else if ($partnerDetails->sm_approve_training_consent == 1 || count($dsaTrainingDetails) > 0) {
                return response()->json([
                    'status' => 400,
                    'message' => "Training already approved.",
                    'error' => true
                ], 400);
            } else {
                DB::table('dsa_front_m_partner')
                    ->where('phone_no', $this->request->mobile_no)
                    ->update([
                        'sm_approve_training_consent' => 1,
                        'sm_approve_training_consent_datetime' => Carbon::now()
                    ]);

                DB::table('dsa_front_t_resource_center_status')->updateOrInsert(
                    ['mobile' => $this->request->mobile_no],
                    ['mobile' => $this->request->mobile_no, 'status' => 'Completed']
                );
                return response()->json([
                    'status' => 200,
                    'message' => "Training Approved.",
                    'error' => false
                ], 200);
            }
        } catch (\Exception $e) {
            return response()->json([
                'status' => 400,
                'message' => $e->getMessage(),
                'error' => true
            ], 400);
        }
    }

    public function dsaUpdateSmMappingSchedular(){
        try {
            Log::info("Deactivated SM Mapping updation schedular started");

            $deactivatedSmList = DB::table('master_employee')
                                 ->where("deletion_flag","1")
                                 ->whereNotNull('L1')
                                 ->get();

            // dd($deactivatedSmList);
            foreach ($deactivatedSmList as $key => $value) {
                Log::info("Value ".$key. " " . json_encode($value));
                // dsa_front_m_partner
                $dsaList = DB::table("dsa_front_m_partner")->where("created_by",$value->employee_id)->where("onboarding_type","B2D")->pluck("phone_no")->toArray();

                Log::info("dsa_front_m_partner list for SM ".$value->employee_code . " " . json_encode($dsaList));
                
                $L1Details = DB::table("master_employee")->where("employee_code",$value->L1)->get();
                Log::info("L1 for SM ".$L1Details[0]->employee_code);
                
                if(count($dsaList) > 0){
                    Log::info("Partner list ".json_encode($dsaList));
                    
                    DB::table("dsa_front_m_partner")
                    ->whereIn("phone_no",$dsaList)
                    ->update([
                        'created_by' => $L1Details[0]->employee_id
                    ]);
                } else {
                    Log::info("Partner list not present");
                }

                // dsa_front_m_case_master onboarding_type
                $dsaCaseMasterList = DB::table("dsa_front_m_case_master")->where("created_by",$value->employee_id)->where("onboarding_type","B2D")->pluck("phone_number")->toArray();

                Log::info("dsa_front_m_case_master list for SM ".$value->employee_code . " " . json_encode($dsaCaseMasterList));
                
                $L1Details = DB::table("master_employee")->where("employee_code",$value->L1)->get();
                Log::info("L1 for SM ".$L1Details[0]->employee_code);
                // dd($dsaCaseMasterList);
                if(count($dsaCaseMasterList) > 0){
                    Log::info("Partner case master list ".json_encode($dsaCaseMasterList));
                    
                    DB::table("dsa_front_m_case_master")
                    ->whereIn("phone_number",$dsaCaseMasterList)
                    ->update([
                        'created_by' => $L1Details[0]->employee_id
                    ]);
                } else {
                    Log::info("Partner case master list not present");
                }

                // dsa_m_case source
                $dsaMCaseList = DB::table("dsa_m_case")->where("created_by",$value->employee_id)->where("source","B2D")->pluck("mobile_no")->toArray();

                Log::info("dsa_m_case list for SM ".$value->employee_code . " " . json_encode($dsaMCaseList));
                
                $L1Details = DB::table("master_employee")->where("employee_code",$value->L1)->get();
                Log::info("L1 for SM ".$L1Details[0]->employee_code);
                // dd($dsaMCaseList);
                if(count($dsaMCaseList) > 0){
                    Log::info("Partner m case list ".json_encode($dsaMCaseList));
                    
                    DB::table("dsa_m_case")
                    ->whereIn("mobile_no",$dsaMCaseList)
                    ->update([
                        'created_by' => $L1Details[0]->employee_id
                    ]);
                } else {
                    Log::info("Partner m case list not present");
                }
            }

            Log::info("Deactivated SM Mapping updation schedular stopped");

        } catch (\Exception $e) {
            DB::rollback();
            Log::info("Catch block error ". json_encode($e));
            return response()->json([
                'Status' => 500,
                'message' => $e->getMessage()
            ], 400);
        }
    }

